//! Emits C and Rust source from typed Spass modules.

pub mod abi;
pub mod call_index;
pub mod checkpoint_codegen;
pub mod runtime_sections;
pub mod test_codegen;

// The compile-time AST transformations live in their own crate: the
// optimiser reduces each `if_present` variant separately, and putting
// them here would make the two crates depend on each other in a cycle.
use spass_transform::{
    dispatch as dispatch_codegen, if_present as if_present_codegen, plan::ModulePlan,
};

use call_index::CallIndex;
use checkpoint_codegen::{
    body_has_suspension, split_at_checkpoints, state_struct_name, CheckpointPlan, StateSlotKind,
};
use runtime_sections::RuntimeSections;
use spass_infer::Range;
use spass_parser::ast::{BinOp, Block, CallArg, ConvKind, Expr, RangeDecl, Stmt, Type, UnaryOp};
use spass_semantic::{TypedFunc, TypedModule, TypedStruct};
use std::fmt::Write;
use thiserror::Error;

/// Errors produced by the code generator.
#[derive(Debug, Error)]
pub enum CodegenError {
    #[error("E006: codegen error at {span}: {message}")]
    TypeError { message: String, span: spass_lexer::Span },

    #[error("unsupported feature at {span}: {message}")]
    Unsupported { message: String, span: spass_lexer::Span },
}

pub type CodegenResult<T> = Result<T, CodegenError>;

// ============================================================================
// Public API
// ============================================================================

/// Top-level entry point. Walks the typed module and emits a C source
/// string. The caller is responsible for invoking the system C compiler
/// (see `spass-cli`) to produce a shared library.
pub fn generate_c(typed: &TypedModule) -> CodegenResult<String> {
    generate_c_with_plan(typed, None)
}

/// The same, but with a plan: the bodies the optimiser produced.
///
/// A function that is in the plan is emitted from the plan's body; a
/// function that is not is emitted from its source body, exactly as it
/// was before the optimiser existed.
pub fn generate_c_with_plan(
    typed: &TypedModule,
    plan: Option<&ModulePlan>,
) -> CodegenResult<String> {
    let mut out = String::new();
    out.push_str("/* Generated by spass-codegen. Do not edit. */\n");
    out.push_str("#include <stdint.h>\n");
    out.push_str("#include <stdbool.h>\n");
    out.push_str("#include <stddef.h>\n");
    out.push_str("#include <time.h>\n\n");

    // Runtime helpers - embedded verbatim. The runtime declares the
    // vec/mat typedefs and the corresponding built-ins
    // (`spass_dot3`, `spass_cross`,...) once. We rely on those
    // declarations here, so we do not redeclare the typedefs.
    out.push_str(spass_runtime::RUNTIME_C);
    // the list descriptor. It is a byte view plus an
    // element stride, so one struct serves `list<float>`,
    // `list<vec3>` and `list<list<int>>` alike. `static inline`
    // keeps the unused-function warning away from modules that do
    // not use a list at all.
    out.push_str(
        r#"
typedef struct { unsigned char* data; int32_t len; int32_t stride; } SpassList;
static inline double spass_list_check(int32_t index, int32_t len) {
    if (index < 0 || index >= len) {
        fprintf(stderr, "spass: list index %d out of range (length %d)\n", index, len);
        abort();
    }
    return 0.0;
}

/* random choice. An xorshift64 state seeded from the
* clock; `n` is the number of candidates. */
static uint64_t spass_random_state = 0;
static inline int32_t spass_random_index(int32_t n) {
    if (n <= 1) return 0;
    uint64_t x = spass_random_state;
    if (x == 0) {
        x = (uint64_t)time(0) ^ (uint64_t)(uintptr_t)&spass_random_state;
        if (x == 0) x = 0x9e3779b97f4a7c15ull;
    }
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    spass_random_state = x;
    return (int32_t)(x % (uint64_t)n);
}
static inline double spass_random_pick(const double* values, int32_t n) {
    return values[spass_random_index(n)];
}

/* `parallel` spawns one call per argument row. A row
* draws list parameters from the same index and repeats scalar
* parameters; every list must have the row count as its length. */
typedef struct {
    const SpassList* list; /* NULL for a scalar parameter */
    double scalar;
    int32_t is_int;
} SpassParArg;
typedef struct { uint64_t* ids; int32_t n; } SpassBatch;
static inline uint64_t spass_parallel_spawn_args(
    spass_spawn_fn thunk, const SpassParArg* params, int32_t nparams, int32_t ncalls
) {
    SpassBatch* b = (SpassBatch*)malloc(sizeof(SpassBatch));
    if (b == NULL) { fprintf(stderr, "spass: out of memory\n"); abort(); }
    b->n = ncalls;
    b->ids = (uint64_t*)malloc(sizeof(uint64_t) * (ncalls ? (size_t)ncalls : 1));
    double* row = (double*)malloc(sizeof(double) * (nparams ? (size_t)nparams : 1));
    if (b->ids == NULL || row == NULL) { fprintf(stderr, "spass: out of memory\n"); abort(); }
    for (int32_t i = 0; i < ncalls; ++i) {
        for (int32_t p = 0; p < nparams; ++p) {
            if (params[p].list != NULL) {
                const SpassList* l = params[p].list;
                if (l->len != ncalls) {
                    fprintf(stderr, "spass: parallel list lengths differ (%d vs %d)\n", l->len, ncalls);
                    abort();
                }
                const unsigned char* at = l->data + (size_t)i * (size_t)l->stride;
                row[p] = params[p].is_int ? (double)(*(const int32_t*)at) : *(const double*)at;
            } else {
                row[p] = params[p].scalar;
            }
        }
        b->ids[i] = spass_spawn(thunk, row, (uint32_t)nparams);
    }
    free(row);
    return (uint64_t)(uintptr_t)b;
}
static inline SpassList spass_parallel_await(uint64_t handle) {
    SpassBatch* b = (SpassBatch*)(uintptr_t)handle;
    if (b == NULL) { SpassList empty = { 0, 0, sizeof(double) }; return empty; }
    double* out = (double*)malloc(sizeof(double) * (b->n ? (size_t)b->n : 1));
    if (out == NULL) { fprintf(stderr, "spass: out of memory\n"); abort(); }
    for (int32_t i = 0; i < b->n; ++i) out[i] = spass_task_await(b->ids[i]);
    SpassList list = { (unsigned char*)out, b->n, sizeof(double) };
    free(b->ids);
    free(b);
    return list;
}
"#,
    );
    // spass playground runtime (s2d:/s3d:/spio:), embedded verbatim
    // from the standalone spass-playground crate sources. It is the
    // largest runtime section by far, so it is emitted only for the
    // programs that call into those namespaces.
    if RuntimeSections::detect(typed).playground {
        out.push_str(include_str!("../../spass-playground/src/playground.c"));
    }
    out.push_str("\n");
    // Value-domain encode: turn a `double` into the
    // domain's integer state index. The compiler knows the domain's
    // exact reciprocal `k = 1/step`, so the state is
    // `round((v - min) * k)`. Mirrors the Rust prelude's
    // `spass_enc_state` exactly, so both backends agree bit for bit.
    out.push_str(
        r#"
static inline double spass_enc_state(double v, double min, double k, double nstates) {
    double r = spass_round((v - min) * k);
    /* `!(r > 0.0)` holds for NaN, so a NaN input lands on state 0. */
    if (!(r > 0.0)) return 0.0;
    if (r > nstates - 1.0) return nstates - 1.0;
    return r;
}
"#,
    );
    out.push('\n');

    // Struct definitions.
    for s in &typed.structs {
        emit_struct(&mut out, s);
    }
    if !typed.structs.is_empty() {
        out.push('\n');
    }

    // Forward declarations. The C standard requires a declaration
    // before use, so a function that calls one defined later in the
    // file (e.g. a public entry that calls another public function
    // declared in a later `include`d file, or the hoisted
    // `ownclude` helper that is emitted after its enclosing
    // function) would otherwise be an implicit-declaration error.
    // Prototypes come from the same [`c_signature`] helper the
    // definitions use, so the two can never drift. State-machine
    // wrappers keep the original signature (only the runner is
    // private and locally declared inside the emit block).
    if !typed.functions.is_empty() {
        out.push_str("/* Forward declarations */\n");
        for func in &typed.functions {
            // A function the optimiser eliminated is not emitted, so it
            // gets no prototype either.
            if let Some(fp) = plan.and_then(|p| p.get(&func.name)) {
                if fp.variants.is_empty() {
                    continue;
                }
            }
            // `ponytail`: multi-return functions use an inline
            // anonymous struct as their return type; a prototype would
            // declare a *distinct* anonymous type and clash with the
            // definition ("conflicting types"). Hoisting the struct
            // into a named typedef is the upgrade path if a
            // call-before-definition ever matters for multi-return.
            if func.multi_returns.is_some() {
                continue;
            }
            if func.has_if_present {
                let _ = writeln!(
                    out,
                    "{};",
                    c_signature(
                        func,
                        &mangle_function_name_variant(
                            func,
                            if_present_codegen::Variant::Present
                        )
                    )
                );
                let _ = writeln!(
                    out,
                    "{};",
                    c_signature(
                        func,
                        &mangle_function_name_variant(
                            func,
                            if_present_codegen::Variant::Absent
                        )
                    )
                );
            } else {
                let _ = writeln!(out, "{};", c_signature(func, &mangle_function_name(func)));
            }
        }
        out.push('\n');
    }

    // Async spawn thunks: one worker wrapper per
    // spawn-compatible function, defined before any call site.
    emit_spawn_thunks_c(&mut out, typed);

    // Sequence ids + message pack/unpack helpers.
    emit_seq_helpers_c(&mut out, typed);

    // Function definitions.
    let index = CallIndex::build(typed);
    for func in &typed.functions {
        if body_has_suspension(&func.original.body.stmts) {
            // A function with `@checkpoint` or
            // `@await` becomes a state machine. The wrapper keeps
            // the original signature; a separate runner does the
            // actual work. The runtime exposes
            // `spass_task_new/resume/register/lookup` for this.
            // For `@await` the I/O still happens inline at the
            // `let v = spasio:input[...](...)` statement; the
            // state machine is wired up for future async
            // resumption but isn't strictly required for the
            // MVP's synchronous semantics.
            emit_state_machine_c(&mut out, func, typed, &index)?;
        } else if let Some(fp) = plan.and_then(|p| p.get(&func.name)) {
            // The optimised body. An empty variant list means the
            // function was eliminated: nothing is emitted for it.
            for (variant, body) in &fp.variants {
                let mangled = if func.has_if_present {
                    mangle_function_name_variant(func, *variant)
                } else {
                    mangle_function_name(func)
                };
                emit_function_with_mangled(
                    &mut out,
                    func,
                    typed,
                    &index,
                    &mangled,
                    &body.stmts,
                    &body.readonly,
                )?;
                out.push('\n');
            }
        } else if func.has_if_present {
            // a function with `if_present` is split
            // into two variants at codegen time. Both variants have
            // the same signature; the CLI dispatcher picks the
            // right one based on whether the gated parameter was
            // supplied. Internal Spass calls always use the
            // `present` variant (Spass has no "omit this argument"
            // syntax at call sites, so all params are always passed).
            emit_function_variant(&mut out, func, typed, &index, if_present_codegen::Variant::Present)?;
            out.push('\n');
            emit_function_variant(&mut out, func, typed, &index, if_present_codegen::Variant::Absent)?;
        } else {
            emit_function(&mut out, func, typed, &index)?;
        }
        out.push('\n');
    }

    Ok(out)
}

// ============================================================================
// Structs
// ============================================================================

fn emit_struct(out: &mut String, s: &TypedStruct) {
    let _ = writeln!(out, "typedef struct {{");
    for (fname, fty) in &s.fields {
        let _ = writeln!(out, "    {} {};", c_type_name(fty), fname);
    }
    let _ = writeln!(out, "}} {};", s.name);
}

/// Emit a C list literal with a known element type.
///
/// The literal's storage is a compound literal, so its lifetime is the
/// enclosing block - the same lifetime a local binding would have. A
/// list may not escape a function (the semantic pass rejects list
/// returns), which is what keeps that lifetime sound.
fn emit_list_lit_c(
    out: &mut String,
    elements: &[Expr],
    elem: &Type,
    cx: &mut Ctx<'_>,
) -> CodegenResult<()> {
    let elem_c = c_type_name(elem);
    if elements.is_empty() {
        let _ = write!(out, "((SpassList){{ 0, 0, sizeof({}) }})", elem_c);
        return Ok(());
    }
    // `(T[]){... }` is a C99 compound literal: it has the lifetime of
    // the enclosing block, which is exactly the lifetime a local list
    // binding needs.
    let _ = write!(out, "((SpassList){{ (unsigned char*)(({}[]){{ ", elem_c);
    for (i, e) in elements.iter().enumerate() {
        if i > 0 {
            out.push_str(", ");
        }
        emit_expr(out, e, cx)?;
    }
    let _ = write!(out, " }}), {}, sizeof({}) }})", elements.len(), elem_c);
    Ok(())
}

fn c_type_name(ty: &Type) -> String {
    match ty {
        Type::Float(_) => "double".to_string(),
        Type::Int(_) => "int32_t".to_string(),
        Type::Uint(_) => "uint32_t".to_string(),
        Type::Bool => "bool".to_string(),
        Type::String => "const char*".to_string(),
        // every list shares one descriptor. The element
        // type is carried by the code that casts `data`, which is the
        // only place that knows it (the AST is untyped).
        Type::List(_) => "SpassList".to_string(),
        // vector / matrix types. The typedefs are emitted
        // unconditionally at the top of the generated C file (see
        // `generate_c`) so these names always resolve.
        Type::Vec2(_, _) => "spass_vec2".to_string(),
        Type::Vec3(_, _, _) => "spass_vec3".to_string(),
        Type::Vec4(_, _, _, _) => "spass_vec4".to_string(),
        Type::Mat3 => "spass_mat3".to_string(),
        Type::Mat4 => "spass_mat4".to_string(),
        Type::Struct(name, _) => name.clone(),
        // a task handle is an opaque runtime id.
        Type::Task(_) => "uint64_t".to_string(),
    }
}

// ============================================================================
// Value-domain encoding
// ============================================================================
//
// A `Type::Float(Some(decl))` carries a value-domain. At the C ABI boundary
// the value is an unsigned integer of `bit_width` bits; the function body
// uses `double`. Encode/decode helpers are inlined at the call site.

/// Render a multi-return's anonymous struct type. Matches the layout used
/// by the destructuring logic in `emit_stmt` and the function-level return
/// type in `emit_function`.
///
/// Example: `[(float, _), (int, _)]` -> `struct { double _f0; int32_t _f1; }`.
fn multi_return_c_type(mr: &[Type]) -> String {
    let mut s = String::from("struct { ");
    for (i, t) in mr.iter().enumerate() {
        if i > 0 {
            s.push(' ');
        }
        s.push_str(&c_type_name(t));
        s.push(' ');
        s.push_str(&field_name(i));
        s.push(';');
    }
    s.push_str(" }");
    s
}

/// Field name used in the multi-return struct. The C and Rust emitters
/// share the same `_f<i>` convention so that one name works in both
/// targets (the Rust side never has to read a struct field, but if it
/// did, the name would be the same).
fn field_name(i: usize) -> String {
    format!("_f{}", i)
}

/// Return the span of an expression - a thin convenience used at error
/// sites that do not already have a span in scope.
fn expr_span(e: &Expr) -> spass_lexer::Span {
    e.span()
}

/// Emit a function call. `caller_name` is the user-visible name (used to
/// look up the callee in the module), `mangled` is the symbol to call,
/// `args` is the argument list. Centralising the call emission here lets
/// the destructuring logic share the same argument handling as the
/// regular call expression.
fn emit_call_with_args(
    out: &mut String,
    _caller_name: &str,
    mangled: &str,
    args: &[CallArg],
    cx: &mut Ctx<'_>,
) -> CodegenResult<()> {
    let _ = write!(out, "{}(", mangled);
    for (i, a) in args.iter().enumerate() {
        if i > 0 {
            out.push_str(", ");
        }
        emit_call_arg(out, _caller_name, i, a, cx)?;
    }
    out.push(')');
    Ok(())
}

/// Information about a value-domain-typed scalar. `None` when the type is
/// unconstrained (default `float`/`int`).
///
/// `ponytail`: `max`/`bits` are kept for diagnostics even though the
/// current codegen only needs `min`/`step`/`state_count`/`c_type`. The
/// compiler will surface them in E001/E010 messages later.
#[derive(Clone)]
#[allow(dead_code)]
pub(crate) struct ValueDomain {
    pub min: String, // rendered rational literal, e.g. "0.0" or "5.0/2.0"
    pub max: String,
    pub step: String,
    /// The exact reciprocal of `step` (`k = 1/step`), rendered as a
    /// float literal. E001 restricts the step to 1 or a negative power
    /// of 2 or 10, so `k` is always a positive integer that the
    /// compiler already knows exactly. Multiplying by `k` replaces the
    /// division by `step`: the divisor is exact instead of a decimal
    /// that binary floating point cannot represent, and a multiply is
    /// cheaper than a divide.
    pub k: String,
    /// The domain bounds as exact rationals. The call-site range
    /// checks compare the argument's inferred range against these, so
    /// the comparison happens in the rational domain and not in the
    /// rendered float literals.
    pub min_r: num_rational::Rational64,
    pub max_r: num_rational::Rational64,
    /// The step as an exact rational.
    pub step_r: num_rational::Rational64,
    pub bits: u32,
    pub state_count: u64,
    /// The C type at the C ABI boundary (e.g. `uint16_t`).
    pub c_type: String,
    /// The Rust type at the Rust ABI boundary (e.g. `u16`).
    pub rust_type: String,
}

/// If `ty` has a value-domain, return its encoding info. Returns `None`
/// for unconstrained types.
fn value_domain(ty: &Type) -> Option<ValueDomain> {
    let decl: &RangeDecl = match ty {
        Type::Float(Some(d)) | Type::Int(Some(d)) | Type::Uint(Some(d)) => d,
        _ => return None,
    };
    let range = Range::from_decl(decl, ty).ok()?;
    let states = range.state_count()?;
    let bits = range.bit_width();
    if bits == 0 || bits > 64 {
        return None;
    }
    let min = render_rational(&range.min);
    let max = render_rational(&range.max);
    let step = render_rational(&range.step);
    // `validate_step` (E001) has already accepted this step, so the
    // reciprocal is an exact positive integer. If it is not, the
    // domain is not one this encoder can represent exactly, and we
    // decline the whole domain rather than emit an inexact multiply.
    let inv = num_rational::Rational64::from_integer(1) / range.step.clone();
    if !inv.is_integer() || *inv.numer() <= 0 {
        return None;
    }
    let k = *inv.numer() as u64;
    let c_type = if bits <= 8 {
        "uint8_t".to_string()
    } else if bits <= 16 {
        "uint16_t".to_string()
    } else if bits <= 32 {
        "uint32_t".to_string()
    } else {
        "uint64_t".to_string()
    };
    let rust_type = if bits <= 8 {
        "u8".to_string()
    } else if bits <= 16 {
        "u16".to_string()
    } else if bits <= 32 {
        "u32".to_string()
    } else {
        "u64".to_string()
    };
    Some(ValueDomain {
        min,
        max,
        step,
        k: format!("{}.0", k),
        min_r: range.min.clone(),
        max_r: range.max.clone(),
        step_r: range.step.clone(),
        bits,
        state_count: states,
        c_type,
        rust_type,
    })
}

/// Render a `Rational64` as a Rust f64 expression. Mirrors
/// [`render_rational`], but the lossy case has to use Rust's cast
/// syntax rather than C's.
fn render_rational_rust(r: &num_rational::Rational64) -> String {
    let numer = *r.numer();
    let denom = *r.denom();
    let f = (numer as f64) / (denom as f64);
    if f.is_finite() && denom != 0 {
        let back_num = (f * (denom as f64)).round() as i64;
        if back_num == numer {
            if f.fract() == 0.0 {
                format!("{:.1}", f)
            } else {
                format!("{}", f)
            }
        } else {
            format!("(({} as f64) / ({} as f64))", numer, denom)
        }
    } else {
        "0.0".to_string()
    }
}

impl ValueDomain {
    /// The domain's minimum, rendered as a Rust expression.
    fn min_rs(&self) -> String {
        render_rational_rust(&self.min_r)
    }

    /// The domain's step, rendered as a Rust expression.
    fn step_rs(&self) -> String {
        render_rational_rust(&self.step_r)
    }
}

/// The value range of an expression, when the compiler can prove one.
/// Returns `(min, max)` as exact rationals, or `None` when the range
/// is unknown.
///
/// The range is what lets a call site drop the value-domain clamp: an
/// argument whose range is provably inside the callee's domain cannot
/// produce an out-of-range state index, so the clamp is dead code.
fn expr_value_range(
    expr: &Expr,
    cx: &Ctx<'_>,
) -> Option<(num_rational::Rational64, num_rational::Rational64)> {
    use num_rational::Rational64;
    match expr {
        Expr::FloatLit { value, .. } => Some((value.clone(), value.clone())),
        Expr::IntLit { value, .. } => {
            let r = Rational64::from_integer(*value);
            Some((r.clone(), r))
        }
        Expr::Ident { name, .. } => {
            let ty = lookup_local_type(name, cx)?;
            let vd = value_domain(&ty)?;
            Some((vd.min_r, vd.max_r))
        }
        _ => None,
    }
}

/// How a value-domain argument is passed at a call site.
enum ArgEncoding {
    /// The argument's range is provably inside the callee's domain, so
    /// the quantise cannot produce an out-of-range state index and the
    /// clamp is dead code.
    InDomain,
    /// The argument's range is unknown or reaches outside the domain:
    /// quantise and clamp.
    Clamped,
    /// The argument's range is provably disjoint from the callee's
    /// domain. The call is a program error, but the code is still
    /// emitted (clamped) so the diagnostic can point at the call.
    Disjoint,
}

/// Decide how to encode `arg` for a callee parameter with the value
/// domain `vd`.
fn classify_arg(arg: &Expr, vd: &ValueDomain, cx: &Ctx<'_>) -> ArgEncoding {
    let (lo, hi) = match expr_value_range(arg, cx) {
        Some(r) => r,
        // Unknown range: the conservative answer is to clamp.
        None => return ArgEncoding::Clamped,
    };
    if hi < vd.min_r || lo > vd.max_r {
        return ArgEncoding::Disjoint;
    }
    if lo >= vd.min_r && hi <= vd.max_r {
        ArgEncoding::InDomain
    } else {
        ArgEncoding::Clamped
    }
}

/// Emit the value-domain encode of a scalar expression into the
/// domain's integer state index, in the Rust ABI form.
///
/// `clamp` selects the clamped form (used wherever the value's range is
/// not known to lie inside the domain) from the clamp-free form (used
/// at a call site whose argument range the compiler proved to be
/// inside the domain, where the clamp is dead code).
fn emit_rust_encode<F>(out: &mut String, vd: &ValueDomain, clamp: bool, expr: F) -> CodegenResult<()>
where
    F: FnOnce(&mut String) -> CodegenResult<()>,
{
    if clamp {
        out.push_str("spass_enc_state((");
        expr(out)?;
        let _ = write!(
            out,
            ") as f64, {}, {}, {}.0) as {}",
            vd.min_rs(),
            vd.k,
            vd.state_count,
            vd.rust_type
        );
    } else {
        out.push_str("spass_round(((");
        expr(out)?;
        let _ = write!(
            out,
            " as f64) - {}) * {}) as {}",
            vd.min_rs(),
            vd.k,
            vd.rust_type
        );
    }
    Ok(())
}

/// Emit the value-domain encode of a scalar expression into the
/// domain's integer state index, in the C ABI form. Mirrors
/// [`emit_rust_encode`]: the two backends must agree bit for bit.
fn emit_c_encode<F>(out: &mut String, vd: &ValueDomain, clamp: bool, expr: F) -> CodegenResult<()>
where
    F: FnOnce(&mut String) -> CodegenResult<()>,
{
    if clamp {
        let _ = write!(out, "({})spass_enc_state((double)(", vd.c_type);
        expr(out)?;
        let _ = write!(out, "), {}, {}, {}.0)", vd.min, vd.k, vd.state_count);
    } else {
        let _ = write!(out, "({})spass_round(((double)(", vd.c_type);
        expr(out)?;
        let _ = write!(out, ") - {}) * {})", vd.min, vd.k);
    }
    Ok(())
}

/// Render a `Rational64` as a C double literal. We emit the value as
/// an f64 string (`0.0`, `0.5`, `2.5`,...). Rationals that are not
/// exactly representable in IEEE 754 (e.g. `1/3`) fall back to
/// `((double)N) / D` to keep the compile-time value exact.
fn render_rational(r: &num_rational::Rational64) -> String {
    let numer = *r.numer();
    let denom = *r.denom();
    let f = (numer as f64) / (denom as f64);
    // Use the rational form whenever the f64 round-trip would lose
    // information. `from_float` only exists for `Ratio<BigInt>` in
    // num-rational, so we check by re-multiplying the f64.
    if f.is_finite() && denom != 0 {
        let back_num = (f * (denom as f64)).round() as i64;
        if back_num == numer {
            // Lossless: emit a single double literal. Add `.0` for
            // integer values to make the type unambiguous in C.
            if f.fract() == 0.0 {
                format!("{:.1}", f)
            } else {
                format!("{}", f)
            }
        } else {
            // Lossy: keep the rational form to preserve exactness.
            let sign = if numer < 0 { "-" } else { "" };
            let abs_n = numer.unsigned_abs();
            format!("((double)({}) / (double)({}))", format!("{}{}", sign, abs_n), denom)
        }
    } else {
        "0.0".to_string()
    }
}

// ============================================================================
// Functions
// ============================================================================

fn emit_function(
    out: &mut String,
    func: &TypedFunc,
    module: &TypedModule,
    index: &CallIndex,
) -> CodegenResult<()> {
    let mangled = mangle_function_name(func);
    let readonly = no_readonly();
    emit_function_with_mangled(out, func, module, index, &mangled, &func.original.body.stmts, &readonly)
}

/// Emit one variant of an `if_present` function.
///
/// The `if_present` was already validated by the semantic pass (E016
/// ensures only one gated parameter, the gated parameter is a real
/// function parameter); here we transform the body so the variant
/// has no `if_present` statement left, and we emit it under the
/// variant-specific mangled name (`<base>_present` / `<base>_absent`).
fn emit_function_variant(
    out: &mut String,
    func: &TypedFunc,
    module: &TypedModule,
    index: &CallIndex,
    variant: if_present_codegen::Variant,
) -> CodegenResult<()> {
    let mangled = mangle_function_name_variant(func, variant);
    let body = if_present_codegen::transform_body(&func.original.body.stmts, variant);
    // `has_if_present` is `false` on the variant body - the transform
    // has already removed every `if_present` site - so a nested
    // `emit_function_variant` call would be a no-op. We don't recurse
    // anyway; the body we pass already has the right shape.
    let readonly = no_readonly();
    emit_function_with_mangled(out, func, module, index, &mangled, &body, &readonly)
}

/// The C return type for `func` - shared by the definition emitters
/// and the forward-declaration pass so the two can never drift.
/// A value-domain return exposes the encoded uintN type; the body
/// encodes the double result just before returning.
fn c_return_type(func: &TypedFunc) -> String {
    if let Some(vd) = func.return_type.as_ref().and_then(value_domain) {
        vd.c_type.clone()
    } else if let Some(rt) = &func.return_type {
        c_type_name(rt)
    } else if let Some(mr) = &func.multi_returns {
        // Multi-return: emit a struct of fields. (Multi-return value
        // domains are out of MVP scope; emit each as its plain type.)
        multi_return_c_type(mr)
    } else {
        "void".to_string()
    }
}

/// the linkage of a function is determined by its
/// visibility. Public functions get external linkage so the
/// runtime / CLI can call them by symbol; `fileclude` and
/// `ownclude` functions get internal (`static`) linkage so the
/// symbol never escapes the translation unit. The language
/// explicitly requires this: when another file includes this file,
/// `fileclude` functions do not enter the global namespace, and the same is
/// true for `ownclude` (the closure is a private detail of
/// the enclosing function, no public ABI for it).
fn c_linkage(func: &TypedFunc) -> &'static str {
    match func.original.visibility {
        spass_parser::ast::Visibility::Public => "",
        spass_parser::ast::Visibility::FilePrivate
        | spass_parser::ast::Visibility::OwnPrivate => "static ",
    }
}

/// The C parameter list for `func` (captures + params, no enclosing
/// parentheses) - shared by the definition emitters and the
/// forward-declaration pass so the two can never drift.
fn c_param_list(func: &TypedFunc) -> String {
    let mut out = String::new();
    // (`ownclude`): the hoisted closure receives the
    // captured values as plain (non-value-domain) leading
    // parameters. They are decoded-by-value: at definition time the
    // enclosing function's local of the matching type is passed
    // through, so the helper sees a stable `double` (or `int32_t`,
    // etc.) and never has to think about the original storage.
    // The names keep the same identifier as the source-side
    // binding so the closure body - which still references
    // `factor`, `base`, etc. - compiles unchanged.
    let mut first = true;
    if func.original.visibility == spass_parser::ast::Visibility::OwnPrivate {
        for (cap_name, cap_ty) in &func.captures {
            if !first {
                out.push_str(", ");
            }
            first = false;
            let _ = write!(out, "{} {}", c_type_name(cap_ty), cap_name);
        }
    }
    for p in &func.params {
        if !first {
            out.push_str(", ");
        }
        first = false;
        // Param ABI. Four shapes:
        // 1. value-domain in: `uintN_t __sp_in_<name>` (encoded)
        // 2. value-domain out: `uintN_t* __sp_out_<name>` (encoded slot)
        // 3. plain in: `T <name>` (the C type)
        // 4. plain out: `T* __sp_out_<name>` (slot)
        //
        // Out params are passed by pointer; the body
        // operates on a decoded `double` shadow of the same name and
        // writes back through the pointer on assignment. The name
        // is mangled to `__sp_out_<name>` so the body can refer to the
        // user-visible name without colliding with the pointer.
        if p.is_out {
            if let Some(vd) = value_domain(&p.ty) {
                let _ = write!(out, "{}* __sp_out_{}", vd.c_type, p.name);
            } else {
                let _ = write!(out, "{}* __sp_out_{}", c_type_name(&p.ty), p.name);
            }
        } else if let Some(vd) = value_domain(&p.ty) {
            let _ = write!(out, "{} __sp_in_{}", vd.c_type, p.name);
        } else {
            let _ = write!(out, "{} {}", c_type_name(&p.ty), p.name);
        }
    }
    if first {
        // No params (and no captures): still emit `void` for an
        // explicit no-arg signature. An ownclude with no captures
        // is legal (it's just a plain helper), and the same
        // `void` shape still applies.
        out.push_str("void");
    }
    out
}

/// The full C signature line for `func` up to (but excluding) the
/// body terminator: `{linkage}{ret} {mangled}({params})`. The
/// definition emitters append `" {"`, the forward-declaration pass
/// appends `";"`.
fn c_signature(func: &TypedFunc, mangled: &str) -> String {
    format!(
        "{}{} {}({})",
        c_linkage(func),
        c_return_type(func),
        mangled,
        c_param_list(func)
    )
}

/// Shared body of `emit_function` / `emit_function_variant`. The
/// `mangled` is the public symbol name and `body` is the statement
/// list to emit. Splitting out the inner function keeps the public
/// wrappers small and lets the variant path reuse the entire code
/// path with just a different symbol and a transformed body.
fn emit_function_with_mangled(
    out: &mut String,
    func: &TypedFunc,
    module: &TypedModule,
    index: &CallIndex,
    mangled: &str,
    body: &[Stmt],
    readonly: &std::collections::HashSet<String>,
) -> CodegenResult<()> {
    out.push_str(&c_signature(func, mangled));
    out.push_str(" {\n");

    // Local mirrors of the signature pieces the default-return path
    // needs (kept in lock-step via `c_signature`'s shared helpers).
    let ret_value_domain = func.return_type.as_ref().and_then(value_domain);
    let ret_ty = c_return_type(func);

    // Body.
    let mut cx = Ctx::new(func, module, Some(index), body, readonly);
    for p in &func.params {
        // Incoming in-params: decode value-domain uintN to a `double`
        // shadow of the user-visible name.
        if !p.is_out {
            if let Some(vd) = value_domain(&p.ty) {
                let _ = writeln!(out, "    double {} = {} + {} * __sp_in_{};",
                                 p.name, vd.min, vd.step, p.name);
            }
        } else {
            // Out-params: declare a `double` shadow that is read+written
            // by the body, then mirrored through the caller's slot.
            // For value-domain out params, decode the encoded slot into
            // the shadow; for plain out params, dereference the pointer.
            if let Some(vd) = value_domain(&p.ty) {
                let _ = writeln!(out, "    double {} = {} + {} * (*__sp_out_{});",
                                 p.name, vd.min, vd.step, p.name);
            } else {
                let _ = writeln!(out, "    double {} = *__sp_out_{};",
                                 p.name, p.name);
            }
            // Track this name so Stmt::Assign can mirror the local back
            // into the caller's slot.
            cx.out_params.insert(p.name.clone(), p.ty.clone());
        }
    }
    for stmt in body {
        emit_stmt(out, stmt, &mut cx)?;
    }

    // Ensure non-void functions have a return path. If a return is missing
    // we add a default return at the end of the body.
    if !cx.has_return {
        if let Some(vd) = &ret_value_domain {
            // The implicit `return 0;` is a uintN 0, not a double 0.0.
            // The user is expected to return explicitly when the return
            // type is value-domain-encoded; otherwise the function
            // returns 0 (state N=0, i.e. min).
            let _ = writeln!(out, "    return 0; /* implicit: min = {} */", vd.min);
        } else {
            match (&func.return_type, &func.multi_returns) {
                (Some(_), _) => {
                    let _ = writeln!(out, "    return 0;");
                }
                (_, Some(mr)) => {
                    let _ = write!(out, "    return ({} ){{0}};\n", ret_ty);
                    let _ = mr.len();
                }
                (None, None) => {}
            }
        }
    }

    out.push_str("}\n");
    Ok(())
}

// ============================================================================
// State machine emit
//
// A function whose body uses `@checkpoint name` is turned into a
// wrapper + runner pair. The wrapper keeps the original signature
// (so callers see the same ABI as a regular function); the runner
// does the actual work and yields control at every checkpoint by
// returning to the wrapper. Cross-function `@resume name` works
// because every checkpointed function registers its task under
// the checkpoint name in a global name->task table (see runtime.c).
// ============================================================================

/// Emit a state machine for a checkpointed function: the public
/// wrapper plus the private runner. The wrapper takes the original
/// signature, allocates a task, copies in the parameters, runs the
/// state machine to completion, and returns the result.
fn emit_state_machine_c(
    out: &mut String,
    func: &TypedFunc,
    module: &TypedModule,
    index: &CallIndex,
) -> CodegenResult<()> {
    let mangled = mangle_function_name(func);
    let plan = CheckpointPlan::build(func, &mangled);
    let state_ty = state_struct_name(&mangled);

    // --- 1. The state struct -------------------------------------------
    // A flat byte layout the runner indexes into via offsetof-free
    // pointer arithmetic. The MVP uses 8 bytes for every slot.
    let _ = writeln!(out, "typedef struct {{");
    for slot in &plan.layout.slots {
        let _ = writeln!(
            out,
            "    double {}; /* {} @ {} */",
            slot.name, slot.name, slot.offset
        );
    }
    let _ = writeln!(out, "}} {};", state_ty);
    out.push('\n');

    // --- 2. Forward-declare the runner ---------------------------------
    // The wrapper calls the runner by name; the runner is emitted
    // below the wrapper.
    let _ = writeln!(out, "static void {}(spass_task_t* t);", plan.runner);
    out.push('\n');

    // --- 3. The wrapper ------------------------------------------------
    // The wrapper's signature mirrors the original function so
    // callers don't know this is a state machine. Value-domain
    // params and out params are encoded/decoded exactly the same
    // as in `emit_function` (so the public ABI is stable).
    let ret_value_domain = func.return_type.as_ref().and_then(value_domain);
    let ret_ty = if let Some(vd) = &ret_value_domain {
        vd.c_type.clone()
    } else if let Some(rt) = &func.return_type {
        c_type_name(rt)
    } else if let Some(mr) = &func.multi_returns {
        multi_return_c_type(mr)
    } else {
        "void".to_string()
    };
    let _ = write!(out, "{} {}(", ret_ty, mangled);
    let mut first = true;
    for p in &func.params {
        if !first {
            out.push_str(", ");
        }
        first = false;
        if p.is_out {
            if let Some(vd) = value_domain(&p.ty) {
                let _ = write!(out, "{}* __sp_out_{}", vd.c_type, p.name);
            } else {
                let _ = write!(out, "{}* __sp_out_{}", c_type_name(&p.ty), p.name);
            }
        } else if let Some(vd) = value_domain(&p.ty) {
            let _ = write!(out, "{} __sp_in_{}", vd.c_type, p.name);
        } else {
            let _ = write!(out, "{} {}", c_type_name(&p.ty), p.name);
        }
    }
    if first {
        out.push_str("void");
    }
    out.push_str(") {\n");

    // Allocate the task with the function's full state size. The
    // refcount starts at 1; we release on the normal exit path.
    let _ = writeln!(
        out,
        "    spass_task_t* t = spass_task_new({}, {});",
        plan.layout.state_size, plan.runner
    );

    // Copy in-params into the state block. For value-domain params
    // we decode the uintN ABI to a double; for plain params we
    // cast the C type to double. Out params are not stored in the
    // state block (they live in the caller's slot); the wrapper
    // writes the result through the pointer after the runner
    // completes.
    for p in &func.params {
        if p.is_out {
            continue;
        }
        let offset = plan
            .layout
            .offset_of(&p.name)
            .expect("param slot exists in layout");
        if let Some(vd) = value_domain(&p.ty) {
            let _ = writeln!(
                out,
                "    *((double*)(((uint8_t*)t) + {} + offsetof(spass_task_t, state_data))) = {} + {} * __sp_in_{};",
                offset, vd.min, vd.step, p.name
            );
        } else {
            let _ = writeln!(
                out,
                "    *((double*)(((uint8_t*)t) + {} + offsetof(spass_task_t, state_data))) = (double)({});",
                offset, p.name
            );
        }
    }

    // Drive the state machine. The runner is re-entrant: it
    // returns at every checkpoint (and at every cross-function
    // @resume hop), and the wrapper loops `spass_task_resume`
    // until the task marks itself complete. Without the loop a
    // single-checkpoint function would return immediately at the
    // first suspension site and the wrapper would read the
    // not-yet-written return slot.
    //
    // `ponytail`: a more aggressive form would use Duff's device
    // here too (no per-iteration branch on `completed`) but the
    // MVP has at most a handful of slices per function so a plain
    // while is fine.
    out.push_str("    while (!t->completed) { spass_task_resume(t); }\n");

    // Pull the return value out of the state block and encode it
    // back to the ABI type. We do the encoding here (not in the
    // runner) so the runner doesn't have to know about value
    // domains.
    if let Some(ret_name) = &plan.return_slot {
        let offset = plan
            .layout
            .offset_of(ret_name)
            .expect("return slot exists in layout");
        let _ = writeln!(
            out,
            "    double __sp_ret = *((double*)(((uint8_t*)t) + {} + offsetof(spass_task_t, state_data)));",
            offset
        );
        // Multi-return MVP: not yet supported in state machines.
        // The user gets a clear codegen error before reaching this
        // branch.
        if let Some(mr) = &func.multi_returns {
            return Err(CodegenError::Unsupported {
                message: format!(
                    "multi-return state machines are not supported in MVP (function `{}` returns {} values)",
                    func.name,
                    mr.len()
                ),
                span: func.original.span.clone(),
            });
        }
        let _ = writeln!(out, "    spass_task_complete(t);");
        let _ = writeln!(out, "    spass_task_release(t);");
        if let Some(vd) = &ret_value_domain {
            let _ = writeln!(
                out,
                "    return (({})spass_enc_state((double)(__sp_ret), {}, {}, {}.0));",
                vd.c_type, vd.min, vd.k, vd.state_count
            );
        } else if func.return_type.is_some() {
            let _ = writeln!(out, "    return __sp_ret;");
        }
    } else {
        // void / out-only function: just mark complete and release.
        let _ = writeln!(out, "    spass_task_complete(t);");
        let _ = writeln!(out, "    spass_task_release(t);");
    }

    // Mirror out-params back to the caller's slots. The runner
    // wrote the final shadow value into the state block; we copy
    // it out and (if value-domain) encode it.
    for p in &func.params {
        if !p.is_out {
            continue;
        }
        let offset = plan
            .layout
            .offset_of(&p.name)
            .expect("out-param slot exists in layout");
        let _ = writeln!(
            out,
            "    double __sp_out_v = *((double*)(((uint8_t*)t) + {} + offsetof(spass_task_t, state_data)));",
            offset
        );
        if let Some(vd) = value_domain(&p.ty) {
            let _ = writeln!(
                out,
                "    *__sp_out_{} = (({})spass_enc_state((double)(__sp_out_v), {}, {}, {}.0));",
                p.name, vd.c_type, vd.min, vd.k, vd.state_count
            );
        } else {
            let _ = writeln!(out, "    *__sp_out_{} = __sp_out_v;", p.name);
        }
    }

    out.push_str("}\n\n");

    // --- 4. The runner -------------------------------------------------
    // The runner is a `switch` on `t->state_id`. Each case body is
    // the source-level body split at every `@checkpoint`. When a
    // checkpoint is reached we set `t->state_id` to the next case,
    // register the task so cross-function @resume can find us, and
    // return. The Duff's-device fall-through means re-entry lands
    // at the next case, not at the checkpoint site.
    let _ = writeln!(out, "static void {}(spass_task_t* t) {{", plan.runner);
    let _ = writeln!(
        out,
        "    {}* state = ({}*)t->state_data;",
        state_ty, state_ty
    );
    // Duff's device: jump into the right case. The first call lands
    // at case 0 (function entry); subsequent resumes land at the
    // saved state_id, which corresponds to a case label.
    let _ = writeln!(out, "    switch (t->state_id) {{");
    let _ = writeln!(out, "        case 0: {{");

    let slices = split_at_checkpoints(&func.original.body.stmts);
    let last_idx = slices.len().saturating_sub(1);
    for (i, slice) in slices.iter().enumerate() {
        // Build a Ctx that runs in runner mode. The locals are
        // pulled from the state block, not declared on the stack.
        let mut cx = Ctx::new(func, module, Some(index), &func.original.body.stmts, no_readonly());
        cx.runner_state = Some(RunnerCtx { plan: &plan });
        // First slice (i == 0) is the entry body; we already
        // opened `case 0: {` above. Subsequent slices become
        // their own `case N: {... }` blocks.
        if i > 0 {
            let _ = writeln!(out, "        case {}: {{", i);
        }
        for stmt in slice {
            emit_stmt(out, stmt, &mut cx)?;
        }
        // The last slice may fall off the end without returning
        // (e.g. a missing explicit return). Close out the case
        // and mark complete. If the body's last top-level stmt is
        // already a `return;`, the sentinel would be unreachable
        // - skip it. `ponytail`: C compilers don't warn on
        // unreachable code by default, but emitting a clean slice
        // is cheap insurance and keeps the C/Rust outputs in sync.
        let slice_ends_with_return = slice
            .last()
            .map(|s| matches!(s, Stmt::Return { .. }))
            .unwrap_or(false);
        if !slice_ends_with_return {
            let _ = writeln!(out, "            spass_task_complete(t);");
            let _ = writeln!(out, "            return;");
        }
        // Close this case so the next `case N+1:` can begin.
        // We do NOT `break`; the runner relies on the checkpoint
        // site to set the next state and return early. The close
        // is just to balance braces.
        if i < last_idx {
            let _ = writeln!(out, "        }}");
        }
    }
    // Close the final case and the switch.
    let _ = writeln!(out, "        }}");
    let _ = writeln!(out, "    }}");
    // Final cleanup: mark complete (the body might fall off the
    // end without hitting an explicit `return;`).
    let _ = writeln!(out, "    spass_task_complete(t);");
    out.push_str("}\n");

    let _ = module;
    Ok(())
}

#[derive(Default)]
pub(crate) struct Ctx<'a> {
    /// The `let` bindings currently in scope. Stored for future use (e.g.
    /// shadowing diagnostics). MVP: every binding becomes a C local.
    locals: Vec<String>,
    /// True once we have emitted a `return;` statement at the end of the
    /// function body, so we know whether to inject a fallback return.
    has_return: bool,
    /// The current module - used at call sites to look up the mangled
    /// name of a user-defined function. A reference, not a clone: the
    /// context is built once per emitted function, and cloning the
    /// module (with every function body) each time made codegen
    /// quadratic in the function count.
    module: Option<&'a TypedModule>,
    /// The function we are currently emitting. Used by `lookup_local_type`
    /// to resolve the type of an identifier in the body - the previous
    /// implementation used `module.functions.first`, which is wrong
    /// when the body belongs to a function other than the first one
    /// in source order.
    current_func: Option<&'a TypedFunc>,
    /// If the function's return type carries a value-domain, the encoded
    /// (min, step, state_count) of that domain. Used at every `return`
    /// to encode the body result back to the ABI uintN type.
    ret_value_domain: Option<ValueDomain>,
    /// If the enclosing function has a multi-return signature
    ///, the element types. Used to emit `(a, b)` as the
    /// right struct literal type on `return` sites.
    ret_multi_returns: Option<Vec<Type>>,
    /// `out` parameters declared by the enclosing function. The body
    /// operates on a `double` shadow of each name; on every
    /// `Stmt::Assign` to an out name we also mirror the value back into
    /// the caller's slot (encoding if the slot is value-domain).
    out_params: std::collections::HashMap<String, Type>,
    /// If `Some`, we are emitting the body of a state-machine runner
    /// In runner context, `emit_expr` rewrites every
    /// `Expr::Ident` to a `state-><name>` access (the runner accesses
    /// locals through the state block, not via stack-allocated shadows),
    /// and `emit_stmt` for `Stmt::Checkpoint` / `Stmt::Resume` emits
    /// the appropriate state transition instead of a comment.
    runner_state: Option<RunnerCtx<'a>>,
    /// The module-wide call-site index. Built once per module and
    /// shared by every emitted function, so a call site does not
    /// rebuild the callee's symbol and value domains.
    index: Option<&'a CallIndex>,
    /// The locals that are never reassigned. The Rust emitter writes
    /// `let` for these instead of `let mut`.
    readonly: std::collections::HashSet<String>,
    /// The type of every binding the emitter has seen so far.
    ///
    /// The AST is untyped, and a `list` element type is not written in
    /// the literal: `[1, 2]` says nothing about the element type a
    /// C accessor has to cast to. The map is seeded with the
    /// parameters and extended as `let` / `for` statements are
    /// emitted, which is enough for the places that need a type
    /// (`for` over a list, indexing, `.length`).
    bindings: std::collections::HashMap<String, Type>,
}

/// State-machine runner context. Holds the plan so the `emit_expr` /
/// `emit_stmt` paths can look up state IDs and slot names. The struct
/// is a `Copy`-able view of the plan; the underlying plan is owned
/// by the function-level emit, so we just borrow it here.
#[derive(Copy, Clone)]
struct RunnerCtx<'a> {
    plan: &'a CheckpointPlan,
}

/// The read-only set of a body nobody optimised.
///
/// Every local stays mutable in that case, exactly as it did before the
/// optimiser existed: the set is only filled in when the optimiser says
/// a name is never reassigned.
pub(crate) fn no_readonly() -> &'static std::collections::HashSet<String> {
    static EMPTY: std::sync::OnceLock<std::collections::HashSet<String>> =
        std::sync::OnceLock::new();
    EMPTY.get_or_init(std::collections::HashSet::new)
}

impl<'a> Ctx<'a> {
    pub(crate) fn new(
        func: &'a TypedFunc,
        module: &'a TypedModule,
        index: Option<&'a CallIndex>,
        body: &[Stmt],
        readonly: &std::collections::HashSet<String>,
    ) -> Self {
        let mut s = Self::default();
        s.module = Some(module);
        s.index = index;
        s.current_func = Some(func);
        s.ret_value_domain = func.return_type.as_ref().and_then(value_domain);
        s.ret_multi_returns = func.multi_returns.clone();
        s.readonly = readonly.clone();
        for p in &func.params {
            s.locals.push(p.name.clone());
            s.bindings.insert(p.name.clone(), p.ty.clone());
        }
        for (name, ty) in &func.captures {
            s.bindings.insert(name.clone(), ty.clone());
        }
        // Walk body once to collect `let` names.
        for stmt in body {
            collect_let_names(stmt, &mut s.locals);
        }
        s
    }
}

fn collect_let_names(stmt: &Stmt, into: &mut Vec<String>) {
    match stmt {
        Stmt::Let { names, .. } => into.extend(names.iter().cloned()),
        _ => {}
    }
}

/// Look up the type of a name in the enclosing function's scope
/// (parameters + let bindings). Returns `None` for unknown names.
/// `ponytail`: the lookup walks the AST rather than reading a
/// precomputed table because the semantic pass doesn't expose a
/// per-locals type map. For the MVP's small test surface this is
/// fast enough; the same code can be reused by a future
/// "value-domain" debug pass.
fn nested_stmts(stmt: &Stmt) -> &[Stmt] {
    match stmt {
        Stmt::If { then_branch, .. } => &then_branch.stmts,
        Stmt::For { body, .. } | Stmt::While { body, .. } => &body.stmts,
        _ => &[],
    }
}

fn lookup_local_type(name: &str, cx: &Ctx<'_>) -> Option<Type> {
    // The emitter records types as it walks the body; a `for` variable
    // or a `let` the walk has already passed is found here first.
    if let Some(t) = cx.bindings.get(name) {
        return Some(t.clone());
    }
    // Use the function currently being emitted (not
    // `module.functions.first`), so a `let v: vec2` in the second
    // function is resolved against that function's body, not the
    // first function's params.
    let func = cx.current_func?;
    for p in &func.params {
        if p.name == name {
            return Some(p.ty.clone());
        }
    }
    for stmt in &func.original.body.stmts {
        if let Some(ty) = let_binding_type(stmt, name) {
            return Some(ty);
        }
    }
    None
}

/// The type of a literal expression, when its shape names one.
fn literal_type(e: &Expr) -> Option<Type> {
    match e {
        Expr::IntLit { .. } => Some(Type::Int(None)),
        Expr::FloatLit { .. } => Some(Type::Float(None)),
        Expr::BoolLit { .. } => Some(Type::Bool),
        Expr::StringLit { .. } => Some(Type::String),
        Expr::ListLit { elements, .. } => {
            let inner = elements
                .first()
                .and_then(literal_type)
                .unwrap_or(Type::Float(None));
            Some(Type::List(Box::new(inner)))
        }
        Expr::StructLit { name, span, .. } => Some(Type::Struct(name.clone(), span.clone())),
        _ => None,
    }
}

fn let_binding_type(stmt: &Stmt, name: &str) -> Option<Type> {
    for s in nested_stmts(stmt) { if let Some(t) = let_binding_type(s, name) { return Some(t); } }
    match stmt {
        Stmt::Let { names, ty, value, .. } => {
            if !names.iter().any(|n| n == name) {
                return None;
            }
            // Explicit annotation wins.
            if let Some(t) = ty {
                return Some(t.clone());
            }
            // Otherwise infer from the right-hand side. Only handle
            // the common literal / identifier shapes for the MVP.
            literal_type(value)
        }
        _ => None,
    }
}

/// The type of an expression, as far as the emitter needs it.
///
/// This is deliberately small: it answers the questions the list and
/// `random` emitters ask (what is the element type of this list, what
/// does this call return), not a full type checker. The semantic pass
/// has already rejected programs where the answer matters for
/// correctness.
fn expr_type(expr: &Expr, cx: &Ctx<'_>) -> Option<Type> {
    match expr {
        Expr::IntLit { .. }
        | Expr::FloatLit { .. }
        | Expr::BoolLit { .. }
        | Expr::StringLit { .. }
        | Expr::ListLit { .. }
        | Expr::StructLit { .. } => literal_type(expr),
        Expr::Ident { name, .. } => lookup_local_type(name, cx),
        Expr::Index { target, .. } => match expr_type(target, cx)? {
            Type::List(inner) => Some(*inner),
            _ => None,
        },
        Expr::FieldAccess { target, field, .. } => {
            let t = expr_type(target, cx)?;
            match &t {
                Type::List(_) if field == "length" => Some(Type::Int(None)),
                Type::Struct(name, _) => cx
                    .module
                    .and_then(|m| m.structs.iter().find(|s| &s.name == name))
                    .and_then(|s| {
                        s.fields
                            .iter()
                            .find(|(n, _)| n == field)
                            .map(|(_, ty)| ty.clone())
                    }),
                _ if vec_dim(&t).is_some() => Some(Type::Float(None)),
                _ => None,
            }
        }
        Expr::Call { callee, .. } => {
            let Expr::Ident { name, .. } = callee.as_ref() else {
                return None;
            };
            // A user function resolves against the module; a builtin
            // resolves against the small table the emitter maps.
            if let Some(module) = cx.module {
                if let Some(f) = module.functions.iter().filter(|f| &f.name == name).last() {
                    return f.return_type.clone();
                }
            }
            builtin_return_type(name, expr, cx)
        }
        Expr::Binary { lhs, .. } => expr_type(lhs, cx).or(Some(Type::Float(None))),
        Expr::Unary { expr: inner, .. } => expr_type(inner, cx),
        Expr::IfExpr { then_branch, .. } => expr_type(then_branch, cx),
        Expr::AsType { target, .. } | Expr::NarrowCast { target, .. } => Some(target.clone()),
        Expr::Conv { kind, .. } => Some(match kind {
            spass_parser::ast::ConvKind::ToInt => Type::Int(None),
            spass_parser::ast::ConvKind::ToFloat => Type::Float(None),
        }),
        Expr::Spawn { func, .. } => {
            let Expr::Ident { name, .. } = func.as_ref() else {
                return None;
            };
            let ret = cx
                .module
                .and_then(|m| m.functions.iter().filter(|f| &f.name == name).last())
                .and_then(|f| f.return_type.clone())?;
            Some(Type::Task(Some(Box::new(ret))))
        }
        Expr::Parallel { func, args, .. } => {
            let Expr::Ident { name, .. } = func.as_ref() else {
                return None;
            };
            let f = cx
                .module
                .and_then(|m| m.functions.iter().filter(|x| &x.name == name).last())?;
            let ret = f.return_type.clone()?;
            let has_list = args
                .iter()
                .any(|a| matches!(expr_type(&a.value, cx), Some(Type::List(_))));
            let payload = if has_list {
                Type::List(Box::new(ret))
            } else {
                ret
            };
            Some(Type::Task(Some(Box::new(payload))))
        }
        Expr::Await { task, .. } => match expr_type(task, cx)? {
            Type::Task(Some(inner)) => Some(*inner),
            _ => Some(Type::Float(None)),
        },
        Expr::Random { candidates, args, .. } => {
            if args.is_some() {
                // Function mode: the type is the (shared) return type
                // of the candidates.
                let Expr::Ident { name, .. } = candidates.first()? else {
                    return None;
                };
                cx.module
                    .and_then(|m| m.functions.iter().filter(|f| &f.name == name).last())
                    .and_then(|f| f.return_type.clone())
            } else {
                candidates.first().and_then(|c| expr_type(c, cx))
            }
        }
        Expr::SpasioInput { .. } | Expr::SpasioOutput { .. } => Some(Type::Float(None)),
        Expr::Receive { pattern: Some(p), .. } => {
            Some(Type::Struct(p.type_name.clone(), p.span.clone()))
        }
        _ => None,
    }
}

/// The return type of a built-in call, where the emitter can name it.
fn builtin_return_type(name: &str, call: &Expr, cx: &Ctx<'_>) -> Option<Type> {
    let Expr::Call { args, .. } = call else {
        return None;
    };
    match name {
        "mk_vec2" => Some(Type::Vec2(None, None)),
        "mk_vec3" => Some(Type::Vec3(None, None, None)),
        "mk_vec4" => Some(Type::Vec4(None, None, None, None)),
        "dot" | "length" | "sin" | "cos" | "tan" | "sqrt" | "abs"
        | "floor" | "ceil" | "round" | "exp" | "log" | "pow" | "lerp"
        | "clamp" | "smoothstep" | "max" | "min" | "noise" | "fbm"
        | "to_int" | "to_float" => Some(Type::Float(None)),
        "normalize" | "hadamard" => args.first().and_then(|a| expr_type(&a.value, cx)),
        "cross" => Some(Type::Vec3(None, None, None)),
        "transpose" => args.first().and_then(|a| expr_type(&a.value, cx)),
        _ => None,
    }
}

/// Return the dimension (2/3/4) of a vec/mat type, or `None` for
/// scalars. Used by the call-site dispatch to pick the right vec/mat
/// built-in (e.g. `spass_dot3` for `dot(v1, v2)` on `Type::Vec3`).
fn vec_dim(ty: &Type) -> Option<u32> {
    match ty {
        Type::Vec2(_, _) => Some(2),
        Type::Vec3(_, _, _) => Some(3),
        Type::Vec4(_, _, _, _) => Some(4),
        _ => None,
    }
}

/// Return the dimension of a mat type, or `None` for non-mat. Same
/// shape as `vec_dim` so the call-site dispatch can share the
/// dimension lookup. Vectors and matrices share a numeric key here
/// because `vec2` and `mat2` (which doesn't exist in the language) would
/// both map to 2; the type kind check below discriminates.
fn mat_dim(ty: &Type) -> Option<u32> {
    match ty {
        Type::Mat3 => Some(3),
        Type::Mat4 => Some(4),
        _ => None,
    }
}

// ============================================================================
// Statements
// ============================================================================

fn emit_stmt(out: &mut String, stmt: &Stmt, cx: &mut Ctx<'_>) -> CodegenResult<()> {
    match stmt {
        Stmt::Let { names, ty, value, span } => {
            if cx.runner_state.is_some() {
                // Runner context: every local is a pre-declared
                // double slot in the state block. We don't redeclare
                // it; just assign. Destructuring is not supported
                // inside a state machine (semantic pass can enforce
                // if desired; the codegen path stays minimal here).
                if names.len() != 1 {
                    return Err(CodegenError::Unsupported {
                        message: "destructuring `let (a, b) = ...` is not supported inside a `@checkpoint` state machine".into(),
                        span: expr_span(value),
                    });
                }
                let _ = write!(out, "    state->{} = ", &names[0]);
                emit_expr(out, value, cx)?;
                out.push_str(";\n");
                let _ = ty;
                let _ = span;
            } else if names.len() == 1 {
                // `let msg = receive Alert{...}` - the
                // receive loop is statement-shaped in C, so it gets a
                // dedicated emission instead of the expression path
                // (which rejects Receive with an Unsupported error).
                if let Expr::Receive { pattern: Some(pattern), span: rspan } = value {
                    let self_id = seq_self_id(cx, rspan.clone())?;
                    let s = cx
                        .module
                        .as_ref()
                        .and_then(|m| {
                            m.structs.iter().find(|s| s.name == pattern.type_name)
                        })
                        .cloned()
                        .ok_or_else(|| CodegenError::Unsupported {
                            message: format!("unknown struct `{}`", pattern.type_name),
                            span: rspan.clone(),
                        })?;
                    let _ = writeln!(out, "    spass_msg_t __sp_msg;");
                    let _ = write!(
                        out,
                        "    for (;;) {{ __sp_msg = spass_seq_recv({}); if (",
                        self_id
                    );
                    for (i, (field, op, vexpr)) in pattern.conditions.iter().enumerate() {
                        if i > 0 {
                            out.push_str(" && ");
                        }
                        let idx = s
                            .fields
                            .iter()
                            .position(|(n, _)| n == field)
                            .ok_or_else(|| CodegenError::Unsupported {
                                message: format!("`{}` has no field `{}`", s.name, field),
                                span: rspan.clone(),
                            })?;
                        let lhs = match s.fields[idx].1 {
                            Type::Int(_) => format!("(int32_t)__sp_msg.f[{}]", idx),
                            _ => format!("__sp_msg.f[{}]", idx),
                        };
                        let op_str = match op {
                            BinOp::Gt => ">",
                            BinOp::Lt => "<",
                            BinOp::Ge => ">=",
                            BinOp::Le => "<=",
                            BinOp::Eq => "==",
                            BinOp::Ne => "!=",
                            _ => {
                                return Err(CodegenError::Unsupported {
                                    message: "receive pattern conditions need a comparison operator"
                                        .into(),
                                    span: rspan.clone(),
                                })
                            }
                        };
                        out.push_str(&format!("{} {} (", lhs, op_str));
                        emit_expr(out, vexpr, cx)?;
                        out.push_str(")");
                    }
                    out.push_str(") break; }\n");
                    let _ = writeln!(
                        out,
                        "    {} {} = __sp_unpack_{}(__sp_msg);",
                        c_type_name(&Type::Struct(s.name.clone(), rspan.clone())),
                        &names[0],
                        s.name
                    );
                    cx.locals.push(names[0].clone());
                    let _ = ty;
                    let _ = span;
                } else {
                    let cty = match ty {
                        Some(t) => c_type_name(t),
                        None => infer_c_type(value, cx)?,
                    };
                    let _ = write!(out, "    {} {} = ", cty, &names[0]);
                    // The annotation, not the literal, decides the
                    // element type: `list<float> = [1, 2]` stores
                    // doubles even though both elements are integer
                    // literals.
                    match (ty, value) {
                        (Some(Type::List(inner)), Expr::ListLit { elements, .. }) => {
                            emit_list_lit_c(out, elements, inner, cx)?;
                        }
                        _ => emit_expr(out, value, cx)?,
                    }
                    out.push_str(";\n");
                    cx.locals.push(names[0].clone());
                    let binding_ty = ty.clone().or_else(|| expr_type(value, cx));
                    if let Some(t) = binding_ty {
                        cx.bindings.insert(names[0].clone(), t);
                    }
                    let _ = span;
                }
            } else {
                // Destructuring `let (a, b) = f`. The C emitter uses the
                // same anonymous-struct return type as the producer: we
                // call the function into a temporary, then declare each
                // binding as a `__sp_field_N` extraction. The element
                // types come from the function's `multi_returns` slot
                // (populated by the semantic pass).
                let (called_name, args, _) = match value {
                    Expr::Call { callee, args, .. } => {
                        if let Expr::Ident { name, .. } = callee.as_ref() {
                            (name.clone(), args.clone(), ())
                        } else {
                            return Err(CodegenError::Unsupported {
                                message: "destructuring requires a direct function call".into(),
                                span: expr_span(value),
                            });
                        }
                    }
                    _ => {
                        return Err(CodegenError::Unsupported {
                            message: "destructuring only supported for direct calls".into(),
                            span: expr_span(value),
                        });
                    }
                };
                let f = cx
                    .module
                    .as_ref()
                    .and_then(|m| m.func(&called_name).cloned())
                    .ok_or_else(|| CodegenError::Unsupported {
                        message: format!("call to unknown function `{}`", called_name),
                        span: expr_span(value),
                    })?;
                let mr = f.multi_returns.as_ref().ok_or_else(|| CodegenError::Unsupported {
                    message: format!("`{}` is not a multi-return function", called_name),
                    span: expr_span(value),
                })?;
                let mangled = mangle_for_call(&f);
                let ret_ty = multi_return_c_type(mr);
                // Temporary holding the call's struct result.
                let _ = write!(out, "    {} __sp_tup = ", ret_ty);
                emit_call_with_args(out, &called_name, &mangled, &args, cx)?;
                out.push_str(";\n");
                // Destructure: one `T name = __sp_tup._f<i>;` per field.
                for (i, n) in names.iter().enumerate() {
                    let cty = c_type_name(&mr[i]);
                    let _ = writeln!(out, "    {} {} = __sp_tup._f{};", cty, n, i);
                    cx.locals.push(n.clone());
                }
                let _ = span;
            }
        }
        Stmt::Assign { name, value, span } => {
            if cx.runner_state.is_some() {
                // Runner context: the local lives in the state
                // block. Just emit `state-><name> = expr;` and skip
                // the out-param mirror (the runner doesn't have
                // out-params in MVP; the wrapper handles them at
                // function entry / return).
                let _ = write!(out, "    state->{} = ", name);
                emit_expr(out, value, cx)?;
                out.push_str(";\n");
                let _ = span;
            } else {
                let _ = write!(out, "    {} = ", name);
                emit_expr(out, value, cx)?;
                out.push_str(";\n");
                // Out params: the user-visible name is a `double` shadow
                // declared at function entry. The actual storage lives in
                // the caller's slot at `__sp_out_<name>`. Mirror the local
                // back through the pointer (encoded if value-domain).
                if let Some(ty) = cx.out_params.get(name).cloned() {
                    if let Some(vd) = value_domain(&ty) {
                        let _ = write!(out, "    *__sp_out_{} = ", name);
                        emit_c_encode(out, &vd, true, |o| {
                            let _ = write!(o, "{}", name);
                            Ok(())
                        })?;
                        out.push_str(";\n");
                    } else {
                        let _ = writeln!(out, "    *__sp_out_{} = {};", name, name);
                    }
                }
                let _ = span;
            }
        }
        Stmt::Return { value, span } => {
            if cx.runner_state.is_some() {
                // Runner context: the value goes into the return
                // slot of the state block. The wrapper reads it
                // back after `spass_task_resume` returns. We don't
                // do the value-domain encode here (the wrapper
                // does it at the ABI boundary).
                if let Some(v) = value {
                    let _ = write!(out, "    state->__sp_return = ");
                    emit_expr(out, v, cx)?;
                    out.push_str(";\n");
                }
                out.push_str("    return;\n");
                cx.has_return = true;
                let _ = span;
            } else if let Some(v) = value {
                // Take the value-domain out of the Ctx so we can pass
                // `cx` mutably to `emit_expr` without a borrow conflict.
                let vd = cx.ret_value_domain.clone();
                if let Some(vd) = vd {
                    // Encode the body result back to the uintN ABI type:
                    // N = round((x - min) * k), clamped to [0, state_count-1]
                    // where `k = 1/step` is the domain's exact reciprocal.
                    out.push_str("    return ");
                    emit_c_encode(out, &vd, true, |o| emit_expr(o, v, cx))?;
                    out.push_str(";\n");
                } else {
                    let _ = write!(out, "    return ");
                    emit_expr(out, v, cx)?;
                    out.push_str(";\n");
                }
            } else {
                out.push_str("    return;\n");
            }
            cx.has_return = true;
            let _ = span;
        }
        Stmt::Expr(e, span) => {
            let _ = write!(out, "    ");
            emit_expr(out, e, cx)?;
            out.push_str(";\n");
            let _ = span;
        }
        Stmt::If { cond, then_branch, else_branch, span } => {
            let _ = write!(out, "    if (");
            emit_expr(out, cond, cx)?;
            out.push_str(") ");
            emit_block(out, then_branch, cx)?;
            let _ = write!(out, " else ");
            emit_block(out, else_branch, cx)?;
            out.push('\n');
            let _ = span;
        }
        Stmt::While { cond, body, span } => {
            let _ = write!(out, "    while (");
            emit_expr(out, cond, cx)?;
            out.push_str(") ");
            emit_block(out, body, cx)?;
            out.push('\n');
            let _ = span;
        }
        Stmt::For { var, iter, body, span: _ } => match iter {
            spass_parser::ast::ForIter::Range { start, end, step } => {
                // Emit `for (T var = start; var < end; var += step)` (or `++` if no step).
                let cty = infer_c_type(start, cx)?;
                let _ = write!(out, "    for ({} {} = ", cty, var);
                emit_expr(out, start, cx)?;
                out.push_str("; ");
                let _ = write!(out, "{} < ", var);
                emit_expr(out, end, cx)?;
                out.push_str("; ");
                if let Some(s) = step {
                    let _ = write!(out, "{} += ", var);
                    emit_expr(out, s, cx)?;
                } else {
                    let _ = write!(out, "{}++", var);
                }
                out.push_str(") ");
                emit_block(out, body, cx)?;
                out.push('\n');
            }
            spass_parser::ast::ForIter::List(list_expr) => {
                // walk the descriptor by index. The body
                // is emitted from a synthetic block whose first
                // statement binds the loop variable to the element;
                // every following statement then sees an ordinary
                // local of the element type.
                let elem = match expr_type(list_expr, cx) {
                    Some(Type::List(inner)) => *inner,
                    _ => Type::Float(None),
                };
                let dummy = spass_lexer::Span::dummy();
                let index_expr = Expr::Index {
                    target: Box::new(list_expr.clone()),
                    index: Box::new(Expr::Ident {
                        name: "__sp_i".to_string(),
                        span: dummy.clone(),
                    }),
                    span: dummy.clone(),
                };
                let mut stmts = Vec::with_capacity(body.stmts.len() + 1);
                stmts.push(Stmt::Let {
                    names: vec![var.clone()],
                    ty: Some(elem),
                    value: index_expr,
                    span: dummy,
                });
                stmts.extend(body.stmts.iter().cloned());
                let block = Block { stmts, span: body.span.clone() };

                out.push_str("    for (int32_t __sp_i = 0; __sp_i < (");
                emit_expr(out, list_expr, cx)?;
                out.push_str(").len; ++__sp_i) ");
                emit_block(out, &block, cx)?;
                out.push('\n');
            }
        },
        Stmt::Break { span } => {
            let _ = writeln!(out, "    break;");
            let _ = span;
        }
        Stmt::Continue { span } => {
            let _ = writeln!(out, "    continue;");
            let _ = span;
        }
        Stmt::Checkpoint { name, .. } | Stmt::Resume { name, .. } => {
            // Checkpoint/Resume handling. Outside a runner these
            // can't appear (codegen dispatches by `body_has_checkpoint`),
            // but if a future revision adds a non-checkpointed
            // function with @resume, the resume path is a synchronous
            // call to `spass_task_resume(spass_task_lookup(name))`.
            if let Some(rc) = cx.runner_state {
                match stmt {
                    Stmt::Checkpoint { name, .. } => {
                        // Save the next state id, register the task
                        // under the checkpoint name so a cross-
                        // function @resume can find it, and return
                        // to the caller (the wrapper will re-enter
                        // us via spass_task_resume).
                        let state_id = rc.plan.state_id_of(name).unwrap_or(0);
                        let _ = writeln!(out, "    t->state_id = {};", state_id);
                        let _ = writeln!(out, "    spass_task_register({:?}, t);", name);
                        out.push_str("    return;\n");
                    // The next case label is emitted by the
                    // surrounding case-emit loop in
                    // `emit_state_machine_c`, which lays out
                    // each slice as `case N: {... }` in
                    // source order. The Duff's device fall-
                    // through means re-entry at state_id N
                    // lands in the next case, not at the
                    // checkpoint site itself.
                    }
                    Stmt::Resume { name, .. } => {
                        // Look up the target task and run it from
                        // its saved state. Cross-function @resume
                        // works because every checkpointed
                        // function registers its task under its
                        // checkpoint names. A NULL lookup is a
                        // no-op (the resume target was never
                        // checkpointed, or already completed).
                        let _ = writeln!(out, "    {{");
                        let _ = writeln!(out, "        spass_task_t* __sp_other = spass_task_lookup({:?});", name);
                        out.push_str("        if (__sp_other != NULL) { spass_task_resume(__sp_other); }\n");
                        out.push_str("    }\n");
                    }
                    _ => unreachable!(),
                }
            } else {
                // Defensive: a non-checkpointed function with a
                // resume site is unusual (codegen dispatches by
                // `body_has_checkpoint` so this branch is
                // effectively unreachable). Treat as a synchronous
                // resume call.
                if matches!(stmt, Stmt::Resume { .. }) {
                    let _ = writeln!(out, "    {{");
                    let _ = writeln!(out, "        spass_task_t* __sp_other = spass_task_lookup({:?});", name);
                    out.push_str("        if (__sp_other != NULL) { spass_task_resume(__sp_other); }\n");
                    out.push_str("    }\n");
                } else {
                    let _ = writeln!(out, "    /* @checkpoint / @resume ignored */");
                }
            }
        }
        Stmt::OrderDecl { .. } => {
        // Compiler-internal metadata; emits nothing.
        }
        Stmt::Assert { .. } => {
            // `assert(...)` lives in `test` bodies, which are handled
            // by the `spass test` driver and not folded
            // into the regular build path. The match arm exists for
            // exhaustiveness; we never reach it from `typed.functions`
            // because tests are not in that list. The comment keeps
            // the output self-explanatory if the codegen is ever
            // extended to compile tests in-line.
            let _ = out;
        }
        Stmt::Dispatch { decl, apply, .. } => {
            // expand `@dispatch(...) apply(...)` into a
            // left-fold over the matched functions. The semantic pass
            // has validated the dispatch (E002, E004, E014, W002);
            // here we just turn it into a sequence of plain calls.
            //
            // `ponytail`: the expansion produces a chain of regular
            // calls. The first call's carry is the user's rhs; the
            // rest's carries are the user's lhs (which the previous
            // call wrote to). For the MVP we require an assignment
            // target so the carry name is unambiguous.
            let modref = cx
                .module
                .as_ref()
                .ok_or_else(|| CodegenError::Unsupported {
                    message: "@dispatch needs a module context".into(),
                    span: decl.span.clone(),
                })?;
            let expansions = dispatch_codegen::expand(
                modref,
                &decl.tags,
                &decl.bind,
                &apply.call,
                apply.target.as_deref(),
            )
            .map_err(|e| CodegenError::Unsupported {
                message: format!("@dispatch expansion failed: {}", e),
                span: decl.span.clone(),
            })?;
            for (target, call, span) in expansions {
                let _ = write!(out, "    {} = ", target);
                emit_expr(out, &call, cx)?;
                out.push_str(";\n");
                let _ = span;
            }
        }
        Stmt::IfPresent { .. } => {
            // The C emitter, like the Rust emitter, only ever sees
            // the post-transform body (the `if_present` was replaced
            // by its present_branch or absent_branch when codegen
            // produced the per-variant AST). If we land here it
            // means the transform was skipped, which is a bug -
            // surface it loudly so the broken codegen path is
            // visible in the C output.
            return Err(CodegenError::Unsupported {
                message: "if_present was not transformed before C emission; this is a codegen bug".into(),
                span: stmt.span(),
            });
        }
        Stmt::Await { .. } => {
            // the `@await` marker is a no-op in the
            // MVP's runner. The actual I/O happens at the next
            // `let v = spasio:input[mode]("channel")` statement
            // (see `emit_expr` for `Expr::SpasioInput`); the
            // state machine is wired up for future async
            // resumption but isn't strictly required here. The
            // comment keeps the generated C self-documenting.
            out.push_str("    /* @await: see next let for spasio:input */\n");
        }
        Stmt::Ownclude(_) => {
        // `ownclude` is lifted into a static
        // helper at module-emit time (see `generate_c` and
        // `generate_rust`), not at statement-emit time. The
        // enclosing function's body has already had its
        // nested functions hoisted by the time we walk
        // statements, so this arm is here purely for
        // exhaustiveness.
        }
    }
    Ok(())
}

fn emit_block(out: &mut String, block: &Block, cx: &mut Ctx<'_>) -> CodegenResult<()> {
    out.push_str("{\n");
    for s in &block.stmts {
        emit_stmt(out, s, cx)?;
    }
    out.push_str("    }");
    Ok(())
}

// ============================================================================
// Expressions
// ============================================================================

fn emit_expr(out: &mut String, expr: &Expr, cx: &mut Ctx<'_>) -> CodegenResult<()> {
    match expr {
        Expr::IntLit { value, .. } => {
            let _ = write!(out, "((int32_t){})", value);
        }
        Expr::FloatLit { value, .. } => {
            // Render rational as a double literal.
            let f = rational_to_f64(value);
            let _ = write!(out, "({})", f);
        }
        Expr::BoolLit { value, .. } => {
            let _ = write!(out, "({})", if *value { "true" } else { "false" });
        }
        Expr::StringLit { value, .. } => {
            let _ = write!(out, "({:?})", value);
        }
        Expr::Ident { name, .. } => {
            if cx.runner_state.is_some() {
                // Runner context: every local lives in the state
                // block, accessed as `state-><name>`.
                let _ = write!(out, "state->{}", name);
            } else {
                let _ = write!(out, "{}", name);
            }
        }
        Expr::Binary { op, lhs, rhs, .. } => {
            emit_binop(out, op, lhs, rhs, cx)?;
        }
        Expr::Unary { op, expr: inner, .. } => {
            match op {
                UnaryOp::Neg => {
                    out.push_str("(-(");
                    emit_expr(out, inner, cx)?;
                    out.push_str("))");
                }
                UnaryOp::Not => {
                    out.push_str("(!(");
                    emit_expr(out, inner, cx)?;
                    out.push_str("))");
                }
            }
        }
        // `s2d:window(...)`, `s3d:box(...)`, `spio:read_text(...)` -
        // playground native calls. Emit the runtime symbol directly:
        // `spass_s2d_window(...)`, `spass_spio_read_text(...)`.
        Expr::NativeCall { namespace, func, args, .. } => {
            let _ = write!(out, "spass_{}_{}(", namespace, func);
            for (i, arg) in args.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                emit_expr(out, &arg.value, cx)?;
            }
            out.push(')');
        }
        Expr::Call { callee, args, span } => {
            let name = match callee.as_ref() {
                Expr::Ident { name, .. } => name.as_str(),
                _ => {
                    return Err(CodegenError::Unsupported {
                        message: "only direct function calls are supported".into(),
                        span: span.clone(),
                    })
                }
            };
            // Conversions are syntactically a function call but must be
            // emitted as inline casts. Detect and handle before the
            // generic builtin/runtime dispatch below.
            if name == "to_int" {
                if args.len() != 1 {
                    return Err(CodegenError::Unsupported {
                        message: "to_int expects exactly 1 argument".into(),
                        span: span.clone(),
                    });
                }
                out.push_str("((int32_t)(");
                emit_expr(out, &args[0].value, cx)?;
                out.push_str("))");
                return Ok(());
            }
            if name == "to_float" {
                if args.len() != 1 {
                    return Err(CodegenError::Unsupported {
                        message: "to_float expects exactly 1 argument".into(),
                        span: span.clone(),
                    });
                }
                out.push_str("((double)(");
                emit_expr(out, &args[0].value, cx)?;
                out.push_str("))");
                return Ok(());
            }
            // (`ownclude`): a call to an `ownclude`
            // function must forward the enclosing function's
            // captured values as extra leading arguments (the
            // hoisted helper's signature prepends them). We look
            // the callee up before the builtin/runtime dispatch
            // so the captures can be emitted no matter which
            // branch the symbol came from.
            let ownclude_captures: Option<Vec<String>> = cx
                .module
                .as_ref()
                .and_then(|m| m.func(&name))
                .filter(|f| {
                    f.original.visibility == spass_parser::ast::Visibility::OwnPrivate
                })
                .map(|f| f.captures.iter().map(|(n, _)| n.clone()).collect());
            // The callee's value-domain parameters, in declaration order,
            // and the value domain of its return. Filled in only when the
            // call actually resolves to a module function: built-ins and
            // native calls have no value-domain parameter ABI. `out`
            // parameters are passed by pointer and carry the encoded
            // slot, so they are not quantised here.
            //
            // Both come from the module's call-site index, so a call
            // site does not rebuild the callee's symbol and domains.
            let index = cx.index;
            let mut callee_domains: Option<&[Option<ValueDomain>]> = None;
            let mut callee_return: Option<&ValueDomain> = None;
            let mapped: &str = if let Some(builtin) = builtin_mapping(&name) {
                builtin
            } else if let Some(dim_builtin) = vec_mat_builtin(&name, args, cx) {
                // vec/mat built-ins like `dot` / `length`
                // dispatch to dimension-specific runtime symbols
                // (`spass_dot3`, `spass_length3`,...). The
                // dimension comes from the first argument's type; if
                // we can't determine it, fall back to the generic
                // mapping above and let the linker catch the type
                // mismatch.
                dim_builtin
            } else if let Some(site) = index.and_then(|ix| ix.get(&name)) {
                // Use `mangle_for_call` so an `if_present` function
                // is always invoked under its present-variant symbol
                // (Spass has no syntax for omitting a positional
                // argument, so the caller always supplied the
                // parameter).
                callee_domains = Some(site.param_domains.as_slice());
                callee_return = site.return_domain.as_ref();
                site.symbol.as_str()
            } else if cx.module.is_some() {
                return Err(CodegenError::Unsupported {
                    message: format!("call to unknown function `{}`", name),
                    span: span.clone(),
                });
            } else {
                return Err(CodegenError::Unsupported {
                    message: format!("call to unknown function `{}` (no module context)", name),
                    span: span.clone(),
                });
            };
            // The call is built into its own buffer so that a
            // value-domain return can be decoded around it.
            let mut call = String::new();
            let _ = write!(call, "{}(", mapped);
            let mut arg_idx = 0;
            // ownclude captures are forwarded by name.
            // The names are guaranteed to be in scope at the call
            // site (the semantic pass enforces this) so the helper
            // sees a stable value even if the original variable is
            // reassigned later.
            if let Some(caps) = &ownclude_captures {
                for cap in caps {
                    if arg_idx > 0 {
                        call.push_str(", ");
                    }
                    let _ = write!(call, "{}", cap);
                    arg_idx += 1;
                }
            }
            for (i, a) in args.iter().enumerate() {
                if arg_idx > 0 {
                    call.push_str(", ");
                }
                let dom = callee_domains
                    .as_ref()
                    .and_then(|doms| doms.get(i))
                    .and_then(|d| d.as_ref());
                match dom {
                    Some(vd) => {
                        // The callee expects the encoded state index, so
                        // the argument has to be quantised. When the
                        // argument's range is provably inside the
                        // domain the clamp is dead code and is dropped.
                        let enc = classify_arg(&a.value, vd, cx);
                        if let ArgEncoding::Disjoint = enc {
                            return Err(CodegenError::TypeError {
                                message: format!(
                                    "argument {} of `{}` is outside the value domain [{}, {}]",
                                    i + 1,
                                    name,
                                    vd.min,
                                    vd.max
                                ),
                                span: a.span.clone(),
                            });
                        }
                        let clamp = !matches!(enc, ArgEncoding::InDomain);
                        emit_c_encode(&mut call, vd, clamp, |o| emit_expr(o, &a.value, cx))?;
                    }
                    None => {
                        emit_call_arg(&mut call, &name, arg_idx, a, cx)?;
                    }
                }
                arg_idx += 1;
            }
            call.push(')');
            match &callee_return {
                // The callee returns the encoded state index; the Spass
                // level sees the decoded value, so decode it here.
                Some(vd) => {
                    let _ = write!(
                        out,
                        "{} + {} * (double)({})",
                        vd.min, vd.step, call
                    );
                }
                None => out.push_str(&call),
            }
        }
        Expr::FieldAccess { target, field, .. } => {
            emit_expr(out, target, cx)?;
            // `list.length` is a field of the list
            // descriptor, not of an element.
            if field == "length" && matches!(expr_type(target, cx), Some(Type::List(_))) {
                out.push_str(".len");
            } else {
                let _ = write!(out, ".{}", field);
            }
        }
        Expr::Index { target, index, .. } => {
            // bounds-checked access into the list's byte
            // buffer. The check and the access both evaluate `index`
            // and `target`; both are pure expressions in Spass (a list
            // return is rejected by the semantic pass), so a repeated
            // evaluation cannot change the value.
            let elem = match expr_type(target, cx) {
                Some(Type::List(inner)) => *inner,
                _ => Type::Float(None),
            };
            let ect = c_type_name(&elem);
            out.push_str("(spass_list_check((int32_t)(");
            emit_expr(out, index, cx)?;
            out.push_str("), (");
            emit_expr(out, target, cx)?;
            out.push_str(").len), *(");
            out.push_str(&ect);
            out.push_str("*)(");
            emit_expr(out, target, cx)?;
            out.push_str(".data + (size_t)(int32_t)(");
            emit_expr(out, index, cx)?;
            out.push_str(") * (");
            emit_expr(out, target, cx)?;
            out.push_str(").stride))");
        }
        Expr::Tuple { elements, .. } => {
            // `(a, b, c)` tuple literal. Allowed only as the return
            // value of a multi-return function (semantic pass enforces
            // this); emit a struct literal with `_f<i>` fields.
            // The target struct type is taken from `cx.ret_multi_returns`
            // when set; otherwise we synthesise a fresh anonymous struct.
            let types: Vec<Type> = if let Some(mr) = &cx.ret_multi_returns {
                mr.clone()
            } else {
                elements.iter().map(|_| Type::Float(None)).collect()
            };
            out.push_str("({");
            for (i, (e, t)) in elements.iter().zip(types.iter()).enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                let _ = write!(out, ".{} = ", field_name(i));
                emit_expr(out, e, cx)?;
                let _ = t;
            }
            out.push_str(" })");
        }
        Expr::ListLit { elements, .. } => {
            let elem = elements
                .first()
                .and_then(|e| expr_type(e, cx))
                .unwrap_or(Type::Float(None));
            emit_list_lit_c(out, elements, &elem, cx)?;
        }
        Expr::StructLit { name, fields, .. } => {
            let _ = write!(out, "({}){{", name);
            for (i, (fname, val)) in fields.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                let _ = write!(out, ".{} = ", fname);
                emit_expr(out, val, cx)?;
            }
            out.push_str(" }");
        }
        Expr::IfExpr { cond, then_branch, else_branch, .. } => {
            out.push_str("((");
            emit_expr(out, cond, cx)?;
            out.push_str(") ? (");
            emit_expr(out, then_branch, cx)?;
            out.push_str(") : (");
            emit_expr(out, else_branch, cx)?;
            out.push_str("))");
        }
        Expr::Spawn { func, args, .. } => {
            // launch the callee on a worker thread and return
            // an opaque task handle (uint64_t). The thunk wrapper is
            // emitted at module scope by `emit_spawn_thunks_c`.
            let callee = match func.as_ref() {
                Expr::Ident { name, .. } => name.clone(),
                _ => {
                    return Err(CodegenError::Unsupported {
                        message: "spawn callee must be a named function".into(),
                        span: expr.span(),
                    })
                }
            };
            let tf = cx
                .module
                .as_ref()
                .and_then(|m| m.functions.iter().find(|f| f.name == callee));
            let tf = match tf {
                Some(f) if spawn_thunk_compatible(f) => f,
                Some(_) => {
                    return Err(CodegenError::Unsupported {
                        message: format!(
                            "`spawn` target `{}` must be a plain function: float/int params, float/int return, no captured variables",
                            callee
                        ),
                        span: expr.span(),
                    })
                }
                None => {
                    return Err(CodegenError::Unsupported {
                        message: format!("`spawn` target `{}` not found", callee),
                        span: expr.span(),
                    })
                }
            };
            let thunk = spawn_thunk_name(tf);
            let _ = write!(out, "spass_spawn({}, (const double[]){{ ", thunk);
            for (i, a) in args.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                out.push_str("(double)(");
                emit_expr(out, &a.value, cx)?;
                out.push_str(")");
            }
            let _ = write!(out, " }}, {})", args.len());
        }
        Expr::Parallel { func, args, span, .. } => {
            // one call per list index. A list argument
            // supplies the value for that call; a scalar argument is
            // repeated. The batch runtime checks that every list has
            // the same length as the first one.
            let module = cx.module.as_ref().ok_or_else(|| CodegenError::Unsupported {
                message: "no module context".into(),
                span: span.clone(),
            })?;
            let Expr::Ident { name, .. } = func.as_ref() else {
                return Err(CodegenError::Unsupported {
                    message: "`parallel` needs a function name".into(),
                    span: span.clone(),
                });
            };
            let f = module
                .functions
                .iter()
                .filter(|f| &f.name == name)
                .last()
                .ok_or_else(|| CodegenError::Unsupported {
                    message: format!("call to unknown function `{}`", name),
                    span: span.clone(),
                })?;
            if !spawn_thunk_compatible(f) {
                return Err(CodegenError::Unsupported {
                    message: format!(
                        "`{}` cannot run under `parallel`: only plain float/int parameters and returns are supported",
                        name
                    ),
                    span: span.clone(),
                });
            }
            let mut has_list = false;
            for a in args {
                if let Some(Type::List(inner)) = expr_type(&a.value, cx) {
                    has_list = true;
                    if !matches!(*inner, Type::Float(_) | Type::Int(_)) {
                        return Err(CodegenError::Unsupported {
                            message: "`parallel` list arguments must hold float or int values"
                                .into(),
                            span: a.span.clone(),
                        });
                    }
                }
            }
            out.push_str("spass_parallel_spawn_args(");
            out.push_str(&spawn_thunk_name(f));
            if args.is_empty() {
                out.push_str(", 0, 0, ");
            } else {
                out.push_str(", (const SpassParArg[]){ ");
                for (i, a) in args.iter().enumerate() {
                    if i > 0 {
                        out.push_str(", ");
                    }
                    if let Some(Type::List(inner)) = expr_type(&a.value, cx) {
                        out.push_str("{ &(");
                        emit_expr(out, &a.value, cx)?;
                        out.push_str("), 0.0, ");
                        out.push_str(if matches!(*inner, Type::Int(_)) { "1" } else { "0" });
                        out.push_str(" }");
                    } else {
                        out.push_str("{ 0, (double)(");
                        emit_expr(out, &a.value, cx)?;
                        out.push_str("), 0 }");
                    }
                }
                let _ = write!(out, " }}, {}, ", args.len());
            }
            if has_list {
                let first = args
                    .iter()
                    .find(|a| matches!(expr_type(&a.value, cx), Some(Type::List(_))))
                    .unwrap();
                out.push('(');
                emit_expr(out, &first.value, cx)?;
                out.push_str(").len");
            } else {
                out.push('1');
            }
            out.push(')');
        }
        Expr::Send { target, message, span } => {
            // pack the message struct into the runtime's
            // f64 slot array and push it onto the target's queue. The
            // pack helper keeps this a single expression so `send` can
            // appear anywhere a bool expression can.
            let mty = seq_message_struct(message, cx, span.clone())?;
            let _ = write!(out, "spass_seq_send({}, ", seq_id_const(target));
            out.push_str(&pack_call_c(&mty, message, cx)?);
            out.push(')');
        }
        Expr::Broadcast { message, span } => {
            let mty = seq_message_struct(message, cx, span.clone())?;
            let _ = write!(out, "spass_seq_broadcast(");
            out.push_str(&pack_call_c(&mty, message, cx)?);
            out.push(')');
        }
        Expr::Receive { .. } => {
            // `receive` blocks in a loop - it is statement-shaped. The
            // C emitter only supports it as the RHS of a `let` (see the
            // Stmt::Let special case); anywhere else is an error.
            return Err(CodegenError::Unsupported {
                message:
                    "`receive` must be the right-hand side of a `let` binding in the C backend"
                        .into(),
                span: expr.span(),
            })
        }
        Expr::Await { task, .. } => {
            match expr_type(expr, cx) {
                Some(Type::List(_)) => {
                    // A `parallel` batch awaits into a list of results.
                    out.push_str("spass_parallel_await((uint64_t)(");
                    emit_expr(out, task, cx)?;
                    out.push_str("))");
                }
                payload => {
                    let cast = match payload {
                        Some(Type::Int(_)) => Some("int32_t"),
                        Some(Type::Uint(_)) => Some("uint32_t"),
                        Some(Type::Bool) => Some("bool"),
                        _ => None,
                    };
                    if let Some(ty) = cast {
                        let _ = write!(out, "({})(", ty);
                    }
                    out.push_str("spass_task_await((uint64_t)(");
                    emit_expr(out, task, cx)?;
                    out.push_str("))");
                    if cast.is_some() {
                        out.push(')');
                    }
                }
            }
        }
        Expr::Random { candidates, args, span } => match args {
            None => {
                // value mode. A task candidate is awaited
                // first; every candidate crosses the helper as a double.
                let cast = match expr_type(expr, cx) {
                    Some(Type::Int(_)) => Some("int32_t"),
                    Some(Type::Uint(_)) => Some("uint32_t"),
                    Some(Type::Bool) => Some("bool"),
                    _ => None,
                };
                if let Some(ty) = cast {
                    let _ = write!(out, "({})(", ty);
                }
                out.push_str("spass_random_pick((const double[]){ ");
                for (i, c) in candidates.iter().enumerate() {
                    if i > 0 {
                        out.push_str(", ");
                    }
                    if matches!(expr_type(c, cx), Some(Type::Task(_))) {
                        out.push_str("spass_task_await((uint64_t)(");
                        emit_expr(out, c, cx)?;
                        out.push_str("))");
                    } else {
                        out.push_str("(double)(");
                        emit_expr(out, c, cx)?;
                        out.push(')');
                    }
                }
                let _ = write!(out, " }}, {})", candidates.len());
                if cast.is_some() {
                    out.push(')');
                }
            }
            Some(args) => {
                let module = cx.module.as_ref().ok_or_else(|| CodegenError::Unsupported {
                    message: "no module context".into(),
                    span: span.clone(),
                })?;
                let mut funcs = Vec::with_capacity(candidates.len());
                for c in candidates {
                    let Expr::Ident { name, .. } = c else {
                        return Err(CodegenError::Unsupported {
                            message: "`random(...)(args)` candidates must be function names"
                                .into(),
                            span: span.clone(),
                        });
                    };
                    let f = module
                        .functions
                        .iter()
                        .filter(|f| &f.name == name)
                        .last()
                        .ok_or_else(|| CodegenError::Unsupported {
                            message: format!("call to unknown function `{}`", name),
                            span: span.clone(),
                        })?;
                    if !random_candidate_compatible(f) {
                        return Err(CodegenError::Unsupported {
                            message: format!(
                                "`{}` cannot be a `random` candidate: only plain float/int parameters and returns are supported",
                                name
                            ),
                            span: span.clone(),
                        });
                    }
                    funcs.push(f);
                }
                let ret = c_type_name(funcs[0].return_type.as_ref().unwrap());
                let params = funcs[0]
                    .params
                    .iter()
                    .map(|p| c_type_name(&p.ty))
                    .collect::<Vec<_>>()
                    .join(", ");
                let _ = write!(out, "(({} (*[])({})){{ ", ret, params);
                for (i, f) in funcs.iter().enumerate() {
                    if i > 0 {
                        out.push_str(", ");
                    }
                    out.push_str(&mangle_for_call(f));
                }
                let _ = write!(out, " }})[spass_random_index({})](", candidates.len());
                for (i, a) in args.iter().enumerate() {
                    if i > 0 {
                        out.push_str(", ");
                    }
                    emit_expr(out, &a.value, cx)?;
                }
                out.push(')');
            }
        },
        Expr::SpasioInput { mode, channel, .. } => {
            // / 9: `spasio:input[mode]("channel")` is a
            // blocking I/O call. The C runtime exposes
            // `spass_spasio_input` which reads from the channel
            // (file, socket, or shared memory) and returns a
            // double. The mode constant is rendered from the
            // SpasioMode enum; see `spass_spasio_mode_c`.
            let mode_c = match mode {
                spass_parser::ast::SpasioMode::File => "SPASS_SPASIO_FILE",
                spass_parser::ast::SpasioMode::Socket => "SPASS_SPASIO_SOCKET",
                spass_parser::ast::SpasioMode::Memory => "SPASS_SPASIO_MEMORY",
            };
            let _ = write!(out, "spass_spasio_input({}, {:?})", mode_c, channel);
        }
        Expr::SpasioOutput { mode, value, channel, .. } => {
            // `spasio:output[mode](value, "channel")`
            // writes the value to the channel. The MVP's runtime
            // helper returns the value (so the call site can stay
            // expression-shaped); it does not block.
            let mode_c = match mode {
                spass_parser::ast::SpasioMode::File => "SPASS_SPASIO_FILE",
                spass_parser::ast::SpasioMode::Socket => "SPASS_SPASIO_SOCKET",
                spass_parser::ast::SpasioMode::Memory => "SPASS_SPASIO_MEMORY",
            };
            let _ = write!(out, "spass_spasio_output({}, ", mode_c);
            emit_expr(out, value, cx)?;
            let _ = write!(out, ", {:?})", channel);
        }
        Expr::AsType { value, .. } => {
            // MVP: ignore the target type and just emit the value. A real
            // implementation would clamp to the declared range.
            emit_expr(out, value, cx)?;
        }
        Expr::NarrowCast { value, .. } => {
            emit_expr(out, value, cx)?;
        }
        Expr::Conv { kind, value, .. } => match kind {
            ConvKind::ToFloat => {
                out.push_str("((double)(");
                emit_expr(out, value, cx)?;
                out.push_str("))");
            }
            ConvKind::ToInt => {
                out.push_str("((int32_t)(");
                emit_expr(out, value, cx)?;
                out.push_str("))");
            }
        },
        Expr::IfPresent { .. } => {
            return Err(CodegenError::Unsupported {
                message: "`if_present` is a statement, not an expression".into(),
                span: expr.span(),
            })
        }
    }
    Ok(())
}

fn emit_call_arg(
    out: &mut String,
    _func: &str,
    _idx: usize,
    arg: &CallArg,
    cx: &mut Ctx<'_>,
) -> CodegenResult<()> {
    emit_expr(out, &arg.value, cx)
}

fn emit_binop(
    out: &mut String,
    op: &BinOp,
    lhs: &Expr,
    rhs: &Expr,
    cx: &mut Ctx<'_>,
) -> CodegenResult<()> {
    // Spass forbids runtime fixed-point division. We surface that as a
    // clear error from the codegen; semantic analysis should have caught
    // it earlier, but be defensive.
    if matches!(op, BinOp::Div) {
        if let Some(r) = const_int_pow2(rhs) {
            // Compile-time 2^k => right-shift, but we operate on doubles
            // for the MVP, so emit a divide.
            out.push_str("((");
            emit_expr(out, lhs, cx)?;
            let _ = write!(out, ") / {} )", 1i64 << r);
            return Ok(());
        }
    }

    // vector / matrix binary operators. `v1 + v2`,
    // `v1 - v2`, `v * s` and `s * v` (with a scalar on one side).
    // The type of the LHS determines the dimension. Matrices
    // share the `*` and `/` paths with scalars here - the MVP
    // uses the `m * v` and `m1 * m2` built-ins (`spass_matvec*`
    // / `spass_matmul*`) rather than the `*` operator.
    if let Some(d) = lhs_type_dim(lhs, cx) {
        return emit_vec_binop(out, op, lhs, rhs, d, cx);
    }

    let op_str = match op {
        BinOp::Add => "+",
        BinOp::Sub => "-",
        BinOp::Mul => "*",
        BinOp::Div => "/",
        BinOp::Pow => "pow", // function call below
        BinOp::Eq => "==",
        BinOp::Ne => "!=",
        BinOp::Lt => "<",
        BinOp::Le => "<=",
        BinOp::Gt => ">",
        BinOp::Ge => ">=",
        BinOp::And => "&&",
        BinOp::Or => "||",
    };

    if matches!(op, BinOp::Pow) {
        out.push_str("spass_pow(");
        emit_expr(out, lhs, cx)?;
        out.push_str(", ");
        emit_expr(out, rhs, cx)?;
        out.push(')');
        return Ok(());
    }

    out.push('(');
    emit_expr(out, lhs, cx)?;
    out.push(' ');
    out.push_str(op_str);
    out.push(' ');
    emit_expr(out, rhs, cx)?;
    out.push(')');
    Ok(())
}

/// Emit `lhs OP rhs` where `lhs` is a vec of dimension `d` and
/// the operator is `+` / `-` (vec-vec) or `*` / `/` (vec-scalar).
/// `ponytail`: scalar-on-both-sides and mat-vec / mat-mat are
/// not handled here; the language routes those through named
/// built-ins (`spass_matvec*` / `spass_matmul*`).
fn emit_vec_binop(
    out: &mut String,
    op: &BinOp,
    lhs: &Expr,
    rhs: &Expr,
    d: u32,
    cx: &mut Ctx<'_>,
) -> CodegenResult<()> {
    let comps: &[&str] = match d {
        2 => &["x", "y"],
        3 => &["x", "y", "z"],
        4 => &["x", "y", "z", "w"],
        _ => {
            return Err(CodegenError::Unsupported {
                message: format!("unsupported vec dimension {}", d),
                span: expr_span(lhs),
            })
        }
    };
    match op {
        BinOp::Add | BinOp::Sub => {
            // vec OP vec, or vec OP scalar (broadcast). When the
            // rhs is a scalar we emit `lhs.<c> OP rhs` (no `.x`
            // on the rhs) so the C compiler doesn't try to take
            // the x-component of a double.
            let rhs_is_scalar = is_scalar_expr(rhs, cx);
            out.push('(');
            out.push_str(&c_type_name_for_dim(d));
            out.push_str("){");
            for (i, c) in comps.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                out.push('(');
                emit_expr(out, lhs, cx)?;
                out.push('.');
                out.push_str(c);
                let op_str = if matches!(op, BinOp::Add) { "+" } else { "-" };
                out.push(' ');
                out.push_str(op_str);
                out.push(' ');
                emit_expr(out, rhs, cx)?;
                if !rhs_is_scalar {
                    out.push('.');
                    out.push_str(c);
                }
                out.push(')');
            }
            out.push('}');
            out.push(')');
            Ok(())
        }
        BinOp::Mul | BinOp::Div => {
            // vec-scalar (or scalar-vec). The rhs is the scalar
            // side; we emit `lhs.<c> OP rhs` for each component.
            // If both sides are vectors the user has probably
            // written a vec-vec `*` which the language forbids; the
            // C compile error is acceptable feedback.
            out.push('(');
            out.push_str(&c_type_name_for_dim(d));
            out.push_str("){");
            for (i, c) in comps.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                let op_str = if matches!(op, BinOp::Mul) { "*" } else { "/" };
                out.push('(');
                emit_expr(out, lhs, cx)?;
                out.push('.');
                out.push_str(c);
                out.push(' ');
                out.push_str(op_str);
                out.push(' ');
                emit_expr(out, rhs, cx)?;
                out.push(')');
            }
            out.push('}');
            out.push(')');
            Ok(())
        }
        _ => Err(CodegenError::Unsupported {
            message: format!("operator `{}` not defined on vec", op),
            span: expr_span(lhs),
        }),
    }
}

fn c_type_name_for_dim(d: u32) -> &'static str {
    match d {
        2 => "spass_vec2",
        3 => "spass_vec3",
        4 => "spass_vec4",
        _ => "double",
    }
}

/// Determine the vec dimension of an expression's LHS type, if any.
/// Returns `None` for scalars (which is the common case).
fn lhs_type_dim(lhs: &Expr, cx: &Ctx<'_>) -> Option<u32> {
    let ty = match lhs {
        Expr::Ident { name, .. } => lookup_local_type(name, cx)?,
        _ => return None,
    };
    vec_dim(&ty)
}

/// Return `true` when the expression's static type is a numeric
/// scalar (float / int / uint). Used to decide whether a vec OP
/// expr should broadcast the rhs (e.g. `v + 1.0`) instead of
/// taking the rhs's `.x` component.
///
/// `ponytail`: only resolves plain `Ident` and literal exprs for
/// now. Function-call results default to "non-scalar" so the
/// caller takes the struct-literal path; the function result will
/// either be a vec (so the path is right) or be rejected by
/// semantic analysis if the type doesn't match. The MVP doesn't
/// need a full type inference pass at codegen time.
fn is_scalar_expr(e: &Expr, cx: &Ctx<'_>) -> bool {
    match e {
        Expr::FloatLit { .. } | Expr::IntLit { .. } | Expr::BoolLit { .. } => true,
        Expr::Ident { name, .. } => {
            if let Some(ty) = lookup_local_type(name, cx) {
                matches!(ty, Type::Float(_) | Type::Int(_) | Type::Uint(_))
            } else {
                false
            }
        }
        _ => false,
    }
}

fn const_int_pow2(e: &Expr) -> Option<u32> {
    if let Expr::IntLit { value, .. } = e {
        if *value > 0 && (*value & (*value - 1)) == 0 {
            Some(value.trailing_zeros())
        } else {
            None
        }
    } else {
        None
    }
}

fn rational_to_f64(r: &num_rational::Rational64) -> f64 {
    let numer = *r.numer() as f64;
    let denom = *r.denom() as f64;
    numer / denom
}

fn infer_c_type(expr: &Expr, _cx: &Ctx<'_>) -> CodegenResult<String> {
    Ok(match expr {
        Expr::IntLit { .. } => "int32_t".to_string(),
        Expr::FloatLit { .. } => "double".to_string(),
        Expr::BoolLit { .. } => "bool".to_string(),
        Expr::StringLit { .. } => "const char*".to_string(),
        Expr::ListLit { .. } => "SpassList".to_string(),
        // spawn/parallel produce an opaque task handle.
        Expr::Spawn { .. } | Expr::Parallel { .. } => "uint64_t".to_string(),
        Expr::Ident { name, .. } => {
            // Default to double for unknown idents; semantic pass should
            // have caught real type errors.
            let _ = name;
            "double".to_string()
        }
        _ => "double".to_string(),
    })
}

/// Rust twin of [`infer_c_type`]. The two functions share the same
/// shape because the underlying Spass types are 1:1, but the names
/// differ (`f64` vs `double`, `i32` vs `int32_t`,...). 
/// relies on the Rust path returning proper Rust types so the
/// `let mut x: <ty> =...` for an unannotated binding compiles
/// without the C-ABI `double` leaking into the Rust output.
fn infer_rust_type(expr: &Expr, _cx: &Ctx<'_>) -> CodegenResult<String> {
    Ok(match expr {
        Expr::IntLit { .. } => "i32".to_string(),
        Expr::FloatLit { .. } => "f64".to_string(),
        Expr::BoolLit { .. } => "bool".to_string(),
        Expr::StringLit { .. } => "&'static str".to_string(),
        Expr::ListLit { elements, .. } => {
            let inner = elements
                .first()
                .and_then(literal_type)
                .unwrap_or(Type::Float(None));
            format!("Vec<{}>", rust_scalar_type(&inner))
        }
        Expr::Ident { name, .. } => {
            // Default to f64 for unknown idents; semantic pass should
            // have caught real type errors. The MVP treats every
            // untyped local as an f64 - this matches the C emitter's
            // default and keeps the Rust path in sync.
            let _ = name;
            "f64".to_string()
        }
        // spawn/parallel produce an opaque task handle.
        Expr::Spawn { .. } | Expr::Parallel { .. } => "u64".to_string(),
        // a receive binds the message struct named by
        // its filter pattern.
        Expr::Receive { pattern: Some(p), .. } => p.type_name.clone(),
        _ => "f64".to_string(),
    })
}

// ============================================================================
// Built-in mapping
// ============================================================================

fn builtin_mapping(name: &str) -> Option<&'static str> {
    match name {
        "sin" => Some("spass_sin"),
        "cos" => Some("spass_cos"),
        "tan" => Some("spass_tan"),
        "sqrt" => Some("spass_sqrt"),
        "abs" => Some("spass_abs"),
        "floor" => Some("spass_floor"),
        "ceil" => Some("spass_ceil"),
        "round" => Some("spass_round"),
        "exp" => Some("spass_exp"),
        "log" => Some("spass_log"),
        "pow" => Some("spass_pow"),
        "lerp" => Some("spass_lerp"),
        "clamp" => Some("spass_clamp"),
        "smoothstep" => Some("spass_smoothstep"),
        "max" => Some("spass_max"),
        "min" => Some("spass_min"),
        "noise" => Some("spass_noise_2d"),
        "fbm" => Some("spass_fbm"),
        // Conversions. The semantic pass types these as unary functions,
        // so we cannot emit a regular function call here - the C/Rust
        // emitter must expand them to inline cast expressions instead.
        // See the special case in `emit_expr` for `Expr::Call` below.
        "to_int" | "to_float" => Some("__spass_cast_builtin__"),
        _ => None,
    }
}

/// Map a vec/mat built-in name to its dimension-specific runtime
/// symbol, based on the type of the first argument. `dot`,
/// `length`, `normalize`, `hadamard` are vector built-ins; `cross`
/// is vec3-only; `transpose` is matrix-only. The MVP doesn't ship
/// `inverse` (see runtime.c). `ponytail`: we don't track return
/// types here - the runtime symbol's argument list is the source
/// of truth. The vec constructors (`mk_vec*`) are dispatched by
/// argument count instead of by the first arg's type.
pub(crate) fn vec_mat_builtin(name: &str, args: &[CallArg], cx: &Ctx<'_>) -> Option<&'static str> {
    // Vec constructors - picked by arity, not first-arg type.
    // The semantic pass accepts the call shape; the codegen layer
    // names the runtime symbol. `ponytail`: a future revision
    // that adds vec literal syntax can route through the same
    // dispatch (e.g. `vec3(1, 2, 3)` -> `spass_mk_vec3(1, 2, 3)`).
    if name == "mk_vec2" && args.len() == 2 {
        return Some("spass_mk_vec2");
    }
    if name == "mk_vec3" && args.len() == 3 {
        return Some("spass_mk_vec3");
    }
    if name == "mk_vec4" && args.len() == 4 {
        return Some("spass_mk_vec4");
    }
    if args.is_empty() {
        return None;
    }
    let first = &args[0].value;
    let ty = first_arg_type(first, cx)?;
    match name {
        "dot" => {
            let d = vec_dim(&ty)?;
            Some(match d {
                2 => "spass_dot2",
                3 => "spass_dot3",
                4 => "spass_dot4",
                _ => return None,
            })
        }
        "length" => {
            let d = vec_dim(&ty)?;
            Some(match d {
                2 => "spass_length2",
                3 => "spass_length3",
                4 => "spass_length4",
                _ => return None,
            })
        }
        "normalize" => {
            let d = vec_dim(&ty)?;
            Some(match d {
                2 => "spass_normalize2",
                3 => "spass_normalize3",
                4 => "spass_normalize4",
                _ => return None,
            })
        }
        "hadamard" => {
            let d = vec_dim(&ty)?;
            Some(match d {
                2 => "spass_hadamard2",
                3 => "spass_hadamard3",
                4 => "spass_hadamard4",
                _ => return None,
            })
        }
        "cross" => {
            // cross is vec3-only. The runtime symbol
            // is the same for any dim, but the language restricts the
            // argument shape so the type check suffices.
            let d = vec_dim(&ty)?;
            if d == 3 {
                Some("spass_cross")
            } else {
                None
            }
        }
        "transpose" => {
            let d = mat_dim(&ty)?;
            Some(match d {
                3 => "spass_transpose3",
                4 => "spass_transpose4",
                _ => return None,
            })
        }
        _ => None,
    }
}

/// Determine the type of an expression at codegen time. Only
/// resolves the shapes that the vec/mat dispatch cares about:
/// identifiers (looked up in the enclosing function's scope) and
/// component access on a vec (target is a vec, the access returns
/// a scalar - not useful for the dispatch, so we report `None`).
/// `ponytail`: a richer version of this helper would also walk
/// `let` chains, function calls, and `FieldAccess`/`Index` shapes;
/// the MVP only needs identifiers.
fn first_arg_type(expr: &Expr, cx: &Ctx<'_>) -> Option<Type> {
    match expr {
        Expr::Ident { name, .. } => lookup_local_type(name, cx),
        // vec-vec add/sub preserves the vec type, so built-ins like
        // `length(p - c)` still dispatch to the right dimension.
        Expr::Binary { op: BinOp::Add | BinOp::Sub, lhs, rhs, .. } => {
            let lt = first_arg_type(lhs, cx)?;
            let rt = first_arg_type(rhs, cx)?;
            if vec_dim(&lt).is_some() && vec_dim(&rt).is_some() && lt == rt {
                Some(lt)
            } else {
                None
            }
        }
        _ => None,
    }
}

// ============================================================================
// Name mangling
//
// Format: `_spass_<name>_<param_count>_<param1>_<param2>_...`
// Parsing: right-to-left reverse scan.
// ============================================================================

// ============================================================================
// Async spawn
// ============================================================================

/// A `random` candidate has to be callable through a plain function
/// pointer: the same scalar shape as a spawn thunk, and no
/// `if_present` variant to choose between.
fn random_candidate_compatible(f: &TypedFunc) -> bool {
    !f.has_if_present
        && f.captures.is_empty()
        && f.params.iter().all(|p| matches!(p.ty, Type::Float(None) | Type::Int(None)))
        && matches!(f.return_type.as_ref(), Some(Type::Float(None)) | Some(Type::Int(None)))
}

/// The async runtime marshals arguments and results through f64 slots, so
/// only functions with plain float/int params and a float/int return can
/// be spawned for now. Value-domain params have a uintN ABI and vec/struct
/// params need a bigger marshalling protocol - the upgrade path is a
/// typed arg-pack instead of a `double[]`.
fn spawn_thunk_compatible(f: &TypedFunc) -> bool {
    // `if_present` functions compile to present/absent variants; which
    // variant a spawned call should take is undefined for now, so they
    // are excluded from the spawn surface.
    //
    // A closure that captures variables has a different ABI: the hoisted
    // helper takes the captured values as extra leading parameters, and a
    // module-scope thunk has no way to supply them - the capture lives in
    // the enclosing function's frame.
    !f.has_if_present
        && f.captures.is_empty()
        && f.params.iter().all(|p| matches!(p.ty, Type::Float(None) | Type::Int(None)))
        && matches!(f.return_type.as_ref(), Some(Type::Float(None)) | Some(Type::Int(None)))
}

fn spawn_thunk_name(f: &TypedFunc) -> String {
    format!("__sp_spawn_thunk_{}", mangle_function_name(f))
}

/// Emit one worker thunk per spawn-compatible function. The thunk adapts
/// the runtime's uniform `(const double[], double*)` protocol to the
/// callee's real ABI. We emit thunks for ALL compatible functions rather
/// than scanning the AST for `spawn` sites - unused thunks cost a few
/// dead lines and the emitter stays single-pass (`ponytail`).
fn emit_spawn_thunks_c(out: &mut String, module: &TypedModule) {
    let compat: Vec<&TypedFunc> =
        module.functions.iter().filter(|f| spawn_thunk_compatible(f)).collect();
    if compat.is_empty() {
        return;
    }
    out.push_str("/* Async spawn thunks */\n");
    for f in compat {
        let name = spawn_thunk_name(f);
        let mut call_args = String::new();
        for (i, p) in f.params.iter().enumerate() {
            if i > 0 {
                call_args.push_str(", ");
            }
            match p.ty {
                Type::Int(_) => call_args.push_str(&format!("(int32_t)__sp_args[{}]", i)),
                _ => call_args.push_str(&format!("__sp_args[{}]", i)),
            }
        }
        let mangled = mangle_function_name(f);
        let ret = match f.return_type.as_ref() {
            Some(Type::Int(_)) => format!("(double){}", mangled),
            _ => mangled,
        };
        let _ = writeln!(
            out,
            "static void {}(const double* __sp_args, double* __sp_out) {{ *(__sp_out) = {}({}); }}",
            name, ret, call_args
        );
    }
    out.push('\n');
}

fn emit_spawn_thunks_rust(out: &mut String, module: &TypedModule) {
    let compat: Vec<&TypedFunc> =
        module.functions.iter().filter(|f| spawn_thunk_compatible(f)).collect();
    if compat.is_empty() {
        return;
    }
    out.push_str("// Async spawn thunks.\n");
    for f in compat {
        let name = spawn_thunk_name(f);
        let mut call_args = String::new();
        for (i, p) in f.params.iter().enumerate() {
            if i > 0 {
                call_args.push_str(", ");
            }
            match p.ty {
                Type::Int(_) => call_args.push_str(&format!("args[{}] as i32", i)),
                _ => call_args.push_str(&format!("args[{}]", i)),
            }
        }
        let mangled = mangle_function_name(f);
        let ret = match f.return_type.as_ref() {
            Some(Type::Int(_)) => format!("{}({}) as f64", mangled, call_args),
            _ => format!("{}({})", mangled, call_args),
        };
        let _ = writeln!(
            out,
            "fn {}(args: &[f64], out: &mut f64) {{ *out = {}; }}",
            name, ret
        );
    }
    out.push('\n');
}

// ============================================================================
// Sequence message passing
// ============================================================================

fn seq_id_const(name: &str) -> String {
    format!("__SP_SEQ_ID_{}", name)
}

/// Sequence-id constant of the function being emitted. Only sequence
/// bodies may `receive`.
fn seq_self_id(cx: &Ctx<'_>, span: spass_lexer::Span) -> CodegenResult<String> {
    let fname = cx
        .current_func
        .map(|f| f.name.as_str())
        .unwrap_or("");
    let module = cx.module.as_ref().ok_or_else(|| CodegenError::Unsupported {
        message: "no module context".into(),
        span: span.clone(),
    })?;
    module
        .sequences
        .iter()
        .find(|s| s.name == fname)
        .map(|s| seq_id_const(&s.name))
        .ok_or_else(|| CodegenError::Unsupported {
            message: "`receive` is only valid inside a `sequence` body".into(),
            span,
        })
}

/// Message structs marshal through a fixed 8-slot f64 array, so only
/// structs with at most 8 float/int fields can travel on a queue.
fn seq_msg_compatible(s: &TypedStruct) -> bool {
    s.fields.len() <= 8
        && s.fields
            .iter()
            .all(|(_n, t)| matches!(t, Type::Float(None) | Type::Int(None)))
}

/// Resolve the struct type of a `send`/`broadcast` message expression.
/// Either a struct literal (`Alert{...}`) or an identifier bound to a
/// struct value.
fn seq_message_struct(
    message: &Expr,
    cx: &Ctx<'_>,
    span: spass_lexer::Span,
) -> CodegenResult<TypedStruct> {
    let module = cx.module.as_ref().ok_or_else(|| CodegenError::Unsupported {
        message: "no module context".into(),
        span: span.clone(),
    })?;
    let name = match message {
        Expr::StructLit { name, .. } => name.clone(),
        Expr::Ident { name, .. } => match lookup_local_type(name, cx) {
            Some(Type::Struct(n, _)) => n,
            _ => {
                return Err(CodegenError::Unsupported {
                    message: format!("`{}` is not a struct value", name),
                    span,
                })
            }
        },
        _ => {
            return Err(CodegenError::Unsupported {
                message: "message must be a struct literal or a struct variable".into(),
                span,
            })
        }
    };
    let s = module
        .structs
        .iter()
        .find(|s| s.name == name)
        .cloned()
        .ok_or_else(|| CodegenError::Unsupported {
            message: format!("unknown struct `{}`", name),
            span: span.clone(),
        })?;
    if !seq_msg_compatible(&s) {
        return Err(CodegenError::Unsupported {
            message: format!(
                "message type `{}` must have at most 8 float/int fields",
                s.name
            ),
            span: span.clone(),
        });
    }
    Ok(s)
}

/// Emit the runtime pack call for a message: `__sp_pack_X((double)((msg).f0),...)`.
fn pack_call_c(s: &TypedStruct, message: &Expr, cx: &mut Ctx<'_>) -> CodegenResult<String> {
    let mut args = String::new();
    for (i, (fname, _fty)) in s.fields.iter().enumerate() {
        if i > 0 {
            args.push_str(", ");
        }
        args.push_str("(double)(((");
        let mut tmp = String::new();
        emit_expr(&mut tmp, message, cx)?;
        args.push_str(&tmp);
        args.push_str(&format!(").{}))", fname));
    }
    Ok(format!("__sp_pack_{}({})", s.name, args))
}

fn pack_call_rust(s: &TypedStruct, message: &Expr, cx: &mut Ctx<'_>) -> CodegenResult<String> {
    let mut args = String::new();
    for (i, (fname, _fty)) in s.fields.iter().enumerate() {
        if i > 0 {
            args.push_str(", ");
        }
        args.push_str("((");
        let mut tmp = String::new();
        emit_rust_expr(&mut tmp, message, cx)?;
        args.push_str(&tmp);
        args.push_str(&format!(").{}) as f64", fname));
    }
    Ok(format!("__sp_pack_{}({})", s.name, args))
}

/// Emit per-struct pack/unpack helpers plus the sequence-id constants.
/// We emit helpers for every compatible struct rather than scanning the
/// bodies for message types - unused helpers cost a few dead lines and
/// the emitter stays single-pass (`ponytail`).
fn emit_seq_helpers_c(out: &mut String, module: &TypedModule) {
    if module.sequences.is_empty() {
        return;
    }
    out.push_str("/* Sequence ids */\n");
    out.push_str("enum {\n");
    for (i, s) in module.sequences.iter().enumerate() {
        let _ = writeln!(out, "    {} = {},", seq_id_const(&s.name), i);
    }
    out.push_str("};\n\n");

    let msgs: Vec<&TypedStruct> =
        module.structs.iter().filter(|s| seq_msg_compatible(s)).collect();
    if msgs.is_empty() {
        return;
    }
    out.push_str("/* Sequence message pack/unpack helpers */\n");
    for s in msgs {
        let params: Vec<String> = (0..s.fields.len()).map(|i| format!("double v{}", i)).collect();
        let _ = writeln!(
            out,
            "static spass_msg_t __sp_pack_{}({}) {{\n    spass_msg_t m; m.n = {};",
            s.name,
            params.join(", "),
            s.fields.len()
        );
        for (i, _f) in s.fields.iter().enumerate() {
            let _ = writeln!(out, "    m.f[{}] = v{};", i, i);
        }
        let _ = writeln!(out, "    return m;\n}}");
        let _ = writeln!(out, "static {} __sp_unpack_{}(spass_msg_t m) {{\n    {} r;", s.name, s.name, s.name);
        for (i, (fname, fty)) in s.fields.iter().enumerate() {
            let cast = match fty {
                Type::Int(_) => "(int32_t)",
                _ => "",
            };
            let _ = writeln!(out, "    r.{} = {}m.f[{}];", fname, cast, i);
        }
        let _ = writeln!(out, "    return r;\n}}");
    }
    out.push('\n');
}

fn emit_seq_helpers_rust(out: &mut String, module: &TypedModule) {
    if module.sequences.is_empty() {
        return;
    }
    out.push_str("// Sequence ids.\n");
    for (i, s) in module.sequences.iter().enumerate() {
        let _ = writeln!(out, "const {}: usize = {};", seq_id_const(&s.name), i);
    }
    out.push('\n');

    let msgs: Vec<&TypedStruct> =
        module.structs.iter().filter(|s| seq_msg_compatible(s)).collect();
    if msgs.is_empty() {
        return;
    }
    out.push_str("// Sequence message pack/unpack helpers.\n");
    for s in msgs {
        let slots: Vec<String> = (0..8).map(|i| if i < s.fields.len() { format!("v{}", i) } else { "0.0".to_string() }).collect();
        let _ = writeln!(
            out,
            "fn __sp_pack_{}({}) -> SpassMsg {{ SpassMsg {{ f: [{}], n: {} }} }}",
            s.name,
            (0..s.fields.len()).map(|i| format!("v{}: f64", i)).collect::<Vec<_>>().join(", "),
            slots.join(", "),
            s.fields.len()
        );
        let fields: Vec<String> = s
            .fields
            .iter()
            .enumerate()
            .map(|(i, (fname, fty))| {
                let cast = match fty {
                    Type::Int(_) => " as i32",
                    _ => "",
                };
                format!("{}: m.f[{}]{}", fname, i, cast)
            })
            .collect();
        let _ = writeln!(
            out,
            "fn __sp_unpack_{}(m: SpassMsg) -> {} {{ {} {{ {} }} }}",
            s.name,
            s.name,
            s.name,
            fields.join(", ")
        );
    }
    out.push('\n');
}

/// Encode a single Spass type into its name-mangling code.
pub fn mangle_type(ty: &Type) -> String {
    match ty {
        Type::Float(_) => "f".to_string(),
        Type::Int(_) => "i".to_string(),
        Type::Uint(_) => "u".to_string(),
        Type::Bool => "b".to_string(),
        Type::String => "s".to_string(),
        Type::List(inner) => format!("a{}", mangle_type(inner)),
        Type::Vec2(_, _) => "2f".to_string(),
        Type::Vec3(_, _, _) => "3f".to_string(),
        Type::Vec4(_, _, _, _) => "4f".to_string(),
        Type::Mat3 => "m3".to_string(),
        Type::Mat4 => "m4".to_string(),
        Type::Struct(name, _) => format!("s{}", name),
        // task handle mangles as an opaque u64 id.
        Type::Task(_) => "v".to_string(),
    }
}

/// Build the fully-mangled name of a function.
pub fn mangle_function_name(func: &TypedFunc) -> String {
    let mut parts: Vec<String> = vec!["_spass".to_string(), func.name.clone()];
    // (`ownclude`): the hoisted closure shares its name
    // with the enclosing function's scope, so two `ownclude` blocks
    // with the same name but different captures need distinct
    // symbols. We bake the enclosing function's name and each
    // capture's type code into the mangle so the C/Rust ABI stays
    // a flat namespace.
    if func.original.visibility == spass_parser::ast::Visibility::OwnPrivate {
        if let Some(enclosing) = &func.enclosing_func {
            parts.insert(1, enclosing.clone());
        }
        // Capture type codes are appended after the user params so
        // the regular `_spass_<enclosing>_<own>_<arity>_<types>`
        // prefix still matches a substring search for the unmangled
        // ownclude name. The trailing `_c<arity>_<types>` segment
        // distinguishes the closures.
        if !func.captures.is_empty() {
            parts.push("c".to_string());
            parts.push(func.captures.len().to_string());
            for (_, ty) in &func.captures {
                parts.push(mangle_type(ty));
            }
        }
    }
    parts.push(func.params.len().to_string());
    for p in &func.params {
        if p.is_out {
            parts.push(format!("o{}", mangle_type(&p.ty)));
        } else {
            parts.push(mangle_type(&p.ty));
        }
    }
    parts.join("_")
}

/// only Public functions take part in the module's
/// public ABI - the Rust dispatch table, the `_exported` help list,
/// and the CLI manifest. `fileclude` / `ownclude` symbols are still
/// emitted (with internal linkage) but never enter the public
/// namespace, so `spass run` cannot reach them and external
/// consumers cannot link against them.
pub fn is_public_export(f: &TypedFunc) -> bool {
    f.original.visibility == spass_parser::ast::Visibility::Public
}

/// Build the mangled name of a function variant - the same as
/// [`mangle_function_name`] but with `_present` / `_absent` appended
/// The suffix is appended to the whole mangle so a
/// present variant and an absent variant of the same function live
/// at distinct C-ABI symbols and the dispatcher can pick one by
/// symbol name.
///
/// `ponytail`: the suffix is appended after the parameter list
/// (not after the function name) so any caller doing a substring
/// search for the unmangled name still finds the variant; future
/// compiler-side tooling that knows about variants can also match
/// the full `_present` / `_absent` suffix. Adding a future variant
/// (e.g. `_deferred`) only needs a new arm.
pub fn mangle_function_name_variant(func: &TypedFunc, variant: if_present_codegen::Variant) -> String {
    let suffix = match variant {
        if_present_codegen::Variant::Present => "present",
        if_present_codegen::Variant::Absent => "absent",
    };
    format!("{}_{}", mangle_function_name(func), suffix)
}

/// Mangle a function for a *call site* - the symbol the callee is
/// invoked under. For functions with `if_present` we always invoke
/// the present variant (Spass has no syntax for omitting a positional
/// argument at a call site, so every param is always passed). The
/// absent variant only exists for direct CLI access (where the user
/// explicitly asks for the absent behaviour).
pub fn mangle_for_call(func: &TypedFunc) -> String {
    if func.has_if_present {
        mangle_function_name_variant(func, if_present_codegen::Variant::Present)
    } else {
        mangle_function_name(func)
    }
}

// ============================================================================
// Rust emitter (MVP - used for `spass run` until a C compiler is available)
// ============================================================================
//
// The C emitter above is the language-mandated backend.
// For the MVP we also emit a Rust program that:
// * mirrors the same C-ABI naming (`pub extern "C" fn _spass_*`),
// * provides a Rust-side implementation of the runtime (`spass_sin` etc.),
// * wires a `main` that dispatches CLI args to a function call.
//
// The Rust emitter uses the same AST walk as the C emitter. We keep them in
// one file because the two outputs share a lot of helper logic; splitting
// would be premature.

/// How the emitted Rust module is packaged.
///
/// The two flavours differ only in what the host gets: a program is
/// launched and dispatches on `argv`, a shared library is loaded into the
/// host's process and called through its exported symbols.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum RustFlavor {
    /// A standalone program: `fn main` dispatches on `argv[1]`.
    Program,
    /// A shared library (deeppack): the public functions are exported
    /// with `#[no_mangle]` so the host can resolve them by symbol name,
    /// and there is no `main`.
    Cdylib,
}

/// Emit a runnable Rust program. `entry` is the function to call when the
/// user does not pick one with `--func`. If `None`, `main` will look up
/// the function from `argv`.
pub fn generate_rust(typed: &TypedModule) -> CodegenResult<String> {
    generate_rust_with(typed, RustFlavor::Program)
}

/// Emit the Rust module in the requested packaging flavour.
pub fn generate_rust_with(typed: &TypedModule, flavor: RustFlavor) -> CodegenResult<String> {
    generate_rust_with_plan(typed, flavor, None)
}

/// The same, but with a plan: the bodies the optimiser produced.
///
/// A function that is in the plan is emitted from the plan's body; a
/// function that is not is emitted from its source body, exactly as it
/// was before the optimiser existed.
pub fn generate_rust_with_plan(
    typed: &TypedModule,
    flavor: RustFlavor,
    plan: Option<&ModulePlan>,
) -> CodegenResult<String> {
    let mut out = String::new();
    out.push_str("// Generated by spass-codegen. Do not edit.\n");
    // Spass `let` is mutable by default (reassignment is allowed), so the
    // emitter writes `let mut` for every binding. The Rust compiler then
    // warns about `unused_mut` whenever the variable is never reassigned.
    // Rather than tracking assignments precisely, suppress the warning
    // for the generated module.
    out.push_str("#![allow(dead_code, unused_imports, unused_mut, unused_parens, unused_variables, unused_assignments, non_upper_case_globals)]\n");
    // Spass function symbols are mangled with the C ABI in mind
    // (`_spass_<name>_<arity>_<type1>_<type2>...`) so the names end up
    // non-snake-case on the Rust side. The compiler treats them as
    // opaque symbols, so the warning is noise.
    out.push_str("#![allow(non_snake_case)]\n");
    // The per-function state structs follow the same `_spass_<name>_<arity>_<types>_state_t`
    // mangled shape - same reason as `non_snake_case`. The C ABI
    // uses these names for the matching C-side structs, so we
    // can't rename them to UpperCamelCase without breaking
    // cross-backend symbol parity.
    out.push_str("#![allow(non_camel_case_types)]\n\n");
    out.push_str("use std::f64::consts::PI;\n");
    // Only the program flavour reads the command line.
    if flavor == RustFlavor::Program {
        out.push_str("use std::env;\n");
    }
    out.push('\n');

    // Runtime prelude. Only the sections the program actually uses
    // are emitted: the prelude is inlined into every generated module,
    // so its size is a direct cost on the compile time of every
    // Spass program.
    let sections = RuntimeSections::detect(typed);
    emit_rust_runtime_core(&mut out);
    if sections.vec_mat {
        emit_rust_runtime_vec_mat(&mut out);
    }
    if sections.spasio {
        emit_rust_runtime_spasio(&mut out);
    }
    if sections.tasks {
        emit_rust_runtime_tasks(&mut out);
    }
    if sections.sequences {
        emit_rust_runtime_sequences(&mut out);
    }
    // spass playground runtime (s2d:/s3d:/spio:), embedded verbatim
    // from the standalone spass-playground crate sources. It is the
    // largest runtime section by far, so it is emitted only for the
    // programs that call into those namespaces.
    if sections.playground {
        out.push_str(include_str!("../../spass-playground/src/playground.rs"));
        out.push('\n');
    }
    out.push('\n');

    // Async spawn thunks.
    emit_spawn_thunks_rust(&mut out, typed);

    // Sequence ids + message pack/unpack helpers.
    emit_seq_helpers_rust(&mut out, typed);

    // Structs. We derive `Clone, Copy, Debug, Default` and add
    // `#[repr(C)]`:
    // * `Clone, Copy` - every field is `f64` (or a value-domain uintN
    // encoded as the field's f64 shadow), so `Copy` is free; the
    // value-pass ABI for FFI relies on it.
    // * `Debug` - required by the dispatcher in `main`, which uses
    // `{:?}` to print struct return values.
    // * `Default` - used to zero-fill any struct field that the
    // dispatcher has no CLI arg for (so a missing positional field
    // yields a zero, not a panic).
    // * `#[repr(C)]` - guarantees a stable layout that matches the
    // C `typedef struct {... } Name;` emitted by the C backend,
    // so a `extern "C"` function with struct params/returns stays
    // FFI-safe. Without it rustc warns and the program is not
    // guaranteed to interop correctly.
    for s in &typed.structs {
        let _ = writeln!(out, "#[repr(C)]");
        let _ = writeln!(out, "#[derive(Clone, Copy, Debug, Default)] pub struct {} {{", s.name);
        for (fname, _fty) in &s.fields {
            let _ = writeln!(out, "    pub {}: f64,", fname);
        }
        let _ = writeln!(out, "}}");
    }
    if !typed.structs.is_empty() {
        out.push('\n');
    }

    // Multi-return helpers. We emit one `#[repr(C)]` struct per
    // multi-return arity so the Rust ABI matches the C struct layout.
    // Without `repr(C)`, Rust tuples have unspecified layout and the
    // `extern "C"` boundary triggers a hard FFI-safety warning.
    let mut emitted_mr_structs: std::collections::HashSet<usize> = std::collections::HashSet::new();
    for func in &typed.functions {
        if let Some(mr) = &func.multi_returns {
            let arity = mr.len();
            if emitted_mr_structs.insert(arity) {
                let _ = writeln!(out, "#[repr(C)]");
                // `Debug` is required by the dispatcher in `main`,
                // which formats multi-return values with `{:?}`. Without
                // it, the generated program fails to compile (E0277).
                let _ = writeln!(out, "#[derive(Clone, Copy, Debug)]");
                let _ = writeln!(out, "pub struct SpassRet{} {{", arity);
                for (i, t) in mr.iter().enumerate() {
                    let _ = writeln!(out, "    pub _f{}: {},", i, rust_scalar_type(t));
                }
                let _ = writeln!(out, "}}");
            }
        }
    }

    // (cross-function @resume, D5): when ANY function in
    // the program has a suspension point, emit the `SpassState` trait
    // and the cross-function task registry ONCE at the top of the
    // generated source. Each state-machine function then implements
    // the trait and registers/unregisters its state through the
    // shared registry, so different functions with different state
    // struct types can dispatch into each other via `Box<dyn SpassState>`.
    let any_suspension = typed
        .functions
        .iter()
        .any(|f| body_has_suspension(&f.original.body.stmts));
    if any_suspension {
        out.push_str(checkpoint_codegen::rust_state_machine_header());
        out.push('\n');
    }

    // Functions.
    let index = CallIndex::build(typed);
    for func in &typed.functions {
        if body_has_suspension(&func.original.body.stmts) {
            emit_state_machine_rust(&mut out, func, typed, &index, flavor)?;
        } else if let Some(fp) = plan.and_then(|p| p.get(&func.name)) {
            // The optimised body. An empty variant list means the
            // function was eliminated: nothing is emitted for it.
            for (variant, body) in &fp.variants {
                let mangled = if func.has_if_present {
                    mangle_function_name_variant(func, *variant)
                } else {
                    mangle_function_name(func)
                };
                emit_rust_function_with_mangled(
                    &mut out,
                    func,
                    typed,
                    &index,
                    &mangled,
                    &body.stmts,
                    &body.readonly,
                    flavor,
                )?;
                out.push('\n');
            }
        } else if func.has_if_present {
            // emit two variants (`_present` and `_absent`).
            // The CLI dispatcher matches the present variant by default;
            // callers can request the absent variant by passing its full
            // mangled name.
            emit_rust_function_variant(
                &mut out,
                func,
                typed,
                &index,
                if_present_codegen::Variant::Present,
                flavor,
            )?;
            out.push('\n');
            emit_rust_function_variant(
                &mut out,
                func,
                typed,
                &index,
                if_present_codegen::Variant::Absent,
                flavor,
            )?;
        } else {
            emit_rust_function(&mut out, func, typed, &index, flavor)?;
        }
        out.push('\n');
    }

    // The dispatcher only exists in the program flavour: a shared
    // library (deeppack) is called through its exported symbols, not
    // through argv. The shared library gets the runner entry points
    // instead: a `.saple` runner has to call a function whose signature
    // it cannot know, so the module dispatches on the symbol name.
    if flavor == RustFlavor::Program {
        emit_rust_dispatcher(&mut out, typed)?;
    } else {
        emit_rust_module_entry(&mut out, typed)?;
    }

    Ok(out)
}

/// Emit the `fn main` dispatcher - the program flavour's entry point.
/// It lists the exported functions, picks one from `argv[1]` and calls it.
fn emit_rust_dispatcher(out: &mut String, typed: &TypedModule) -> CodegenResult<()> {
    // main: list functions, pick one by argv[1] or default to the first.
    // For `if_present` functions, the present variant is the default
    // (CLI always supplies all params); both variants are listed in
    // `_exported` so the help text shows them.
    //
    // the dispatch surface only covers Public functions.
    // `fileclude` helpers cannot be called from outside their file and
    // `ownclude` closures need their captured values threaded in -
    // neither is meaningfully callable through a bare `argv`-driven
    // entry point, and the language removes them from the public
    // namespace entirely.
    let first_name = typed
        .functions
        .iter()
        .find(|f| is_public_export(f))
        .map(mangle_for_call)
        .unwrap_or_default();
    let exported: Vec<String> = typed
        .functions
        .iter()
        .filter(|f| is_public_export(f))
        .flat_map(|f| {
            if f.has_if_present {
                vec![
                    mangle_function_name_variant(f, if_present_codegen::Variant::Present),
                    mangle_function_name_variant(f, if_present_codegen::Variant::Absent),
                ]
            } else {
                vec![mangle_function_name(f)]
            }
        })
        .collect();
    let has_sequences = !typed.sequences.is_empty();
    let _ = write!(
        out,
        "fn main() {{\n    let args: Vec<String> = env::args().collect();\n\
         \n    // List exported functions for help.\n\
         \n    let _exported: &[&str] = &[{}];\n\
         \n    let fname = args.get(1).cloned().unwrap_or_else(|| {:?}.to_string());\n\
         \n    let fargs: Vec<f64> = args.iter().skip(2).filter_map(|a| a.parse().ok()).collect();\n",
        exported.iter().map(|n| format!("{:?}", n)).collect::<Vec<_>>().join(", "),
        first_name,
    );

    // every sequence is instantiated at program start and
    // runs in parallel; the program exits once they have all terminated.
    // The drop guard joins the sequence threads on every exit path from
    // main (dispatch arms `return` early after printing their result).
    // A program without sequences gets none of this, so the generated
    // module never references the sequence runtime.
    if has_sequences {
        let mut seq_spawns = String::new();
        emit_sequence_starts(&mut seq_spawns, typed, "    ");
        // The list is embedded between two newlines; the helper's own
        // trailing newline would leave a blank line behind.
        let seq_spawns = seq_spawns.trim_end_matches('\n');
        let _ = writeln!(
            out,
            "\n    // Start every sequence; join on all exit paths.\n\
             \n    spass_seq_init({});\n{}\n\
             \n    struct __SpSeqJoin;\n    impl Drop for __SpSeqJoin {{ fn drop(&mut self) {{ spass_seq_wait_all(); }} }}\n\
             \n    let __sp_seq_join = __SpSeqJoin;\n",
            typed.sequences.len(),
            seq_spawns,
        );
    }

    // Runner-owned world: the daemon can start this module
    // in FOREVER mode - sequences run until they all terminate (e.g. the
    // game loop's exit condition), then the process exits without
    // dispatching any function. A module without sequences has nothing
    // to wait for, so its arm returns immediately.
    if has_sequences {
        let _ = writeln!(
            out,
            "    if fname == \"__sp_forever\" {{\n        spass_seq_wait_all();\n        return;\n    }}\n"
        );
    } else {
        let _ = writeln!(
            out,
            "    if fname == \"__sp_forever\" {{\n        return;\n    }}\n"
        );
    }

    // Dispatch table. Each function gets one `if fname == "<mangled>"` arm.
    // For `if_present` functions we emit TWO arms: one per variant - the
    // present variant is the default entry (Spass calls always supply every
    // argument) and the absent variant is reachable when the user types
    // its full mangled name on the CLI. Each arm materialises its own
    // arg list and prints its own return value.
    // public-ABI surface only (see `is_public_export`).
    for func in typed.functions.iter().filter(|f| is_public_export(f)) {
        // Build a list of mangled names per arm. For an if_present
        // function there are two arms, one per variant. The body emission
        // is shared (the args/print logic only depends on the function
        // type signature, which is identical across variants).
        let arms: Vec<String> = if func.has_if_present {
            vec![
                mangle_function_name_variant(func, if_present_codegen::Variant::Present),
                mangle_function_name_variant(func, if_present_codegen::Variant::Absent),
            ]
        } else {
            vec![mangle_for_call(func)]
        };
        for mangled in &arms {
            let _ = writeln!(out, "    if fname == {:?} {{", mangled);
            // Out params: we have to materialise a slot per param and pass
            // a mutable reference. The slot is zero-initialised (the same
            // default the C compiler gives an uninitialised scalar); the
            // function body writes to it before returning.
            let (has_out, has_return_value) =
                emit_dispatch_call(out, typed, func, mangled, "        ")?;
            if has_out {
                // Print each out param on its own line, in declaration order.
                // Plain (f64) values use `{}`; value-domain-encoded values
                // are printed as the raw state (callers decode via
                // `spasio-client`).
                for p in func.params.iter().filter(|p| p.is_out) {
                    let _ = writeln!(out, "        println!(\"{{}}\", __sp_slot_{});", p.name);
                }
            } else if has_return_value {
                // Multi-return functions return a tuple; print it with `{:?}`.
                // Struct returns use `{:?}` (Debug is derived
                // on every emitted struct). Plain scalars use `{}`.
                if func.multi_returns.is_some()
                    || matches!(&func.return_type, Some(Type::Struct(_, _)))
                {
                    let _ = writeln!(out, "        println!(\"{{:?}}\", r);");
                } else {
                    let _ = writeln!(out, "        println!(\"{{}}\", r);");
                }
            }
            // Else: void function (no out params, no return value) - print
            // nothing. The function ran, the call site has nothing to show.
            let _ = writeln!(out, "        return;");
            let _ = writeln!(out, "    }}");
        }
    }

    let _ = writeln!(
        out,
        "    eprintln!(\"unknown function: {{}}\", fname);\n    eprintln!(\"usage: <func> [args...]\");\n\
         \n    std::process::exit(1);\n}}"
    );

    Ok(())
}

/// Emit the Rust that reads a call's arguments and makes the call.
///
/// The arguments come from `fargs`, the slice the caller set up: the
/// program dispatcher fills it from `argv`, the module dispatcher from
/// the caller's array. Both therefore take the same numbers for the
/// same function - a value-domain parameter takes its state index, the
/// others their plain value.
///
/// `pad` is the indentation of the emitted lines.
///
/// Returns whether the call has `out` parameters and whether it has a
/// return value.
fn emit_dispatch_call(
    out: &mut String,
    typed: &TypedModule,
    func: &TypedFunc,
    mangled: &str,
    pad: &str,
) -> CodegenResult<(bool, bool)> {
    // Out params: we have to materialise a slot per param and pass
    // a mutable reference. The slot is zero-initialised (the same
    // default the C compiler gives an uninitialised scalar); the
    // function body writes to it before returning.
    let has_out = func.params.iter().any(|p| p.is_out);
    // Whether the call has a printable return value: a scalar/multi
    // return type with no out-params binds to `r`; an out-only or
    // void function does not.
    let has_return_value = !has_out
        && (func.return_type.is_some() || func.multi_returns.is_some());
    if func.params.is_empty() {
        if has_return_value {
            let _ = writeln!(out, "{pad}let r = {mangled}();");
        } else {
            // Void or out-only with zero args: call and discard.
            let _ = writeln!(out, "{pad}{mangled}();");
        }
        return Ok((has_out, has_return_value));
    }
    let _ = writeln!(out, "{pad}let mut _i = 0usize;");
    for p in &func.params {
        if p.is_out {
            // Out param: allocate the encoded slot type, pass `&mut`.
            if let Some(vd) = value_domain(&p.ty) {
                let _ = writeln!(
                    out,
                    "{pad}let mut __sp_slot_{}: {} = 0{};",
                    p.name, vd.rust_type, vd.rust_type
                );
            } else {
                let _ = writeln!(
                    out,
                    "{pad}let mut __sp_slot_{}: {} = 0.0;",
                    p.name,
                    rust_scalar_type(&p.ty)
                );
            }
        } else {
            // In param: read from the argument list, cast to the right
            // type. Scalars and value-domain-encoded uintN come
            // straight from the numeric arg list; struct params
            // are built from the next N positional args, one per
            // field (a missing field is zero). The C/Rust
            // emitters share a single dispatch path.
            let pty = if let Some(vd) = value_domain(&p.ty) {
                vd.rust_type.clone()
            } else {
                rust_scalar_type(&p.ty)
            };
            if let Type::Struct(sname, _) = &p.ty {
                // Struct param: build the struct from the next
                // N args, one per field (positional; a
                // missing field is zero). Looking up the field
                // list in `typed.structs` keeps the dispatcher
                // in sync with the user-defined layout. The
                // struct has `#[derive(Default)]`, so any
                // missing trailing field ends up zero rather
                // than panicking.
                let sname = sname.clone();
                if let Some(sdef) = typed.structs.iter().find(|s| s.name == sname) {
                    let _ = writeln!(out, "{pad}let {}: {} = {} {{", p.name, sname, sname);
                    for (i, (fname, _fty)) in sdef.fields.iter().enumerate() {
                        // Comma goes at the *end* of every
                        // line (Rust struct literals allow a
                        // trailing comma after the last field
                        // too, so the uniform form is safe).
                        let _ = write!(
                            out,
                            "{pad}    {}: fargs.get(_i + {}).copied().unwrap_or(0.0),",
                            fname, i
                        );
                        if i + 1 < sdef.fields.len() {
                            out.push('\n');
                        }
                    }
                    let _ = writeln!(out, "\n{pad}}}; _i += {};", sdef.fields.len());
                } else {
                    // Unknown struct name - fall back to default so codegen
                    // still produces a runnable binary. (Semantic should
                    // have caught this earlier with E006.)
                    let _ = writeln!(
                        out,
                        "{pad}let {}: {} = Default::default(); _i += 1;",
                        p.name, pty,
                    );
                }
            } else {
                let _ = writeln!(
                    out,
                    "{pad}let {}: {} = fargs.get(_i).copied().unwrap_or(0.0) as {}; _i += 1;",
                    p.name, pty, pty,
                );
            }
        }
    }
    let arg_list = func
        .params
        .iter()
        .map(|p| {
            if p.is_out {
                format!("&mut __sp_slot_{}", p.name)
            } else {
                p.name.clone()
            }
        })
        .collect::<Vec<_>>()
        .join(", ");
    if has_out {
        // Out-only functions return `` - no `r`.
        let _ = writeln!(out, "{pad}{mangled}({arg_list});");
    } else {
        let _ = writeln!(out, "{pad}let r = {mangled}({arg_list});");
    }
    Ok((has_out, has_return_value))
}

/// Emit the Rust that writes a call's results into the caller's
/// buffer.
///
/// The `out` parameters come first, in declaration order, then the
/// return value. A struct return and a multi-return contribute one
/// slot per field.
fn emit_dispatch_results(
    out: &mut String,
    typed: &TypedModule,
    func: &TypedFunc,
    has_out: bool,
    pad: &str,
) -> CodegenResult<()> {
    for p in func.params.iter().filter(|p| p.is_out) {
        let _ = writeln!(
            out,
            "{pad}if out_cap > _n {{ unsafe {{ *outs.add(_n) = __sp_slot_{} as f64; }} _n += 1; }}",
            p.name
        );
    }
    // A function with `out` parameters returns nothing the caller can
    // use: the program dispatcher drops the return value in that case
    // too, and the two have to agree.
    if has_out {
        return Ok(());
    }
    if let Some(mr) = &func.multi_returns {
        for i in 0..mr.len() {
            let _ = writeln!(
                out,
                "{pad}if out_cap > _n {{ unsafe {{ *outs.add(_n) = r._f{} as f64; }} _n += 1; }}",
                i
            );
        }
    } else if let Some(Type::Struct(sname, _)) = &func.return_type {
        if let Some(sdef) = typed.structs.iter().find(|s| s.name == *sname) {
            for (fname, _fty) in &sdef.fields {
                let _ = writeln!(
                    out,
                    "{pad}if out_cap > _n {{ unsafe {{ *outs.add(_n) = r.{} as f64; }} _n += 1; }}",
                    fname
                );
            }
        }
    } else if func.return_type.is_some() {
        // Rust does not cast `bool` to `f64`; the uniform numeric entry
        // point represents it as 0/1.
        let value = if matches!(func.return_type, Some(Type::Bool)) {
            "(if r { 1.0 } else { 0.0 })"
        } else {
            "r as f64"
        };
        let _ = writeln!(
            out,
            "{pad}if out_cap > _n {{ unsafe {{ *outs.add(_n) = {value}; }} _n += 1; }}"
        );
    }
    Ok(())
}

/// Emit the Rust that starts the module's sequences.
///
/// every sequence is instantiated at start and runs in
/// parallel. The program flavour does this in `main`; a shared library
/// has no `main`, so the host calls the start entry point instead.
fn emit_sequence_starts(out: &mut String, typed: &TypedModule, pad: &str) {
    for s in &typed.sequences {
        if let Some(f) = typed.functions.iter().find(|f| f.name == s.name) {
            let _ = writeln!(out, "{pad}spass_seq_spawn({});", mangle_for_call(f));
        }
    }
}

/// Emit the entry points a `.saple` runner uses.
///
/// The runner does not call the exported functions one by one: a
/// function's signature is a compiler decision, and the runner has no
/// way to know it. The module therefore exports a uniform entry point
/// that takes the symbol name and the arguments as numbers - the same
/// numbers the command line takes - and writes the results into a
/// buffer.
fn emit_rust_module_entry(out: &mut String, typed: &TypedModule) -> CodegenResult<()> {
    let has_sequences = !typed.sequences.is_empty();

    out.push_str(
        "\n/// Start the module: run the sequences it declares.\n\
         ///\n\
         /// A module without sequences has nothing to start. The symbol is\n\
         /// there either way, so the host does not have to know which it\n\
         /// has.\n\
         #[no_mangle]\n\
         pub extern \"C\" fn spass_module_start() -> i32 {\n",
    );
    if has_sequences {
        let _ = writeln!(out, "    spass_seq_init({});", typed.sequences.len());
        emit_sequence_starts(out, typed, "    ");
    }
    out.push_str("    0\n}\n");

    out.push_str(
        "\n/// Wait for the module's sequences to finish.\n\
         ///\n\
         /// `spass_module_start` launches the sequences and returns; a\n\
         /// host that owns the module's lifetime has to wait for them\n\
         /// before unloading it. A module without sequences returns at\n\
         /// once, so a host can call this unconditionally.\n\
         #[no_mangle]\n\
         pub extern \"C\" fn spass_module_wait() {\n",
    );
    if has_sequences {
        out.push_str("    spass_seq_wait_all();\n");
    }
    out.push_str("}\n");

    out.push_str(
        "\n/// Call an exported function by its mangled symbol name.\n\
         ///\n\
         /// The arguments are the same numbers the command line takes: a\n\
         /// value-domain parameter takes its state index, the others their\n\
         /// plain value. The results - the `out` parameters in declaration\n\
         /// order, then the return value - are written into `outs`.\n\
         ///\n\
         /// The return value is `0` on success and `-1` when the symbol is\n\
         /// not one this module exports.\n\
         #[no_mangle]\n\
         pub extern \"C\" fn spass_module_call(\n\
         \x20   symbol: *const u8,\n\
         \x20   symbol_len: usize,\n\
         \x20   args: *const f64,\n\
         \x20   argc: usize,\n\
         \x20   outs: *mut f64,\n\
         \x20   out_cap: usize,\n\
         ) -> i32 {\n\
         \x20   let name = unsafe { std::slice::from_raw_parts(symbol, symbol_len) };\n\
         \x20   let name = std::str::from_utf8(name).unwrap_or(\"\");\n\
         \x20   let fargs: &[f64] = if argc == 0 {\n\
         \x20       &[]\n\
         \x20   } else {\n\
         \x20       unsafe { std::slice::from_raw_parts(args, argc) }\n\
         \x20   };\n\
         \x20   let mut _n = 0usize;\n",
    );

    for func in typed.functions.iter().filter(|f| is_public_export(f)) {
        let arms: Vec<String> = if func.has_if_present {
            vec![
                mangle_function_name_variant(func, if_present_codegen::Variant::Present),
                mangle_function_name_variant(func, if_present_codegen::Variant::Absent),
            ]
        } else {
            vec![mangle_for_call(func)]
        };
        for mangled in &arms {
            let _ = writeln!(out, "    if name == {:?} {{", mangled);
            let (has_out, _) = emit_dispatch_call(out, typed, func, mangled, "        ")?;
            emit_dispatch_results(out, typed, func, has_out, "        ")?;
            let _ = writeln!(out, "        return 0;");
            let _ = writeln!(out, "    }}");
        }
    }

    out.push_str("    -1\n}\n");
    Ok(())
}

fn emit_rust_function(
    out: &mut String,
    func: &TypedFunc,
    _mod: &TypedModule,
    index: &CallIndex,
    flavor: RustFlavor,
) -> CodegenResult<()> {
    let mangled = mangle_function_name(func);
    let readonly = no_readonly();
    emit_rust_function_with_mangled(
        out,
        func,
        _mod,
        index,
        &mangled,
        &func.original.body.stmts,
        &readonly,
        flavor,
    )
}

/// Emit one variant of an `if_present` function in
/// Rust. Mirror of `emit_function_variant` - the variant has its own
/// mangled symbol and a body with every `if_present` already replaced
/// by the appropriate branch.
fn emit_rust_function_variant(
    out: &mut String,
    func: &TypedFunc,
    module: &TypedModule,
    index: &CallIndex,
    variant: if_present_codegen::Variant,
    flavor: RustFlavor,
) -> CodegenResult<()> {
    let mangled = mangle_function_name_variant(func, variant);
    let body = if_present_codegen::transform_body(&func.original.body.stmts, variant);
    let readonly = no_readonly();
    emit_rust_function_with_mangled(out, func, module, index, &mangled, &body, &readonly, flavor)
}

fn emit_rust_function_with_mangled(
    out: &mut String,
    func: &TypedFunc,
    _mod: &TypedModule,
    index: &CallIndex,
    mangled: &str,
    body: &[Stmt],
    readonly: &std::collections::HashSet<String>,
    flavor: RustFlavor,
) -> CodegenResult<()> {
    // Return value-domain handling. If the function's return type has a
    // value-domain, the ABI returns the encoded uintN; the body encodes
    // the double result at every `return` site.
    let ret_value_domain = func.return_type.as_ref().and_then(value_domain);
    let ret_ty = if let Some(vd) = &ret_value_domain {
        vd.rust_type.clone()
    } else {
        rust_type_name(func.return_type.as_ref(), func.multi_returns.as_ref())
    };
    // The shared-library flavour exports the public functions under
    // their exact symbol name, so the host can resolve them without
    // knowing the Rust mangling scheme. `extern "C"` alone does not
    // prevent Rust from mangling the symbol.
    if flavor == RustFlavor::Cdylib && is_public_export(func) {
        out.push_str("#[no_mangle]\n");
    }
    let _ = write!(
        out,
        "{}extern \"C\" fn {}(",
        if is_public_export(func) { "pub " } else { "" },
        mangled
    );

    // (`ownclude`): the hoisted closure receives the
    // captured values as plain (non-value-domain) leading
    // parameters, matching the C emitter. The names keep the same
    // identifier as the source-side binding so the closure body -
    // which still references `factor`, `base`, etc. - compiles
    // unchanged.
    let mut first = true;
    if func.original.visibility == spass_parser::ast::Visibility::OwnPrivate {
        for (cap_name, cap_ty) in &func.captures {
            if !first {
                out.push_str(", ");
            }
            first = false;
            let _ = write!(out, "{}: {}", cap_name, rust_scalar_type(cap_ty));
        }
    }
    for p in &func.params {
        if !first {
            out.push_str(", ");
        }
        first = false;
        // Param ABI for the Rust emitter:
        // 1. value-domain in: `__<name>: uN` (encoded)
        // 2. value-domain out: `__sp_out_<name>: &mut uN` (slot)
        // 3. plain in: `<name>: f64` (the C type)
        // 4. plain out: `__sp_out_<name>: &mut f64` (slot)
        //
        // Out params use `&mut` so the Rust signature is FFI-safe and
        // matches the C side's pointer ABI. The body operates on a
        // `f64` shadow of the user-visible name and writes back through
        // the reference on assignment.
        //
        // Plain in-params are declared `mut` so the carry in an
        // `@dispatch` left-fold can be reassigned. Rust's `mut` is a
        // local-to-the-function annotation and does not affect the
        // FFI ABI; the generated Rust file disables `unused_mut` so
        // functions that never reassign stay warning-free.
        if p.is_out {
            if let Some(vd) = value_domain(&p.ty) {
                let _ = write!(out, "__sp_out_{}: &mut {}", p.name, vd.rust_type);
            } else {
                let _ = write!(out, "__sp_out_{}: &mut {}", p.name, rust_scalar_type(&p.ty));
            }
        } else if let Some(vd) = value_domain(&p.ty) {
            let _ = write!(out, "__{}: {}", p.name, vd.rust_type);
        } else {
            let _ = write!(out, "mut {}: {}", p.name, rust_scalar_type(&p.ty));
        }
    }
    if first {
    // No params (and no captures): Rust allows `fn foo` for
    // zero-arity. An ownclude with no captures is legal (it's
    // just a plain helper), and the same shape still applies.
    }
    out.push_str(") -> ");
    out.push_str(&ret_ty);
    out.push_str(" {\n");

    let mut cx = Ctx::new(func, _mod, Some(index), body, readonly);

    // Decode value-domain params; out-params get a `f64` shadow that is
    // mirrored back to the caller's slot on assignment.
    for p in &func.params {
        if p.is_out {
            if let Some(vd) = value_domain(&p.ty) {
                let _ = writeln!(
                    out,
                    "    let mut {}: f64 = {} + {} * (*__sp_out_{} as f64);",
                    p.name, vd.min_rs(), vd.step_rs(), p.name
                );
            } else {
                let _ = writeln!(
                    out,
                    "    let mut {}: f64 = *__sp_out_{};",
                    p.name, p.name
                );
            }
            cx.out_params.insert(p.name.clone(), p.ty.clone());
        } else if let Some(vd) = value_domain(&p.ty) {
            let _ = writeln!(
                out,
                "    let {}: f64 = {} + {} * (__{} as f64);",
                p.name, vd.min_rs(), vd.step_rs(), p.name
            );
        }
    }

    for stmt in body {
        emit_rust_stmt(out, stmt, &mut cx)?;
    }

    if !cx.has_return {
        if let Some(vd) = &ret_value_domain {
            // Implicit return: state 0 (the domain's min).
            let _ = writeln!(out, "    return 0{}; /* implicit min = {} */", vd.rust_type, vd.min);
        } else {
            match (&func.return_type, &func.multi_returns) {
                (Some(Type::Struct(name, _)), _) => {
                    // Struct return: zero of the struct via `Default`.
                    let _ = writeln!(out, "    {} {{ ..Default::default() }}", name);
                }
                (Some(_), _) => {
                    out.push_str("    0.0\n");
                }
                (None, Some(mr)) => {
                    // Implicit return: zero of each element type.
                    let zeros: Vec<String> = mr.iter().map(rust_scalar_type).map(|t| match t.as_str() {
                        "f64" => "0.0".to_string(),
                        "i32" => "0".to_string(),
                        "u32" => "0".to_string(),
                        "bool" => "false".to_string(),
                        other => format!("Default::default() /* {} */", other),
                    }).collect();
                    let fields: Vec<String> = (0..mr.len()).map(|i| format!("_f{}: {}", i, zeros[i])).collect();
                    out.push_str(&format!("    SpassRet{} {{ {} }}\n", mr.len(), fields.join(", ")));
                }
                (None, None) => {}
            }
        }
    }

    out.push_str("}\n");
    Ok(())
}

fn rust_type_name(ret: Option<&Type>, multi: Option<&Vec<Type>>) -> String {
    match (ret, multi) {
        (Some(t), _) => rust_scalar_type(t),
        (None, Some(mr)) => {
            // FFI-safe `#[repr(C)]` struct generated by `generate_rust`.
            // Layout matches the C side (struct { T1 _f0; T2 _f1;... }).
            format!("SpassRet{}", mr.len())
        }
        _ => "()".to_string(),
    }
}

fn rust_scalar_type(ty: &Type) -> String {
    match ty {
        Type::Float(_) => "f64".to_string(),
        Type::Int(_) => "i32".to_string(),
        Type::Uint(_) => "u32".to_string(),
        Type::Bool => "bool".to_string(),
        Type::String => "&'static str".to_string(),
        // vector / matrix types. The Rust emitter
        // defines matching structs in the runtime block (see
        // `emit_rust_runtime`). Names match the C side so the
        // FFI contract is uniform.
        Type::Vec2(_, _) => "SpassVec2".to_string(),
        Type::Vec3(_, _, _) => "SpassVec3".to_string(),
        Type::Vec4(_, _, _, _) => "SpassVec4".to_string(),
        Type::Mat3 => "SpassMat3".to_string(),
        Type::Mat4 => "SpassMat4".to_string(),
        // Structs: the user-defined type name doubles as
        // the Rust struct name. Codegen derives `Clone, Copy, Debug` on
        // the emitted struct so the return path can use `{:?}` and
        // value-passes work without explicit clone sites.
        Type::Struct(name, _) => name.clone(),
        // Rust carries a list as the natural `Vec<T>`.
        Type::List(inner) => format!("Vec<{}>", rust_scalar_type(inner)),
        // the task handle is an opaque u64.
        Type::Task(_) => "u64".to_string(),
    }
}

// ============================================================================
// Rust state machine emit
//
// A function whose body uses `@checkpoint name` becomes a state machine
// in Rust too. The shape is the same as the C emitter (wrapper +
// runner), but Rust can't do Duff's device so the runner is a `loop`
// with a `match` on the state id. Each case body is the source-level
// body split at every `@checkpoint`. Re-entry at the saved state id
// just sets the variable and `continue`s the loop.
// ============================================================================

/// Emit a state machine for a checkpointed function (Rust version).
/// The wrapper keeps the original ABI; the runner is a `loop` that
/// dispatches on `state_id`.
fn emit_state_machine_rust(
    out: &mut String,
    func: &TypedFunc,
    module: &TypedModule,
    index: &CallIndex,
    flavor: RustFlavor,
) -> CodegenResult<()> {
    let mangled = mangle_function_name(func);
    let plan = CheckpointPlan::build(func, &mangled);
    let state_ty = state_struct_name(&mangled);

    // --- 1. The state struct -------------------------------------------
    // The runner reads/writes these fields directly. We emit a named
    // struct so the body can use field syntax (`state.foo`).
    let _ = writeln!(out, "#[derive(Clone, Copy)] struct {} {{", state_ty);
    for slot in &plan.layout.slots {
        let _ = writeln!(out, "    {}: f64,", slot.name);
    }
    let _ = writeln!(out, "}}\n");

    // --- 2. The per-function runner ------------------------------------
    // The runner is a free function that drives the state machine
    // forward. It still operates on a `&mut StateT`, so the body
    // emit can use `state.field` syntax unchanged. The cross-
    // function @resume is wired through the `SpassState` trait impl
    // below: a per-function `impl SpassState for StateT` just calls
    // this runner, and the shared `SPASS_TASK_REGISTRY` (emitted at
    // module level by `rust_state_machine_header`) holds the task
    // boxes.
    //
    // The runner body is the existing pattern: `let mut state = t.clone;`,
    // body uses `state.field`, and every `return;` is prefixed with
    // `*t = state;` so the wrapper sees the slice's writes.
    // `plan.runner` is already `{mangled}_runner` (set in
    // `CheckpointPlan::build`), so we use it as-is for the function
    // name. The trait impl below calls it directly via the same
    // name.
    let _ = writeln!(out, "fn {}(t: &mut {}) {{", plan.runner, state_ty);
    let _ = writeln!(out, "    loop {{");
    let _ = writeln!(out, "        match t.__sp_state_id() {{");

    let slices = split_at_checkpoints(&func.original.body.stmts);
    for (i, slice) in slices.iter().enumerate() {
        let _ = writeln!(out, "            {} => {{", i);
        // Capture the body emit into a temporary buffer so we can
        // post-process it: every `return;` gets a `*t = state;`
        // prefix so the wrapper sees the final state.
        let mut slice_buf = String::new();
        let mut cx = Ctx::new(func, module, Some(index), &func.original.body.stmts, no_readonly());
        cx.runner_state = Some(RunnerCtx { plan: &plan });
        for stmt in slice {
            emit_rust_stmt(&mut slice_buf, stmt, &mut cx)?;
        }
        // Prepend `let mut state = t.clone;` so the body emit's
        // `state.field` writes are valid.
        let _ = writeln!(out, "                {{");
        let _ = writeln!(out, "                    let mut state = t.clone();");
        // Walk the captured body and prefix every standalone
        // `return;` with `*t = state;`. The body emit may emit
        // `return;` from `Stmt::Return`; the prefix is what makes
        // the local state visible to the wrapper. A future
        // revision could fold this into the body emit itself
        // by tracking when a return is about to be emitted.
        for line in slice_buf.lines() {
            let trimmed = line.trim_start();
            if trimmed == "return;" {
                // Indent the prefix to match the line's depth.
                let indent: String = line.chars().take_while(|c| c.is_whitespace()).collect();
                let _ = writeln!(out, "{indent}*t = state;");
            }
            let _ = writeln!(out, "{}", line);
        }
        let _ = writeln!(out, "                }}");
        let _ = writeln!(out, "            }}");
    }

    let _ = writeln!(out, "            _ => return,");
    let _ = writeln!(out, "        }}");
    let _ = writeln!(out, "    }}");
    let _ = writeln!(out, "}}\n");

    // --- 3. Per-function trait impl ------------------------------------
    // D5: forward to the per-function runner. This is the bridge that
    // makes cross-function @resume work: the `SPASS_TASK_REGISTRY`
    // holds `Box<dyn SpassState>`, and dispatching `resume` lands
    // here, which dispatches to the right runner for this state
    // type.
    // `plan.runner` is already `_spass_<func>_<arity>_<types>_runner`
    // (set in `CheckpointPlan::build`), so call it directly. A
    // previous revision wrote `{}_runner(self)` here, which produced
    // a `<func>_runner_runner` symbol and the trait impl failed to
    // resolve (the runner is exported as `<func>_runner`).
    let _ = writeln!(out, "impl SpassState for {} {{", state_ty);
    let _ = writeln!(out, "    fn resume(&mut self) {{");
    let _ = writeln!(out, "        {}(self);", plan.runner);
    let _ = writeln!(out, "    }}");
    let _ = writeln!(out, "}}\n");

    // --- 4. Inherent state_id helper (per-function) --------------------
    // The state id is stored in a f64 slot of the state struct
    // itself (the `__sp_state_id` slot reserved by
    // `CheckpointPlan::build` as the first slot). Reading it as a
    // `usize` lets the `match` below dispatch into the right slice.
    //
    // The MVP initial value is 0.0 (entry state); the @checkpoint
    // site updates it to the next slice's id before boxing the
    // state. On every re-entry (whether from the wrapper's
    // `resume` or from a cross-function `@resume`), the trait
    // impl forwards to the per-function runner, which reads the
    // current id and dispatches.
    let _ = writeln!(out, "impl {} {{", state_ty);
    let _ = writeln!(out, "    fn __sp_state_id(&self) -> usize {{ self.__sp_state_id as usize }}");
    let _ = writeln!(out, "}}\n");

    // --- 5. The wrapper ------------------------------------------------
    // The wrapper has the original ABI. It owns a `state` local and
    // calls the runner to drive it. Out-params are passed by `&mut`,
    // mirroring the regular Rust emitter.
    let ret_value_domain = func.return_type.as_ref().and_then(value_domain);
    let ret_ty = if let Some(vd) = &ret_value_domain {
        vd.rust_type.clone()
    } else {
        rust_type_name(func.return_type.as_ref(), func.multi_returns.as_ref())
    };
    if flavor == RustFlavor::Cdylib && is_public_export(func) {
        out.push_str("#[no_mangle]\n");
    }
    let _ = write!(
        out,
        "{}extern \"C\" fn {}(",
        if is_public_export(func) { "pub " } else { "" },
        mangled
    );
    let mut first = true;
    for p in &func.params {
        if !first {
            out.push_str(", ");
        }
        first = false;
        if p.is_out {
            if let Some(vd) = value_domain(&p.ty) {
                let _ = write!(out, "__sp_out_{}: &mut {}", p.name, vd.rust_type);
            } else {
                let _ = write!(out, "__sp_out_{}: &mut {}", p.name, rust_scalar_type(&p.ty));
            }
        } else if let Some(vd) = value_domain(&p.ty) {
            let _ = write!(out, "__{}: {}", p.name, vd.rust_type);
        } else {
            let _ = write!(out, "__{}: {}", p.name, rust_scalar_type(&p.ty));
        }
    }
    out.push_str(") -> ");
    out.push_str(&ret_ty);
    out.push_str(" {\n");

    // Build the state block.
    let _ = writeln!(out, "    let mut __sp_state: {} = {} {{", state_ty, state_ty);
    for slot in &plan.layout.slots {
        match slot.kind {
            StateSlotKind::Param => {
                let p = func
                    .params
                    .iter()
                    .find(|p| p.name == slot.name)
                    .expect("param slot");
                if let Some(vd) = value_domain(&p.ty) {
                    let _ = writeln!(
                        out,
                        "        {}: {} + {} * (__{} as f64),",
                        slot.name, vd.min_rs(), vd.step_rs(), p.name
                    );
                } else {
                    let _ = writeln!(out, "        {}: __{} as f64,", slot.name, p.name);
                }
            }
            StateSlotKind::Let => {
                let _ = writeln!(out, "        {}: 0.0,", slot.name);
            }
            StateSlotKind::Return => {
                let _ = writeln!(out, "        {}: 0.0,", slot.name);
            }
            // the Await slot is reserved for the
            // value bound by `let v = spasio:input[...](...)`
            // following an `@await`. Initialise to 0.0; the
            // runner overwrites it when it actually runs the
            // I/O (in the MVP, inline at the let statement).
            StateSlotKind::Await => {
                let _ = writeln!(out, "        {}: 0.0,", slot.name);
            }
            // D5+ state-id slot. The Rust state-machine runner
            // reads this on every re-entry to know which slice
            // to run. The MVP initial value is 0.0 (entry
            // state); the @checkpoint site updates it to the
            // next slice's id before boxing the state.
            StateSlotKind::StateId => {
                let _ = writeln!(out, "        {}: 0.0,", slot.name);
            }
        }
    }
    let _ = writeln!(out, "    }};");

    // Run the state machine. D5: dispatch through the `SpassState`
    // trait so cross-function @resume (which re-enters the state
    // machine through the shared `SPASS_TASK_REGISTRY`) lands in the
    // right per-function runner. The wrapper owns the state block,
    // so this is just a `resume` call on a local.
    let _ = writeln!(out, "    __sp_state.resume();");

    // Pull out the return value and encode if needed.
    if let Some(ret_name) = &plan.return_slot {
        let _ = writeln!(out, "    let __sp_ret = __sp_state.{};", ret_name);
        if let Some(_mr) = &func.multi_returns {
            return Err(CodegenError::Unsupported {
                message: format!(
                    "multi-return state machines are not supported in MVP (function `{}`)",
                    func.name
                ),
                span: func.original.span.clone(),
            });
        }
        if let Some(vd) = &ret_value_domain {
            let _ = write!(out, "    return ");
            emit_rust_encode(out, vd, true, |o| {
                let _ = write!(o, "__sp_ret");
                Ok(())
            })?;
            out.push_str(";\n");
        } else if func.return_type.is_some() {
            let _ = writeln!(out, "    return __sp_ret;");
        }
    }

    // Mirror out-params back.
    for p in &func.params {
        if !p.is_out {
            continue;
        }
        let _ = writeln!(out, "    let __sp_v = __sp_state.{};", p.name);
        if let Some(vd) = value_domain(&p.ty) {
            let _ = write!(out, "    *__sp_out_{} = ", p.name);
            emit_rust_encode(out, &vd, true, |o| {
                let _ = write!(o, "__sp_v");
                Ok(())
            })?;
            out.push_str(";\n");
        } else {
            let _ = writeln!(out, "    *__sp_out_{} = __sp_v;", p.name);
        }
    }

    out.push_str("}\n");

    Ok(())
}

fn emit_rust_stmt(out: &mut String, stmt: &Stmt, cx: &mut Ctx<'_>) -> CodegenResult<()> {
    match stmt {
        Stmt::Let { names, ty, value, .. } => {
            if cx.runner_state.is_some() {
                // Runner context: every local is a pre-declared
                // f64 field of the state struct. We don't redeclare
                // it; just assign. Destructuring is not supported
                // inside a state machine.
                if names.len() != 1 {
                    return Err(CodegenError::Unsupported {
                        message: "destructuring `let (a, b) = ...` is not supported inside a `@checkpoint` state machine".into(),
                        span: expr_span(value),
                    });
                }
                let _ = write!(out, "    state.{} = ", &names[0]);
                emit_rust_expr(out, value, cx)?;
                out.push_str(";\n");
                let _ = ty;
            } else if names.len() == 1 {
                // when the `let` lacks an explicit
                // type, infer the Rust type rather than the C ABI
                // type. The previous code called `infer_c_type`
                // here, which leaked `double`/`int32_t` into the
                // generated Rust source - a fresh `let mut h =
                // f;` then failed to compile with "cannot find
                // type `double`". The Rust emitter has its own
                // scalar map (`f64`/`i32`/...) so we use it
                // directly for typed bindings and call the
                // Rust-aware inference for untyped ones.
                let cty = match ty {
                    Some(t) => rust_scalar_type(t),
                    None => infer_rust_type(value, cx)?,
                };
                // Spass `let` is mutable by default - the user can
                // reassign. The optimiser tells us when a name is never
                // reassigned anywhere in the body; then `let` is enough.
                if cx.readonly.contains(&names[0]) {
                    let _ = write!(out, "    let {}: {} = ", &names[0], cty);
                } else {
                    let _ = write!(out, "    let mut {}: {} = ", &names[0], cty);
                }
                // The annotation decides the element type, exactly as
                // it does on the C side.
                match (ty, value) {
                    (Some(Type::List(inner)), Expr::ListLit { elements, .. }) => {
                        emit_rust_list_lit(out, elements, inner, cx)?;
                    }
                    _ => emit_rust_expr(out, value, cx)?,
                }
                out.push_str(";\n");
                cx.locals.push(names[0].clone());
                let binding_ty = ty.clone().or_else(|| expr_type(value, cx));
                if let Some(t) = binding_ty {
                    cx.bindings.insert(names[0].clone(), t);
                }
            } else {
                // Destructuring `let (a, b) = f`. The Rust emitter
                // mirrors the C emitter: the call returns a `SpassRet<N>`
                // (a `#[repr(C)]` struct), we bind it to a temporary,
                // then extract each field into a local. We deliberately
                // avoid Rust's native tuple destructuring because the
                // return type is a struct (FFI-safe), not a tuple.
                if let Expr::Call { callee, args, .. } = value {
                    if let Expr::Ident { name, .. } = callee.as_ref() {
                        let f = cx
                            .module
                            .as_ref()
                            .and_then(|m| m.func(name).cloned())
                            .ok_or_else(|| CodegenError::Unsupported {
                                message: format!("call to unknown function `{}`", name),
                                span: expr_span(value),
                            })?;
                        let mangled = mangle_for_call(&f);
                        let mr = f.multi_returns.as_ref().ok_or_else(|| {
                            CodegenError::Unsupported {
                                message: format!(
                                    "`{}` is not a multi-return function",
                                    name
                                ),
                                span: expr_span(value),
                            }
                        })?;
                        let _ = write!(out, "    let __sp_tup: SpassRet{} = ", mr.len());
                        out.push_str(&mangled);
                        out.push('(');
                        for (i, a) in args.iter().enumerate() {
                            if i > 0 {
                                out.push_str(", ");
                            }
                            emit_rust_expr(out, &a.value, cx)?;
                        }
                        out.push_str(");\n");
                        for (i, n) in names.iter().enumerate() {
                            let cty = rust_scalar_type(&mr[i]);
                            let _ = writeln!(out, "    let mut {}: {} = __sp_tup._f{};", n, cty, i);
                            cx.locals.push(n.clone());
                        }
                    } else {
                        return Err(CodegenError::Unsupported {
                            message: "destructuring requires a direct function call".into(),
                            span: expr_span(value),
                        });
                    }
                } else {
                    return Err(CodegenError::Unsupported {
                        message: "destructuring only supported for direct calls".into(),
                        span: expr_span(value),
                    });
                }
            }
        }
        Stmt::Assign { name, value, .. } => {
            if cx.runner_state.is_some() {
                // Runner context: the local lives in the state
                // struct. Just emit `state.<name> = expr;`.
                let _ = write!(out, "    state.{} = ", name);
                emit_rust_expr(out, value, cx)?;
                out.push_str(";\n");
            } else {
                let _ = write!(out, "    {} = ", name);
                emit_rust_expr(out, value, cx)?;
                out.push_str(";\n");
                // Out params: the user-visible name is a `f64` shadow; the
                // real storage is the caller's slot at `__sp_out_<name>`.
                // Mirror the local back through the reference (encoded if
                // value-domain).
                if let Some(ty) = cx.out_params.get(name).cloned() {
                    if let Some(vd) = value_domain(&ty) {
                        let _ = write!(out, "    *__sp_out_{} = ", name);
                        emit_rust_encode(out, &vd, true, |o| {
                            let _ = write!(o, "{}", name);
                            Ok(())
                        })?;
                        out.push_str(";\n");
                    } else {
                        let _ = writeln!(out, "    *__sp_out_{} = {};", name, name);
                    }
                }
            }
        }
        Stmt::Return { value, .. } => {
            if cx.runner_state.is_some() {
                // Runner context: the value goes into the return
                // slot of the state struct. The wrapper reads it
                // back. We don't do the value-domain encode here
                // (the wrapper does it at the ABI boundary).
                if let Some(v) = value {
                    let _ = write!(out, "    state.__sp_return = ");
                    emit_rust_expr(out, v, cx)?;
                    out.push_str(";\n");
                }
                out.push_str("    return;\n");
                cx.has_return = true;
            } else if let Some(v) = value {
                // Take the value-domain out of the Ctx to avoid a borrow
                // conflict with `emit_rust_expr` (which takes `cx` mutably).
                let vd = cx.ret_value_domain.clone();
                if let Some(vd) = vd {
                    // Encode the body result back to the uintN ABI type:
                    // N = round((x - min) * k), clamped to [0, state_count-1]
                    // where `k = 1/step` is the domain's exact reciprocal.
                    out.push_str("    return ");
                    emit_rust_encode(out, &vd, true, |o| emit_rust_expr(o, v, cx))?;
                    out.push_str(";\n");
                } else {
                    out.push_str("    return ");
                    emit_rust_expr(out, v, cx)?;
                    out.push_str(";\n");
                }
            } else {
                out.push_str("    return;\n");
            }
            cx.has_return = true;
        }
        Stmt::Expr(e, _) => {
            out.push_str("    ");
            emit_rust_expr(out, e, cx)?;
            out.push_str(";\n");
        }
        Stmt::If { cond, then_branch, else_branch, .. } => {
            out.push_str("    if ");
            emit_rust_expr(out, cond, cx)?;
            out.push_str(" ");
            emit_rust_block(out, then_branch, cx)?;
            out.push_str(" else ");
            emit_rust_block(out, else_branch, cx)?;
            out.push('\n');
        }
        Stmt::While { cond, body, .. } => {
            out.push_str("    while ");
            emit_rust_expr(out, cond, cx)?;
            out.push_str(" ");
            emit_rust_block(out, body, cx)?;
            out.push('\n');
        }
        Stmt::For { var, iter, body, .. } => match iter {
            spass_parser::ast::ForIter::Range { start, end, step } => {
                out.push_str("    for ");
                let _ = write!(out, "{} in ", var);
                emit_rust_range(out, start, end, step.as_ref(), cx)?;
                out.push(' ');
                emit_rust_block(out, body, cx)?;
                out.push('\n');
            }
            spass_parser::ast::ForIter::List(list_expr) => {
                // iterate the `Vec` by value. `cloned`
                // keeps the loop variable a plain `T` (the type the
                // semantic pass binds) rather than a reference.
                let elem = match expr_type(list_expr, cx) {
                    Some(Type::List(inner)) => *inner,
                    _ => Type::Float(None),
                };
                out.push_str("    for ");
                let _ = write!(out, "{} in (", var);
                emit_rust_expr(out, list_expr, cx)?;
                out.push_str(").iter().cloned() ");
                let previous = cx.bindings.insert(var.clone(), elem);
                emit_rust_block(out, body, cx)?;
                match previous {
                    Some(t) => {
                        cx.bindings.insert(var.clone(), t);
                    }
                    None => {
                        cx.bindings.remove(var);
                    }
                }
                out.push('\n');
            }
        },
        Stmt::Break { .. } => out.push_str("    break;\n"),
        Stmt::Continue { .. } => out.push_str("    continue;\n"),
        Stmt::Checkpoint { .. } | Stmt::Resume { .. } => {
            if cx.runner_state.is_some() {
                match stmt {
                    Stmt::Checkpoint { name, .. } => {
                        // a `@checkpoint` site transitions
                        // the state machine to the next slice. We
                        // (1) set the state id slot, (2) write the
                        // slice's local state back to `*t`, (3) box
                        // the state into the shared `SPASS_TASK_REGISTRY`
                        // under the checkpoint name, and (4) return.
                        // The next `resume` (whether from the wrapper
                        // or from a cross-function `@resume`) re-enters
                        // at the saved state id, dispatching through
                        // the per-function runner via `SpassState`.
                        //
                        // `ponytail`: the lock is held for the
                        // `insert` only, not across the call site.
                        // Holding the lock across `resume` would
                        // deadlock a nested @resume that touches the
                        // same registry; the language forbids cycles, but
                        // the short critical section is the cheap
                        // insurance. The state id is sourced from
                        // `CheckpointPlan::state_id_of`, which is
                        // computed at plan-build time; the runtime
                        // never invents ids on the fly.
                        let next_id = cx
                            .runner_state
                            .map(|rc| rc.plan.state_id_of(name).unwrap_or(0))
                            .unwrap_or(0);
                        let _ = writeln!(out, "    state.__sp_state_id = {} as f64;", next_id);
                        let _ = writeln!(out, "    *t = state;");
                        let _ = writeln!(
                            out,
                            "    {{"
                        );
                        let _ = writeln!(
                            out,
                            "        let __sp_boxed: Box<dyn SpassState> = Box::new(*t);"
                        );
                        let _ = writeln!(
                            out,
                            "        SPASS_TASK_REGISTRY.lock().unwrap().insert({:?}.to_string(), __sp_boxed);",
                            name
                        );
                        let _ = writeln!(out, "    }}");
                        let _ = writeln!(out, "    return;");
                    }
                    Stmt::Resume { name, .. } => {
                        // D5: look up the target task (any function
                        // that emitted a `@checkpoint <name>`), call
                        // `resume` on the boxed state to drive the
                        // target's state machine, then put the (now-
                        // updated) box back. The trait dispatch means
                        // the target can have a totally different
                        // state struct type from this function's.
                        //
                        // The lock is released before `resume` so a
                        // nested @resume that lands in this same
                        // function doesn't deadlock on the `Mutex`.
                        // forbids cycles, so the relaxed
                        // re-insert is safe: the box that comes back
                        // is the same one that went out.
                        let _ = writeln!(out, "    {{");
                        let _ = writeln!(
                            out,
                            "        let mut __sp_other = SPASS_TASK_REGISTRY.lock().unwrap().remove({:?});",
                            name
                        );
                        let _ = writeln!(out, "        if let Some(ref mut __sp_box) = __sp_other {{");
                        let _ = writeln!(out, "            __sp_box.resume();");
                        let _ = writeln!(out, "        }}");
                        let _ = writeln!(out, "        if let Some(__sp_box) = __sp_other {{");
                        let _ = writeln!(out, "            SPASS_TASK_REGISTRY.lock().unwrap().insert({:?}.to_string(), __sp_box);", name);
                        let _ = writeln!(out, "        }}");
                        let _ = writeln!(out, "    }}");
                    }
                    _ => unreachable!(),
                }
            } else {
                // @resume can be emitted OUTSIDE a runner - a non-
                // state-machine function can still @resume a
                // checkpointed function from another site. Emit the
                // resume call here too; a stray @checkpoint in a
                // non-state-machine function is a codegen bug, so
                // the defensive comment is enough.
                if let Stmt::Resume { name, .. } = stmt {
                    let _ = writeln!(out, "    {{");
                    let _ = writeln!(
                        out,
                        "        let mut __sp_other = SPASS_TASK_REGISTRY.lock().unwrap().remove({:?});",
                        name
                    );
                    let _ = writeln!(out, "        if let Some(ref mut __sp_box) = __sp_other {{");
                    let _ = writeln!(out, "            __sp_box.resume();");
                    let _ = writeln!(out, "        }}");
                    let _ = writeln!(out, "        if let Some(__sp_box) = __sp_other {{");
                    let _ = writeln!(
                        out,
                        "            SPASS_TASK_REGISTRY.lock().unwrap().insert({:?}.to_string(), __sp_box);",
                        name
                    );
                    let _ = writeln!(out, "        }}");
                    let _ = writeln!(out, "    }}");
                } else {
                    out.push_str("    /* @checkpoint outside state machine: ignored */\n");
                }
            }
        }
        Stmt::OrderDecl { .. } => {}
        Stmt::Assert { .. } => {
            // `assert(...)` lives in test bodies. The
            // Rust emitter, like the C emitter, does not compile test
            // bodies - `spass test` re-parses the test files and runs
            // them through the interpreter path. The arm is here for
            // exhaustiveness; we never reach it via `typed.functions`.
            let _ = out;
        }
        Stmt::Dispatch { decl, apply, .. } => {
            // mirror the C emitter's left-fold expansion.
            // Each `target = fn(args...)` is a regular Rust assignment
            // statement; the runtime types / multi-return structs are
            // already generated by `generate_rust` for the matched
            // functions.
            let modref = cx
                .module
                .as_ref()
                .ok_or_else(|| CodegenError::Unsupported {
                    message: "@dispatch needs a module context".into(),
                    span: decl.span.clone(),
                })?;
            let expansions = dispatch_codegen::expand(
                modref,
                &decl.tags,
                &decl.bind,
                &apply.call,
                apply.target.as_deref(),
            )
            .map_err(|e| CodegenError::Unsupported {
                message: format!("@dispatch expansion failed: {}", e),
                span: decl.span.clone(),
            })?;
            for (target, call, span) in expansions {
                let _ = write!(out, "    {} = ", target);
                emit_rust_expr(out, &call, cx)?;
                out.push_str(";\n");
                let _ = span;
            }
        }
        Stmt::IfPresent { .. } => {
            // The Rust emitter, like the C emitter, only sees the
            // post-transform body (the `if_present` was replaced by
            // its present_branch or absent_branch when codegen
            // produced the per-variant AST). Surface as a codegen
            // bug if the transform was skipped.
            return Err(CodegenError::Unsupported {
                message: "if_present was not transformed before Rust emission; this is a codegen bug".into(),
                span: stmt.span(),
            });
        }
        Stmt::Await { .. } => {
            // same semantics as the C emitter - the
            // `@await` marker is a no-op in the MVP's runner; the
            // I/O happens at the next `let v =
            // spasio:input[mode]("channel")` statement.
            out.push_str("    // @await: see next let for spasio:input\n");
        }
        Stmt::Ownclude(_) => {
        // `ownclude` is hoisted to a static
        // helper at module-emit time, not here. This arm
        // is here purely for exhaustiveness.
        }
    }
    Ok(())
}

fn emit_rust_block(out: &mut String, block: &Block, cx: &mut Ctx<'_>) -> CodegenResult<()> {
    out.push_str("{\n");
    for s in &block.stmts {
        emit_rust_stmt(out, s, cx)?;
    }
    out.push_str("    }");
    Ok(())
}

fn emit_rust_range(
    out: &mut String,
    start: &Expr,
    end: &Expr,
    step: Option<&Expr>,
    cx: &mut Ctx<'_>,
) -> CodegenResult<()> {
    out.push('(');
    emit_rust_expr(out, start, cx)?;
    out.push_str("..");
    emit_rust_expr(out, end, cx)?;
    out.push(')');
    if let Some(s) = step {
        out.push_str(".step_by((");
        emit_rust_expr(out, s, cx)?;
        out.push_str(") as usize)");
    }
    let _ = (start, end);
    Ok(())
}

/// Emit a Rust list literal with a known element type.
///
/// The element type decides the coercions: `list<float> = [1, 2]`
/// stores `f64` values even though both elements are integer
/// literals, and Rust does not coerce those implicitly.
fn emit_rust_list_lit(
    out: &mut String,
    elements: &[Expr],
    elem: &Type,
    cx: &mut Ctx<'_>,
) -> CodegenResult<()> {
    out.push_str("vec![");
    for (i, e) in elements.iter().enumerate() {
        if i > 0 {
            out.push_str(", ");
        }
        if let (Type::List(inner), Expr::ListLit { elements: inner_elements, .. }) = (elem, e) {
            emit_rust_list_lit(out, inner_elements, inner, cx)?;
            continue;
        }
        match elem {
            Type::Float(_) | Type::Int(_) | Type::Uint(_) | Type::Bool => {
                out.push_str("((");
                emit_rust_expr(out, e, cx)?;
                out.push_str(") as ");
                out.push_str(&rust_scalar_type(elem));
                out.push(')');
            }
            _ => emit_rust_expr(out, e, cx)?,
        }
    }
    out.push(']');
    Ok(())
}

fn emit_rust_expr(out: &mut String, expr: &Expr, cx: &mut Ctx<'_>) -> CodegenResult<()> {
    match expr {
        Expr::IntLit { value, .. } => {
            let _ = write!(out, "({}i32)", value);
        }
        Expr::FloatLit { value, .. } => {
            let f = rational_to_f64(value);
            let _ = write!(out, "({}f64)", f);
        }
        Expr::BoolLit { value, .. } => {
            let _ = write!(out, "{}", value);
        }
        Expr::StringLit { value, .. } => {
            let _ = write!(out, "{:?}", value);
        }
        Expr::Ident { name, .. } => {
            if cx.runner_state.is_some() {
                // Runner context: every local lives in the state
                // struct, accessed as `state.<name>`.
                let _ = write!(out, "state.{}", name);
            } else {
                let _ = write!(out, "{}", name);
            }
        }
        Expr::Binary { op, lhs, rhs, .. } => emit_rust_binop(out, op, lhs, rhs, cx)?,
        Expr::Unary { op, expr: inner, .. } => match op {
            UnaryOp::Neg => {
                out.push_str("-(");
                emit_rust_expr(out, inner, cx)?;
                out.push(')');
            }
            UnaryOp::Not => {
                out.push_str("!(");
                emit_rust_expr(out, inner, cx)?;
                out.push(')');
            }
        },
        // `s2d:window(...)`, `s3d:box(...)`, `spio:read_text(...)` -
        // playground native calls. Emit the runtime symbol directly:
        // `spass_s2d_window(...)`, `spass_spio_read_text(...)`.
        Expr::NativeCall { namespace, func, args, .. } => {
            let _ = write!(out, "spass_{}_{}(", namespace, func);
            for (i, arg) in args.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                emit_rust_expr(out, &arg.value, cx)?;
            }
            out.push(')');
        }
        Expr::Call { callee, args, span } => {
            let name = match callee.as_ref() {
                Expr::Ident { name, .. } => name.as_str(),
                _ => {
                    return Err(CodegenError::Unsupported {
                        message: "only direct function calls are supported".into(),
                        span: span.clone(),
                    })
                }
            };
            // Conversions: inline casts, not a real function call.
            if name == "to_int" {
                if args.len() != 1 {
                    return Err(CodegenError::Unsupported {
                        message: "to_int expects exactly 1 argument".into(),
                        span: span.clone(),
                    });
                }
                out.push_str("((");
                emit_rust_expr(out, &args[0].value, cx)?;
                out.push_str(") as i32)");
                return Ok(());
            }
            if name == "to_float" {
                if args.len() != 1 {
                    return Err(CodegenError::Unsupported {
                        message: "to_float expects exactly 1 argument".into(),
                        span: span.clone(),
                    });
                }
                out.push_str("((");
                emit_rust_expr(out, &args[0].value, cx)?;
                out.push_str(") as f64)");
                return Ok(());
            }
            // (`ownclude`): forward the enclosing
            // function's captured values as extra leading
            // arguments. See the C-side `emit_expr` for the
            // matching block - the two emitters share the
            // capture list so a call looks identical from both
            // backends.
            let ownclude_captures: Option<Vec<String>> = cx
                .module
                .as_ref()
                .and_then(|m| m.func(&name))
                .filter(|f| {
                    f.original.visibility == spass_parser::ast::Visibility::OwnPrivate
                })
                .map(|f| f.captures.iter().map(|(n, _)| n.clone()).collect());
            // The callee's value-domain parameters, in declaration order,
            // and the value domain of its return. Filled in only when the
            // call actually resolves to a module function: built-ins and
            // native calls have no value-domain parameter ABI. `out`
            // parameters are passed by pointer and carry the encoded
            // slot, so they are not quantised here.
            //
            // Both come from the module's call-site index, so a call
            // site does not rebuild the callee's symbol and domains.
            let index = cx.index;
            let mut callee_domains: Option<&[Option<ValueDomain>]> = None;
            let mut callee_return: Option<&ValueDomain> = None;
            let mapped: &str = if let Some(builtin) = builtin_mapping(&name) {
                builtin
            } else if let Some(dim_builtin) = vec_mat_builtin(&name, args, cx) {
                // same dispatch as the C side. See the
                // comment at the C `vec_mat_builtin` site for the
                // dimension-resolution rules.
                dim_builtin
            } else if let Some(site) = index.and_then(|ix| ix.get(&name)) {
                // See the C-side comment at the matching `mangle_for_call`
                // call: an `if_present` function is always invoked under
                // its present-variant symbol from Spass source.
                callee_domains = Some(site.param_domains.as_slice());
                callee_return = site.return_domain.as_ref();
                site.symbol.as_str()
            } else if cx.module.is_some() {
                return Err(CodegenError::Unsupported {
                    message: format!("call to unknown function `{}`", name),
                    span: span.clone(),
                });
            } else {
                return Err(CodegenError::Unsupported {
                    message: format!("call to unknown function `{}` (no module context)", name),
                    span: span.clone(),
                });
            };
            // The call is built into its own buffer so that a
            // value-domain return can be decoded around it.
            let mut call = String::new();
            call.push_str(&mapped);
            call.push('(');
            let mut arg_idx = 0;
            if let Some(caps) = &ownclude_captures {
                for cap in caps {
                    if arg_idx > 0 {
                        call.push_str(", ");
                    }
                    let _ = write!(call, "{}", cap);
                    arg_idx += 1;
                }
            }
            for (i, a) in args.iter().enumerate() {
                if arg_idx > 0 {
                    call.push_str(", ");
                }
                let dom = callee_domains
                    .as_ref()
                    .and_then(|doms| doms.get(i))
                    .and_then(|d| d.as_ref());
                match dom {
                    Some(vd) => {
                        // The callee expects the encoded state index, so
                        // the argument has to be quantised. When the
                        // argument's range is provably inside the
                        // domain the clamp is dead code and is dropped.
                        let enc = classify_arg(&a.value, vd, cx);
                        if let ArgEncoding::Disjoint = enc {
                            return Err(CodegenError::TypeError {
                                message: format!(
                                    "argument {} of `{}` is outside the value domain [{}, {}]",
                                    i + 1,
                                    name,
                                    vd.min,
                                    vd.max
                                ),
                                span: a.span.clone(),
                            });
                        }
                        let clamp = !matches!(enc, ArgEncoding::InDomain);
                        emit_rust_encode(&mut call, vd, clamp, |o| {
                            emit_rust_expr(o, &a.value, cx)
                        })?;
                    }
                    None => {
                        emit_rust_expr(&mut call, &a.value, cx)?;
                    }
                }
                arg_idx += 1;
            }
            call.push(')');
            match &callee_return {
                // The callee returns the encoded state index; the Spass
                // level sees the decoded value, so decode it here.
                Some(vd) => {
                    let _ = write!(
                        out,
                        "{} + {} * ({} as f64)",
                        vd.min_rs(),
                        vd.step_rs(),
                        call
                    );
                }
                None => out.push_str(&call),
            }
        }
        Expr::FieldAccess { target, field, .. } => {
            if field == "length" && matches!(expr_type(target, cx), Some(Type::List(_))) {
                // `list.length` is an `int`.
                out.push('(');
                emit_rust_expr(out, target, cx)?;
                out.push_str(").len() as i32");
            } else {
                emit_rust_expr(out, target, cx)?;
                let _ = write!(out, ".{}", field);
            }
        }
        Expr::Index { target, index, .. } => {
            // `Vec` indexing panics out of range, which is
            // the runtime-termination behaviour the language asks for.
            out.push('(');
            emit_rust_expr(out, target, cx)?;
            out.push_str(")[(");
            emit_rust_expr(out, index, cx)?;
            out.push_str(") as usize]");
        }
        Expr::ListLit { elements, .. } => {
            let elem = elements
                .first()
                .and_then(|e| expr_type(e, cx))
                .unwrap_or(Type::Float(None));
            emit_rust_list_lit(out, elements, &elem, cx)?;
        }
        Expr::Tuple { elements, .. } => {
            // `(a, b, c)` tuple literal. Used as the return value of a
            // multi-return function. The Rust emitter
            // produces a `SpassRet<N { _f0: a, _f1: b }` struct literal
            // so the FFI-safe return type matches the destructuring
            // site. The element count must equal the enclosing
            // function's `multi_returns` arity; the semantic pass
            // catches mismatches.
            out.push_str("SpassRet");
            // Recover the arity from `cx.ret_multi_returns` so the
            // struct type's name lines up.
            if let Some(mr) = &cx.ret_multi_returns {
                let _ = write!(out, "{} ", mr.len());
            } else {
                out.push_str("0 /* no enclosing multi-return */ ");
            }
            out.push_str("{ ");
            for (i, e) in elements.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                let _ = write!(out, "_f{}: ", i);
                emit_rust_expr(out, e, cx)?;
            }
            out.push_str(" }");
        }
        Expr::StructLit { name, fields, .. } => {
            let _ = write!(out, "{} {{ ", name);
            for (i, (fname, val)) in fields.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                let _ = write!(out, "{}: ", fname);
                emit_rust_expr(out, val, cx)?;
            }
            out.push_str(" }");
        }
        Expr::IfExpr { cond, then_branch, else_branch, .. } => {
            out.push_str("(if ");
            emit_rust_expr(out, cond, cx)?;
            out.push_str(" { ");
            emit_rust_expr(out, then_branch, cx)?;
            out.push_str(" } else { ");
            emit_rust_expr(out, else_branch, cx)?;
            out.push_str(" })");
        }
        Expr::AsType { value, .. } | Expr::NarrowCast { value, .. } => {
            emit_rust_expr(out, value, cx)?;
        }
        Expr::Conv { kind, value, .. } => match kind {
            ConvKind::ToFloat => {
                out.push_str("((");
                emit_rust_expr(out, value, cx)?;
                out.push_str(") as f64)");
            }
            ConvKind::ToInt => {
                out.push_str("((");
                emit_rust_expr(out, value, cx)?;
                out.push_str(") as i32)");
            }
        },
        Expr::Spawn { func, args, .. } => {
            // mirror of the C path - thunk + runtime spawn.
            let callee = match func.as_ref() {
                Expr::Ident { name, .. } => name.clone(),
                _ => {
                    return Err(CodegenError::Unsupported {
                        message: "spawn callee must be a named function".into(),
                        span: expr.span(),
                    })
                }
            };
            let tf = cx
                .module
                .as_ref()
                .and_then(|m| m.functions.iter().find(|f| f.name == callee));
            let tf = match tf {
                Some(f) if spawn_thunk_compatible(f) => f,
                Some(_) => {
                    return Err(CodegenError::Unsupported {
                        message: format!(
                            "`spawn` target `{}` must be a plain function: float/int params, float/int return, no captured variables",
                            callee
                        ),
                        span: expr.span(),
                    })
                }
                None => {
                    return Err(CodegenError::Unsupported {
                        message: format!("`spawn` target `{}` not found", callee),
                        span: expr.span(),
                    })
                }
            };
            let thunk = spawn_thunk_name(tf);
            let _ = write!(out, "spass_spawn({}, vec![", thunk);
            for (i, a) in args.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                out.push_str("(");
                emit_rust_expr(out, &a.value, cx)?;
                out.push_str(") as f64");
            }
            out.push_str("])");
        }
        Expr::Parallel { func, args, span, .. } => {
            // one call per list index. The arguments are
            // bound once, then the loop builds the row-major argument
            // vector the batch runtime expects.
            let module = cx.module.as_ref().ok_or_else(|| CodegenError::Unsupported {
                message: "no module context".into(),
                span: span.clone(),
            })?;
            let Expr::Ident { name, .. } = func.as_ref() else {
                return Err(CodegenError::Unsupported {
                    message: "`parallel` needs a function name".into(),
                    span: span.clone(),
                });
            };
            let f = module
                .functions
                .iter()
                .filter(|f| &f.name == name)
                .last()
                .ok_or_else(|| CodegenError::Unsupported {
                    message: format!("call to unknown function `{}`", name),
                    span: span.clone(),
                })?;
            if !spawn_thunk_compatible(f) {
                return Err(CodegenError::Unsupported {
                    message: format!(
                        "`{}` cannot run under `parallel`: only plain float/int parameters and returns are supported",
                        name
                    ),
                    span: span.clone(),
                });
            }
            let mut list_indices = Vec::new();
            out.push_str("{ ");
            for (i, a) in args.iter().enumerate() {
                let _ = write!(out, "let __sp_a{} = ", i);
                emit_rust_expr(out, &a.value, cx)?;
                out.push_str("; ");
                if matches!(expr_type(&a.value, cx), Some(Type::List(_))) {
                    if let Some(Type::List(inner)) = expr_type(&a.value, cx) {
                        if !matches!(*inner, Type::Float(_) | Type::Int(_)) {
                            return Err(CodegenError::Unsupported {
                                message:
                                    "`parallel` list arguments must hold float or int values"
                                        .into(),
                                span: a.span.clone(),
                            });
                        }
                    }
                    list_indices.push(i);
                }
            }
            match list_indices.first() {
                Some(first) => {
                    let _ = write!(out, "let __sp_n = __sp_a{}.len(); ", first);
                }
                None => out.push_str("let __sp_n: usize = 1; "),
            }
            for i in &list_indices {
                let _ = write!(
                    out,
                    "assert_eq!(__sp_a{}.len(), __sp_n, \"parallel list lengths differ\"); ",
                    i
                );
            }
            let _ = write!(
                out,
                "let mut __sp_args: Vec<f64> = Vec::with_capacity(__sp_n * {}); ",
                args.len()
            );
            out.push_str("for __sp_i in 0..__sp_n { ");
            for (i, _) in args.iter().enumerate() {
                if list_indices.contains(&i) {
                    let _ = write!(out, "__sp_args.push(__sp_a{}[__sp_i] as f64); ", i);
                } else {
                    let _ = write!(out, "__sp_args.push(__sp_a{} as f64); ", i);
                }
            }
            out.push_str("} ");
            let _ = write!(
                out,
                "spass_parallel_spawn({}, __sp_args, __sp_n, {}) }}",
                spawn_thunk_name(f),
                args.len()
            );
        }
        Expr::Send { target, message, span } => {
            // pack + push onto the target queue.
            let mty = seq_message_struct(message, cx, span.clone())?;
            let pack = pack_call_rust(&mty, message, cx)?;
            let _ = write!(
                out,
                "spass_seq_send({}, {})",
                seq_id_const(target),
                pack
            );
        }
        Expr::Broadcast { message, span } => {
            let mty = seq_message_struct(message, cx, span.clone())?;
            let pack = pack_call_rust(&mty, message, cx)?;
            let _ = write!(out, "spass_seq_broadcast({})", pack);
        }
        Expr::Receive { pattern, span } => {
            // block on the own queue, discarding messages
            // that don't satisfy the pattern. A block expression keeps
            // `let msg = receive...` a plain binding.
            let pattern = pattern.as_ref().ok_or_else(|| CodegenError::Unsupported {
                message: "`receive` needs a `Pattern{...}` filter".into(),
                span: span.clone(),
            })?;
            let self_id = seq_self_id(cx, span.clone())?;
            let s = cx
                .module
                .as_ref()
                .and_then(|m| m.structs.iter().find(|s| s.name == pattern.type_name))
                .cloned()
                .ok_or_else(|| CodegenError::Unsupported {
                    message: format!("unknown struct `{}`", pattern.type_name),
                    span: span.clone(),
                })?;
            let mut conds = String::new();
            for (i, (field, op, value)) in pattern.conditions.iter().enumerate() {
                if i > 0 {
                    conds.push_str(" && ");
                }
                let idx = s
                    .fields
                    .iter()
                    .position(|(n, _)| n == field)
                    .ok_or_else(|| CodegenError::Unsupported {
                        message: format!("`{}` has no field `{}`", s.name, field),
                        span: span.clone(),
                    })?;
                let fty = s.fields[idx].1.clone();
                let lhs = match fty {
                    Type::Int(_) => format!("(__sp_msg.f[{}] as i32)", idx),
                    _ => format!("__sp_msg.f[{}]", idx),
                };
                let rhs = {
                    let mut tmp = String::new();
                    emit_rust_expr(&mut tmp, value, cx)?;
                    format!("({})", tmp)
                };
                let op_str = match op {
                    BinOp::Gt => ">",
                    BinOp::Lt => "<",
                    BinOp::Ge => ">=",
                    BinOp::Le => "<=",
                    BinOp::Eq => "==",
                    BinOp::Ne => "!=",
                    _ => return Err(CodegenError::Unsupported {
                        message: "receive pattern conditions need a comparison operator".into(),
                        span: span.clone(),
                    }),
                };
                conds.push_str(&format!("{} {} {}", lhs, op_str, rhs));
            }
            let _ = write!(
                out,
                "{{ loop {{ let __sp_msg = spass_seq_recv({}); if {} {{ break __sp_unpack_{}(__sp_msg); }} }} }}",
                self_id,
                conds,
                s.name
            );
        }
        Expr::Await { task, .. } => match expr_type(expr, cx) {
            Some(Type::List(_)) => {
                out.push_str("spass_parallel_await(");
                emit_rust_expr(out, task, cx)?;
                out.push_str(" as u64)");
            }
            Some(Type::Int(_)) => {
                out.push_str("(spass_task_await(");
                emit_rust_expr(out, task, cx)?;
                out.push_str(" as u64) as i32)");
            }
            Some(Type::Uint(_)) => {
                out.push_str("(spass_task_await(");
                emit_rust_expr(out, task, cx)?;
                out.push_str(" as u64) as u32)");
            }
            Some(Type::Bool) => {
                out.push_str("(spass_task_await(");
                emit_rust_expr(out, task, cx)?;
                out.push_str(" as u64) != 0.0)");
            }
            _ => {
                out.push_str("spass_task_await(");
                emit_rust_expr(out, task, cx)?;
                out.push_str(" as u64)");
            }
        },
        Expr::Random { candidates, args, span } => match args {
            None => {
                let cast = match expr_type(expr, cx) {
                    Some(Type::Int(_)) => Some("i32"),
                    Some(Type::Uint(_)) => Some("u32"),
                    _ => None,
                };
                out.push_str("spass_random_pick(&[");
                for (i, c) in candidates.iter().enumerate() {
                    if i > 0 {
                        out.push_str(", ");
                    }
                    if matches!(expr_type(c, cx), Some(Type::Task(_))) {
                        out.push_str("spass_task_await(");
                        emit_rust_expr(out, c, cx)?;
                        out.push_str(" as u64)");
                    } else {
                        out.push('(');
                        emit_rust_expr(out, c, cx)?;
                        out.push_str(") as f64");
                    }
                }
                out.push(']');
                out.push(')');
                if let Some(ty) = cast {
                    let _ = write!(out, " as {}", ty);
                }
            }
            Some(args) => {
                out.push_str("{ let __sp_r = spass_random_index(");
                let _ = write!(out, "{}", candidates.len());
                out.push_str("); ");
                for (i, c) in candidates.iter().enumerate() {
                    let call = Expr::Call {
                        callee: Box::new(c.clone()),
                        args: args.clone(),
                        span: span.clone(),
                    };
                    if i + 1 < candidates.len() {
                        let _ = write!(out, "if __sp_r == {} {{ ", i);
                        emit_rust_expr(out, &call, cx)?;
                        out.push_str(" } else ");
                    } else {
                        // Rust requires the final `else` branch to be a
                        // block as well; a bare expression is a syntax
                        // error.
                        out.push_str("{ ");
                        emit_rust_expr(out, &call, cx)?;
                        out.push_str(" }");
                    }
                }
                out.push_str(" }");
            }
        },
        Expr::IfPresent { .. } => {
            return Err(CodegenError::Unsupported {
                message: "`if_present` is a statement, not an expression".into(),
                span: expr.span(),
            })
        }
        Expr::SpasioInput { mode, channel, .. } => {
            // / 9: `spasio:input[mode]("channel")` is a
            // blocking I/O call. The Rust runtime helper
            // `spass_spasio_input` reads from the channel and
            // returns an f64. The mode is rendered as a
            // `SpasioMode` enum tag that the helper matches on.
            let mode_rust = match mode {
                spass_parser::ast::SpasioMode::File => "SpasioMode::File",
                spass_parser::ast::SpasioMode::Socket => "SpasioMode::Socket",
                spass_parser::ast::SpasioMode::Memory => "SpasioMode::Memory",
            };
            let _ = write!(
                out,
                "spass_spasio_input({}, {:?})",
                mode_rust, channel
            );
        }
        Expr::SpasioOutput { mode, value, channel, .. } => {
            // `spasio:output[mode](value, "channel")`
            // writes the value to the channel. The MVP's runtime
            // helper returns the value (so the call site can stay
            // expression-shaped); it does not block.
            let mode_rust = match mode {
                spass_parser::ast::SpasioMode::File => "SpasioMode::File",
                spass_parser::ast::SpasioMode::Socket => "SpasioMode::Socket",
                spass_parser::ast::SpasioMode::Memory => "SpasioMode::Memory",
            };
            let _ = write!(out, "spass_spasio_output({}, ", mode_rust);
            emit_rust_expr(out, value, cx)?;
            let _ = write!(out, ", {:?})", channel);
        }
    }
    Ok(())
}

fn emit_rust_binop(
    out: &mut String,
    op: &BinOp,
    lhs: &Expr,
    rhs: &Expr,
    cx: &mut Ctx<'_>,
) -> CodegenResult<()> {
    let op_str = match op {
        BinOp::Add => "+",
        BinOp::Sub => "-",
        BinOp::Mul => "*",
        BinOp::Div => "/",
        BinOp::Pow => return emit_rust_pow(out, lhs, rhs, cx),
        BinOp::Eq => "==",
        BinOp::Ne => "!=",
        BinOp::Lt => "<",
        BinOp::Le => "<=",
        BinOp::Gt => ">",
        BinOp::Ge => ">=",
        BinOp::And => "&&",
        BinOp::Or => "||",
    };
    out.push('(');
    emit_rust_expr(out, lhs, cx)?;
    out.push(' ');
    out.push_str(op_str);
    out.push(' ');
    emit_rust_expr(out, rhs, cx)?;
    out.push(')');
    Ok(())
}

fn emit_rust_pow(
    out: &mut String,
    lhs: &Expr,
    rhs: &Expr,
    cx: &mut Ctx<'_>,
) -> CodegenResult<()> {
    out.push_str("spass_pow((");
    emit_rust_expr(out, lhs, cx)?;
    out.push_str(") as f64, (");
    emit_rust_expr(out, rhs, cx)?;
    out.push_str(") as f64)");
    Ok(())
}

/// The vector / matrix runtime. Emitted only when the
/// program uses a vec or mat type or calls a vec/mat built-in.
fn emit_rust_runtime_vec_mat(out: &mut String) {
    out.push_str(
        r#"
// vector / matrix types. Field layout matches the C
// side so FFI passes through cleanly. `Debug` is derived so the
// dispatcher's `{:?}` print path works the same way it does for
// user-defined structs.
#[derive(Clone, Copy, Debug)]
pub struct SpassVec2 { pub x: f64, pub y: f64 }
#[derive(Clone, Copy, Debug)]
pub struct SpassVec3 { pub x: f64, pub y: f64, pub z: f64 }
#[derive(Clone, Copy, Debug)]
pub struct SpassVec4 { pub x: f64, pub y: f64, pub z: f64, pub w: f64 }
#[derive(Clone, Copy, Debug)]
pub struct SpassMat3 { pub m: [f64; 9] }
#[derive(Clone, Copy, Debug)]
pub struct SpassMat4 { pub m: [f64; 16] }

// vec/vec and vec/scalar arithmetic. The codegen
// layer emits the same `+`/`-`/`*`/`/` syntax the C backend uses
// so the two backends stay symmetric. The scalar-op impls are
// commutative (both `v + s` and `s + v` are valid).
impl core::ops::Add<SpassVec2> for SpassVec2 { type Output = SpassVec2; fn add(self, r: SpassVec2) -> SpassVec2 { SpassVec2 { x: self.x + r.x, y: self.y + r.y } } }
impl core::ops::Sub<SpassVec2> for SpassVec2 { type Output = SpassVec2; fn sub(self, r: SpassVec2) -> SpassVec2 { SpassVec2 { x: self.x - r.x, y: self.y - r.y } } }
impl core::ops::Mul<SpassVec2> for SpassVec2 { type Output = SpassVec2; fn mul(self, r: SpassVec2) -> SpassVec2 { SpassVec2 { x: self.x * r.x, y: self.y * r.y } } }
impl core::ops::Div<SpassVec2> for SpassVec2 { type Output = SpassVec2; fn div(self, r: SpassVec2) -> SpassVec2 { SpassVec2 { x: self.x / r.x, y: self.y / r.y } } }
impl core::ops::Mul<f64> for SpassVec2 { type Output = SpassVec2; fn mul(self, r: f64) -> SpassVec2 { SpassVec2 { x: self.x * r, y: self.y * r } } }
impl core::ops::Mul<SpassVec2> for f64 { type Output = SpassVec2; fn mul(self, r: SpassVec2) -> SpassVec2 { SpassVec2 { x: self * r.x, y: self * r.y } } }
impl core::ops::Add<f64> for SpassVec2 { type Output = SpassVec2; fn add(self, r: f64) -> SpassVec2 { SpassVec2 { x: self.x + r, y: self.y + r } } }
impl core::ops::Add<SpassVec2> for f64 { type Output = SpassVec2; fn add(self, r: SpassVec2) -> SpassVec2 { SpassVec2 { x: self + r.x, y: self + r.y } } }
impl core::ops::Sub<f64> for SpassVec2 { type Output = SpassVec2; fn sub(self, r: f64) -> SpassVec2 { SpassVec2 { x: self.x - r, y: self.y - r } } }
impl core::ops::Sub<SpassVec2> for f64 { type Output = SpassVec2; fn sub(self, r: SpassVec2) -> SpassVec2 { SpassVec2 { x: self - r.x, y: self - r.y } } }
impl core::ops::Div<f64> for SpassVec2 { type Output = SpassVec2; fn div(self, r: f64) -> SpassVec2 { SpassVec2 { x: self.x / r, y: self.y / r } } }

impl core::ops::Add<SpassVec3> for SpassVec3 { type Output = SpassVec3; fn add(self, r: SpassVec3) -> SpassVec3 { SpassVec3 { x: self.x + r.x, y: self.y + r.y, z: self.z + r.z } } }
impl core::ops::Sub<SpassVec3> for SpassVec3 { type Output = SpassVec3; fn sub(self, r: SpassVec3) -> SpassVec3 { SpassVec3 { x: self.x - r.x, y: self.y - r.y, z: self.z - r.z } } }
impl core::ops::Mul<SpassVec3> for SpassVec3 { type Output = SpassVec3; fn mul(self, r: SpassVec3) -> SpassVec3 { SpassVec3 { x: self.x * r.x, y: self.y * r.y, z: self.z * r.z } } }
impl core::ops::Div<SpassVec3> for SpassVec3 { type Output = SpassVec3; fn div(self, r: SpassVec3) -> SpassVec3 { SpassVec3 { x: self.x / r.x, y: self.y / r.y, z: self.z / r.z } } }
impl core::ops::Mul<f64> for SpassVec3 { type Output = SpassVec3; fn mul(self, r: f64) -> SpassVec3 { SpassVec3 { x: self.x * r, y: self.y * r, z: self.z * r } } }
impl core::ops::Mul<SpassVec3> for f64 { type Output = SpassVec3; fn mul(self, r: SpassVec3) -> SpassVec3 { SpassVec3 { x: self * r.x, y: self * r.y, z: self * r.z } } }
impl core::ops::Add<f64> for SpassVec3 { type Output = SpassVec3; fn add(self, r: f64) -> SpassVec3 { SpassVec3 { x: self.x + r, y: self.y + r, z: self.z + r } } }
impl core::ops::Add<SpassVec3> for f64 { type Output = SpassVec3; fn add(self, r: SpassVec3) -> SpassVec3 { SpassVec3 { x: self + r.x, y: self + r.y, z: self + r.z } } }
impl core::ops::Sub<f64> for SpassVec3 { type Output = SpassVec3; fn sub(self, r: f64) -> SpassVec3 { SpassVec3 { x: self.x - r, y: self.y - r, z: self.z - r } } }
impl core::ops::Sub<SpassVec3> for f64 { type Output = SpassVec3; fn sub(self, r: SpassVec3) -> SpassVec3 { SpassVec3 { x: self - r.x, y: self - r.y, z: self - r.z } } }
impl core::ops::Div<f64> for SpassVec3 { type Output = SpassVec3; fn div(self, r: f64) -> SpassVec3 { SpassVec3 { x: self.x / r, y: self.y / r, z: self.z / r } } }

impl core::ops::Add<SpassVec4> for SpassVec4 { type Output = SpassVec4; fn add(self, r: SpassVec4) -> SpassVec4 { SpassVec4 { x: self.x + r.x, y: self.y + r.y, z: self.z + r.z, w: self.w + r.w } } }
impl core::ops::Sub<SpassVec4> for SpassVec4 { type Output = SpassVec4; fn sub(self, r: SpassVec4) -> SpassVec4 { SpassVec4 { x: self.x - r.x, y: self.y - r.y, z: self.z - r.z, w: self.w - r.w } } }
impl core::ops::Mul<SpassVec4> for SpassVec4 { type Output = SpassVec4; fn mul(self, r: SpassVec4) -> SpassVec4 { SpassVec4 { x: self.x * r.x, y: self.y * r.y, z: self.z * r.z, w: self.w * r.w } } }
impl core::ops::Div<SpassVec4> for SpassVec4 { type Output = SpassVec4; fn div(self, r: SpassVec4) -> SpassVec4 { SpassVec4 { x: self.x / r.x, y: self.y / r.y, z: self.z / r.z, w: self.w / r.w } } }
impl core::ops::Mul<f64> for SpassVec4 { type Output = SpassVec4; fn mul(self, r: f64) -> SpassVec4 { SpassVec4 { x: self.x * r, y: self.y * r, z: self.z * r, w: self.w * r } } }
impl core::ops::Mul<SpassVec4> for f64 { type Output = SpassVec4; fn mul(self, r: SpassVec4) -> SpassVec4 { SpassVec4 { x: self * r.x, y: self * r.y, z: self * r.z, w: self * r.w } } }
impl core::ops::Add<f64> for SpassVec4 { type Output = SpassVec4; fn add(self, r: f64) -> SpassVec4 { SpassVec4 { x: self.x + r, y: self.y + r, z: self.z + r, w: self.w + r } } }
impl core::ops::Add<SpassVec4> for f64 { type Output = SpassVec4; fn add(self, r: SpassVec4) -> SpassVec4 { SpassVec4 { x: self + r.x, y: self + r.y, z: self + r.z, w: self + r.w } } }
impl core::ops::Sub<f64> for SpassVec4 { type Output = SpassVec4; fn sub(self, r: f64) -> SpassVec4 { SpassVec4 { x: self.x - r, y: self.y - r, z: self.z - r, w: self.w - r } } }
impl core::ops::Sub<SpassVec4> for f64 { type Output = SpassVec4; fn sub(self, r: SpassVec4) -> SpassVec4 { SpassVec4 { x: self - r.x, y: self - r.y, z: self - r.z, w: self - r.w } } }
impl core::ops::Div<f64> for SpassVec4 { type Output = SpassVec4; fn div(self, r: f64) -> SpassVec4 { SpassVec4 { x: self.x / r, y: self.y / r, z: self.z / r, w: self.w / r } } }

// vec/mat built-ins. These mirror the C runtime's
// `spass_dot*` / `spass_length*` / etc. functions. The
// `#[inline]` hint lets LLVM fold them at the call site so the
// generated code is as efficient as hand-written arithmetic.
#[inline] pub fn spass_dot2(a: SpassVec2, b: SpassVec2) -> f64 { a.x*b.x + a.y*b.y }
#[inline] pub fn spass_dot3(a: SpassVec3, b: SpassVec3) -> f64 { a.x*b.x + a.y*b.y + a.z*b.z }
#[inline] pub fn spass_dot4(a: SpassVec4, b: SpassVec4) -> f64 { a.x*b.x + a.y*b.y + a.z*b.z + a.w*b.w }
#[inline] pub fn spass_cross(a: SpassVec3, b: SpassVec3) -> SpassVec3 {
    SpassVec3 { x: a.y*b.z - a.z*b.y, y: a.z*b.x - a.x*b.z, z: a.x*b.y - a.y*b.x }
}
#[inline] pub fn spass_length2(v: SpassVec2) -> f64 { spass_dot2(v, v).sqrt }
#[inline] pub fn spass_length3(v: SpassVec3) -> f64 { spass_dot3(v, v).sqrt }
#[inline] pub fn spass_length4(v: SpassVec4) -> f64 { spass_dot4(v, v).sqrt }
#[inline] pub fn spass_normalize2(v: SpassVec2) -> SpassVec2 {
    let l = spass_length2(v); SpassVec2 { x: v.x/l, y: v.y/l }
}
#[inline] pub fn spass_normalize3(v: SpassVec3) -> SpassVec3 {
    let l = spass_length3(v); SpassVec3 { x: v.x/l, y: v.y/l, z: v.z/l }
}
#[inline] pub fn spass_normalize4(v: SpassVec4) -> SpassVec4 {
    let l = spass_length4(v); SpassVec4 { x: v.x/l, y: v.y/l, z: v.z/l, w: v.w/l }
}
#[inline] pub fn spass_hadamard2(a: SpassVec2, b: SpassVec2) -> SpassVec2 {
    SpassVec2 { x: a.x*b.x, y: a.y*b.y }
}
#[inline] pub fn spass_hadamard3(a: SpassVec3, b: SpassVec3) -> SpassVec3 {
    SpassVec3 { x: a.x*b.x, y: a.y*b.y, z: a.z*b.z }
}
#[inline] pub fn spass_hadamard4(a: SpassVec4, b: SpassVec4) -> SpassVec4 {
    SpassVec4 { x: a.x*b.x, y: a.y*b.y, z: a.z*b.z, w: a.w*b.w }
}
// vec/mat constructors. The Spass source uses
// `mk_vec2(x, y)` / `mk_vec3(x, y, z)` / `mk_vec4(x, y, z, w)`
// to build a vec value from scalar args (the dispatcher only
// takes f64 args, so the user must construct the vec inside the
// function body). These mirror the C runtime's `spass_mk_vec*`.
#[inline] pub fn spass_mk_vec2(x: f64, y: f64) -> SpassVec2 {
    SpassVec2 { x, y }
}
#[inline] pub fn spass_mk_vec3(x: f64, y: f64, z: f64) -> SpassVec3 {
    SpassVec3 { x, y, z }
}
#[inline] pub fn spass_mk_vec4(x: f64, y: f64, z: f64, w: f64) -> SpassVec4 {
    SpassVec4 { x, y, z, w }
}
// `ponytail`: matmul/transpose are not part of the MVP's Rust
// emit path - the Rust backend exists only to run unit tests via
// `spass run`. A future revision that targets the Rust backend
// for production use will need these here; for now the C backend
// covers the production path.
"#,
    );
}

/// The scalar math runtime. Always present: it is small, and every
/// generated module can reach it.
fn emit_rust_runtime_core(out: &mut String) {
    out.push_str(
        r#"
pub fn spass_sin(x: f64) -> f64 { x.sin() }
pub fn spass_cos(x: f64) -> f64 { x.cos() }
pub fn spass_tan(x: f64) -> f64 { x.tan() }
pub fn spass_sqrt(x: f64) -> f64 { x.sqrt() }
pub fn spass_abs(x: f64) -> f64 { x.abs() }
pub fn spass_floor(x: f64) -> f64 { x.floor() }
pub fn spass_ceil(x: f64) -> f64 { x.ceil() }
// `round` with halfway cases away from zero -- the same result as
// `f64::round` and C's `round`. `f64::round` needs SSE4.1's
// `roundsd`, which the baseline x86-64 target does not enable, so the
// standard library lowers it to a libm call. The arithmetic below
// gives the same answer without the call.
#[inline]
pub fn spass_round(x: f64) -> f64 {
    // At or above 2^52 every f64 is already integral, and NaN and the
    // infinities are not values to round. All of them return `x`
    // unchanged -- which is also what `round` does.
    if !(x.abs() < 4503599627370496.0) {
        return x;
    }
    let t = x as i64; // truncates toward zero
    let frac = x - (t as f64);
    if frac >= 0.5 { t as f64 + 1.0 }
    else if frac <= -0.5 { t as f64 - 1.0 }
    else { t as f64 }
}
// Value-domain encode: turn a `double` into the domain's
// integer state index. The compiler knows the domain's exact
// reciprocal `k = 1/step` (E001 restricts the step to 1 or a negative
// power of 2 or 10), so the state is `round((v - min) * k)` -- a
// multiply instead of a division by a decimal step that binary
// floating point cannot represent.
//
// `nstates` is the domain's state count; the result is clamped into
// `[0, nstates - 1]`. The C backend mirrors this function exactly, so
// both backends agree bit for bit.
#[inline]
pub fn spass_enc_state(v: f64, min: f64, k: f64, nstates: f64) -> f64 {
    let r = spass_round((v - min) * k);
    // `!(r > 0.0)` holds for NaN, so a NaN input lands on state 0
    // instead of an undefined float-to-integer conversion.
    if !(r > 0.0) { 0.0 }
    else if r > nstates - 1.0 { nstates - 1.0 }
    else { r }
}
pub fn spass_exp(x: f64) -> f64 { x.exp() }
pub fn spass_log(x: f64) -> f64 { x.ln() }
pub fn spass_pow(b: f64, e: f64) -> f64 { b.powf(e) }
pub fn spass_max(a: f64, b: f64) -> f64 { a.max(b) }
pub fn spass_min(a: f64, b: f64) -> f64 { a.min(b) }
pub fn spass_lerp(a: f64, b: f64, t: f64) -> f64 { a + (b - a) * t }
pub fn spass_clamp(v: f64, lo: f64, hi: f64) -> f64 { v.max(lo).min(hi) }
pub fn spass_smoothstep(e0: f64, e1: f64, x: f64) -> f64 {
    let t = ((x - e0) / (e1 - e0)).max(0.0).min(1.0);
    t * t * (3.0 - 2.0 * t)
}

// random choice. The state is an xorshift64 seeded from
// the clock on first use; `n` is the number of candidates.
pub fn spass_random_index(n: usize) -> usize {
    use std::sync::atomic::{AtomicU64, Ordering};
    static STATE: AtomicU64 = AtomicU64::new(0);
    if n <= 1 {
        return 0;
    }
    let mut x = STATE.load(Ordering::Relaxed);
    if x == 0 {
        x = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x9e37_79b9_7f4a_7c15)
            ^ (&STATE as *const _ as u64);
        if x == 0 {
            x = 0x9e37_79b9_7f4a_7c15;
        }
    }
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    STATE.store(x, Ordering::Relaxed);
    (x % n as u64) as usize
}
pub fn spass_random_pick(values: &[f64]) -> f64 {
    if values.is_empty() {
        0.0
    } else {
        values[spass_random_index(values.len())]
    }
}

pub fn spass_noise_2d(x: f64, y: f64) -> f64 {
    let x0 = x.floor() as i64;
    let y0 = y.floor() as i64;
    let x1 = x0 + 1;
    let y1 = y0 + 1;
    let fx = x - x0 as f64;
    let fy = y - y0 as f64;
    let smooth = |t: f64| t * t * (3.0 - 2.0 * t);
    let u = smooth(fx);
    let v = smooth(fy);
    let h = |xi: i64, yi: i64| {
        let mut h = (xi.wrapping_mul(374761393) ^ yi.wrapping_mul(668265263)) as u64;
        h ^= h >> 13; h = h.wrapping_mul(1274126177);
        h ^= h >> 16;
        ((h & 0xFFFF) as f64 / 65535.0) * 2.0 - 1.0
    };
    let n00 = h(x0, y0);
    let n10 = h(x1, y0);
    let n01 = h(x0, y1);
    let n11 = h(x1, y1);
    let ix0 = n00 + u * (n10 - n00);
    let ix1 = n01 + u * (n11 - n01);
    ix0 + v * (ix1 - ix0)
}

pub fn spass_fbm(x: f64, y: f64, octaves: i32, gain: f64) -> f64 {
    let mut sum = 0.0;
    let mut amp = 1.0;
    let mut freq = 1.0;
    let mut norm = 0.0;
    for _ in 0..octaves {
        sum += amp * spass_noise_2d(x * freq, y * freq);
        norm += amp;
        amp *= gain;
        freq *= 2.0;
    }
    if norm == 0.0 { 0.0 } else { sum / norm }
}
"#,
    );
}

/// The spasio client. Emitted only when the program
/// touches a channel.
fn emit_rust_runtime_spasio(out: &mut String) {
    out.push_str(
        r#"
// spasio I/O. ALL spasio
// I/O is served by the saple runner: the program connects to the runner
// over TCP and exchanges data-plane frames. The program process never
// touches the file system or listens on a port - file channels are proxied
// to disk by the runner, socket channels live in the runner's memory
// slots. Frame:
// request: [4B BE body_len][u8 opcode][u8 mode][u32 BE proj_len][project]
// [u8 ch_len][channel][8B f64 LE value]
// response: [4B BE resp_len][u8 status][8B f64 LE value]
// opcode: 0 = GET (input), 1 = SET (output). mode: 0 = file, 1 = socket.
#[derive(Clone, Copy)]
pub enum SpasioMode { File, Socket, Memory }

// The runner address and the project path are process-level constants:
// they were re-read (two `getenv` calls and a `getcwd`) on every
// channel access. Resolving them once means that changing
// `SPASS_SOCKET_HOST` / `SPASS_SOCKET_PORT` after the first channel
// access no longer takes effect.
static SPASS_SPASIO_ADDR: std::sync::OnceLock<String> = std::sync::OnceLock::new();
static SPASS_SPASIO_PROJ: std::sync::OnceLock<Vec<u8>> = std::sync::OnceLock::new();

fn spass_spasio_socket_target() -> &'static str {
    SPASS_SPASIO_ADDR.get_or_init(|| {
        let host = std::env::var("SPASS_SOCKET_HOST").unwrap_or_else(|_| "127.0.0.1".to_string());
        let port = std::env::var("SPASS_SOCKET_PORT").ok()
            .and_then(|p| p.parse::<u16>().ok())
            .unwrap_or(9100);
        format!("{}:{}", host, port)
    })
}

fn spass_spasio_project() -> &'static [u8] {
    SPASS_SPASIO_PROJ.get_or_init(|| {
        std::env::current_dir().unwrap_or_default().to_string_lossy().as_bytes().to_vec()
    })
}

fn spass_spasio_mode_code(mode: SpasioMode) -> u8 {
    match mode {
        SpasioMode::File => 0,
        // `ponytail`: memory mode maps to the runner's in-memory slots
        // for now - a true shared-memory mapping is a future revision.
        SpasioMode::Socket | SpasioMode::Memory => 1,
    }
}

// Connection pool. The program used to open one TCP connection per
// channel access, so a single 8-byte transfer paid a full connect,
// handshake, teardown and accept cycle. The runner's protocol already
// supports reuse (it reads frames until EOF), so connections are kept
// open and handed out from a pool.
//
// The pool is process-global: sequences run on separate threads and
// share the runner's connection budget. A blocking GET holds its
// connection for the whole wait, so the bound must exceed the number
// of concurrently blocked GETs - a bound of one would deadlock a
// program that blocks on one channel while writing another.
const SPASS_SPASIO_MAX_CONNS: usize = 8;

struct SpasioPool {
    /// Connections ready for use.
    idle: Vec<std::net::TcpStream>,
    /// Connections handed out and not yet returned.
    live: usize,
}

fn spass_spasio_pool() -> &'static std::sync::Mutex<SpasioPool> {
    static POOL: std::sync::OnceLock<std::sync::Mutex<SpasioPool>> = std::sync::OnceLock::new();
    POOL.get_or_init(|| std::sync::Mutex::new(SpasioPool { idle: Vec::new(), live: 0 }))
}

fn spass_spasio_pool_cv() -> &'static std::sync::Condvar {
    static CV: std::sync::OnceLock<std::sync::Condvar> = std::sync::OnceLock::new();
    CV.get_or_init(std::sync::Condvar::new)
}

/// Open a runner connection with Nagle's algorithm disabled.
///
/// The frame protocol is a write-write-read: a length prefix, the
/// body, then the response. Nagle delays the second write until the
/// first is acknowledged, which stalls exactly this pattern.
fn spass_spasio_connect() -> Result<std::net::TcpStream, String> {
    let addr = spass_spasio_socket_target();
    let stream = std::net::TcpStream::connect(addr)
        .map_err(|e| format!("spass: cannot connect runner at {}: {} (is `spass daemon` running?)", addr, e))?;
    let _ = stream.set_nodelay(true);
    Ok(stream)
}

/// Take a connection from the pool, opening a new one while the pool
/// is below its bound and waiting for a return once it is not.
fn spass_spasio_checkout() -> Result<std::net::TcpStream, String> {
    let mut pool = spass_spasio_pool().lock().expect("spass: spasio pool poisoned");
    loop {
        if let Some(s) = pool.idle.pop() {
            pool.live += 1;
            return Ok(s);
        }
        if pool.live < SPASS_SPASIO_MAX_CONNS {
            pool.live += 1;
            drop(pool);
            return match spass_spasio_connect() {
                Ok(s) => Ok(s),
                Err(e) => {
                    let mut pool = spass_spasio_pool().lock().expect("spass: spasio pool poisoned");
                    pool.live -= 1;
                    drop(pool);
                    spass_spasio_pool_cv().notify_one();
                    Err(e)
                }
            };
        }
        pool = spass_spasio_pool_cv().wait(pool).expect("spass: spasio pool poisoned");
    }
}

/// Return a healthy connection to the pool.
fn spass_spasio_checkin(s: std::net::TcpStream) {
    {
        let mut pool = spass_spasio_pool().lock().expect("spass: spasio pool poisoned");
        pool.live -= 1;
        pool.idle.push(s);
    }
    spass_spasio_pool_cv().notify_one();
}

/// Drop a connection that failed. It must never be handed out again.
fn spass_spasio_discard() {
    {
        let mut pool = spass_spasio_pool().lock().expect("spass: spasio pool poisoned");
        pool.live -= 1;
    }
    spass_spasio_pool_cv().notify_one();
}

/// The runner's answer to one data-plane frame.
enum SpasioReply {
    /// The runner answered with a value.
    Value(f64),
    /// The runner answered "no value set" for the channel. This is a
    /// successful exchange, not a transport failure, so it must not
    /// trigger a reconnect.
    NoValue,
}

/// Send `body` on `stream` and read the response frame.
fn spass_spasio_exchange(
    stream: &mut std::net::TcpStream,
    body: &[u8],
) -> Result<SpasioReply, String> {
    use std::io::{Read, Write};
    stream.write_all(&(body.len() as u32).to_be_bytes())
        .map_err(|e| format!("spass: runner write failed: {}", e))?;
    stream.write_all(body)
        .map_err(|e| format!("spass: runner write failed: {}", e))?;
    let mut header = [0u8; 4];
    stream.read_exact(&mut header)
        .map_err(|e| format!("spass: runner read failed: {}", e))?;
    let rlen = u32::from_be_bytes(header) as usize;
    let mut resp = vec![0u8; rlen];
    stream.read_exact(&mut resp)
        .map_err(|e| format!("spass: runner read failed: {}", e))?;
    if resp.is_empty() {
        return Err("spass: runner short response".into());
    }
    if resp[0] != 0 {
        return Ok(SpasioReply::NoValue);
    }
    if resp.len() < 9 {
        return Ok(SpasioReply::Value(0.0));
    }
    let mut vb = [0u8; 8];
    vb.copy_from_slice(&resp[1..9]);
    Ok(SpasioReply::Value(f64::from_le_bytes(vb)))
}

/// One RPC to the runner. GET blocks inside the runner until the channel
/// has a value (socket) or errs when the disk slot is missing (file).
///
/// A pooled connection may point at a runner that has since been
/// restarted: the first exchange fails on the dead socket. The failed
/// connection is dropped and the exchange is retried once on a fresh
/// one, which is what makes a runner restart survivable.
fn spass_spasio_rpc(opcode: u8, mode: u8, channel: &str, value: f64) -> Result<f64, String> {
    let proj = spass_spasio_project();
    let name = channel.as_bytes();
    if name.len() > 255 {
        return Err("spass: spasio channel name too long (>255 bytes)".into());
    }
    let mut body = Vec::with_capacity(2 + 4 + proj.len() + 1 + name.len() + 8);
    body.push(opcode);
    body.push(mode);
    body.extend_from_slice(&(proj.len() as u32).to_be_bytes());
    body.extend_from_slice(proj);
    body.push(name.len() as u8);
    body.extend_from_slice(name);
    body.extend_from_slice(&value.to_le_bytes());
    let mut last_err = String::new();
    for attempt in 0..2 {
        let mut stream = spass_spasio_checkout()?;
        match spass_spasio_exchange(&mut stream, &body) {
            Ok(SpasioReply::Value(v)) => {
                spass_spasio_checkin(stream);
                return Ok(v);
            }
            Ok(SpasioReply::NoValue) => {
                spass_spasio_checkin(stream);
                return Err("spass: spasio channel unavailable (no value set)".into());
            }
            Err(e) => {
                // The connection failed: it must not go back into the pool.
                spass_spasio_discard();
                last_err = e;
                if attempt == 1 {
                    return Err(last_err);
                }
            }
        }
    }
    Err(last_err)
}

/// A channel access that failed is a program-level error, not a crash.
///
/// The message says what went wrong and the process leaves with a
/// failure code. A Rust panic would print a backtrace-shaped dump that
/// says nothing about the channel that was missing.
pub fn spass_spasio_fail(msg: String) -> ! {
    eprintln!("{}", msg);
    std::process::exit(1);
}

pub fn spass_spasio_input(mode: SpasioMode, channel: &str) -> f64 {
    spass_spasio_rpc(0, spass_spasio_mode_code(mode), channel, 0.0)
        .unwrap_or_else(|e| spass_spasio_fail(e))
}

pub fn spass_spasio_output(mode: SpasioMode, value: f64, channel: &str) -> f64 {
    spass_spasio_rpc(1, spass_spasio_mode_code(mode), channel, value)
        .unwrap_or_else(|e| spass_spasio_fail(e));
    value
}
"#,
    );
}

/// The async task registry. Emitted only when the
/// program spawns or awaits a task.
fn emit_rust_runtime_tasks(out: &mut String) {
    out.push_str(
        r#"
// Async task runtime. `spawn` runs a thunk on a worker
// thread and returns an opaque u64 handle; `await(handle)` joins and
// returns the result. Results flow through a per-task channel - no
// polling. `ponytail`: the registry holds the receiver keyed by id;
// a task that is never awaited leaks its Receiver until the process
// exits. Upgrade path: refcounted handles (the spass_task_t model).
static SPASS_TASK_NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);
static SPASS_TASKS: std::sync::Mutex<Option<std::collections::HashMap<u64, std::sync::mpsc::Receiver<f64>>>>
    = std::sync::Mutex::new(None);

pub fn spass_spawn(thunk: fn(&[f64], &mut f64), args: Vec<f64>) -> u64 {
    let id = SPASS_TASK_NEXT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::spawn(move || {
        let mut out = 0.0f64;
        thunk(&args, &mut out);
        let _ = tx.send(out);
    });
    SPASS_TASKS.lock().expect("spass: task registry poisoned").get_or_insert_with(Default::default).insert(id, rx);
    id
}

pub fn spass_task_await(id: u64) -> f64 {
    let rx = SPASS_TASKS
        .lock()
        .expect("spass: task registry poisoned")
        .get_or_insert_with(Default::default)
        .remove(&id)
        .unwrap_or_else(|| panic!("spass: await on unknown task {}", id));
    rx.recv().unwrap_or(0.0)
}

// `parallel` spawns one call per argument row and collects
// the results into a list. The handle owns the task ids; awaiting it
// joins every task and returns the values in call order.
struct SpassBatch {
    ids: Vec<u64>,
}
pub fn spass_parallel_spawn(
    thunk: fn(&[f64], &mut f64),
    args: Vec<f64>,
    ncalls: usize,
    nparams: usize,
) -> u64 {
    let mut ids = Vec::with_capacity(ncalls);
    for i in 0..ncalls {
        let start = i * nparams;
        let row = args[start..start + nparams].to_vec();
        ids.push(spass_spawn(thunk, row));
    }
    Box::into_raw(Box::new(SpassBatch { ids })) as u64
}
pub fn spass_parallel_await(handle: u64) -> Vec<f64> {
    if handle == 0 {
        return Vec::new();
    }
    let batch = unsafe { Box::from_raw(handle as *mut SpassBatch) };
    batch.ids.iter().map(|id| spass_task_await(*id)).collect()
}
"#,
    );
}

/// The sequence runtime. Emitted only when the program
/// declares sequences.
fn emit_rust_runtime_sequences(out: &mut String) {
    out.push_str(
        r#"
// Sequence message-passing runtime. Each sequence owns
// one FIFO queue indexed by a compile-time sequence id; `send` pushes
// to the target's queue, `broadcast` pushes to every queue, and a
// `receive` pops from the calling sequence's own queue. Messages are
// marshalled as a fixed f64 slot array - the codegen emits per-struct
// pack/unpack helpers on top of this.
#[derive(Clone, Copy, Default)]
pub struct SpassMsg {
    pub f: [f64; 8],
    pub n: usize,
}

// The queues and one condition variable per queue. A per-queue
// condition variable means a `send` wakes only the queue it targets; a
// single global condition variable with `notify_all` would wake every
// waiting sequence. The condvars are held behind an `Arc` so a waiter
// can keep a reference to its own while the state guard is moved into
// `Condvar::wait`.
struct SpassSeqState {
    queues: Vec<std::collections::VecDeque<SpassMsg>>,
    cvs: Vec<std::sync::Arc<std::sync::Condvar>>,
}

fn spass_seq_state() -> &'static std::sync::Mutex<SpassSeqState> {
    static STATE: std::sync::OnceLock<std::sync::Mutex<SpassSeqState>> = std::sync::OnceLock::new();
    STATE.get_or_init(|| std::sync::Mutex::new(SpassSeqState { queues: Vec::new(), cvs: Vec::new() }))
}

static SPASS_SEQ_HANDLES: std::sync::Mutex<Vec<std::thread::JoinHandle<()>>> =
    std::sync::Mutex::new(Vec::new());

pub fn spass_seq_init(count: usize) {
    let mut st = spass_seq_state().lock().expect("spass: seq queues poisoned");
    st.queues = vec![std::collections::VecDeque::new(); count];
    st.cvs = (0..count)
        .map(|_| std::sync::Arc::new(std::sync::Condvar::new()))
        .collect();
}

pub fn spass_seq_send(target: usize, m: SpassMsg) -> bool {
    let mut st = spass_seq_state().lock().expect("spass: seq queues poisoned");
    st.queues
        .get_mut(target)
        .expect("spass: send to unknown sequence")
        .push_back(m);
    st.cvs[target].notify_one();
    true
}

pub fn spass_seq_broadcast(m: SpassMsg) -> bool {
    let mut st = spass_seq_state().lock().expect("spass: seq queues poisoned");
    for q in st.queues.iter_mut() {
        q.push_back(m);
    }
    for cv in st.cvs.iter() {
        cv.notify_all();
    }
    true
}

/// Block until a message arrives for `self_id`. The wait is a
/// condition-variable wait, not a poll: an idle sequence burns no
/// CPU and wakes as soon as its queue is signalled.
pub fn spass_seq_recv(self_id: usize) -> SpassMsg {
    let mut st = spass_seq_state().lock().expect("spass: seq queues poisoned");
    loop {
        if let Some(m) = st.queues[self_id].pop_front() {
            return m;
        }
        let cv = st.cvs[self_id].clone();
        st = cv.wait(st).expect("spass: seq queues poisoned");
    }
}

pub fn spass_seq_spawn(entry: extern "C" fn()) {
    SPASS_SEQ_HANDLES
        .lock()
        .expect("spass: seq handles poisoned")
        .push(std::thread::spawn(move || entry()));
}

pub fn spass_seq_wait_all() {
    for h in SPASS_SEQ_HANDLES.lock().expect("spass: seq handles poisoned").drain(..) {
        let _ = h.join();
    }
}
"#,
    );
}

// ============================================================================
// Tests
// ============================================================================

#[cfg(test)]
mod tests {
    use super::*;
    use spass_parser::Parser;
    use spass_semantic::{analyze, TypedParam};

    #[test]
    fn mangle_float_float() {
        let f = TypedFunc {
            name: "height".into(),
            params: vec![
                TypedParam { name: "x".into(), ty: Type::Float(None), is_out: false, span: spass_lexer::Span::dummy() },
                TypedParam { name: "z".into(), ty: Type::Float(None), is_out: false, span: spass_lexer::Span::dummy() },
            ],
            return_type: Some(Type::Float(None)),
            multi_returns: None,
            is_gpu: false,
            has_checkpoint: false,
            has_resume: false,
            has_await: false,
            await_binding: None,
            has_if_present: false,
            if_present_param: None,
            tags: vec![],
            // this test-only TypedFunc has no
            // captures, no enclosing function, no source file
            // - the codegen layer reads these fields to decide
            // whether to hoist (ownclude) or skip the public
            // export (fileclude), and we only need the name +
            // params + return type for the mangle test.
            captures: Vec::new(),
            enclosing_func: None,
            source_file: String::new(),
            span: spass_lexer::Span::dummy(),
            original: spass_parser::ast::FuncDef {
                name: "height".into(),
                params: vec![],
                return_type: Some(Type::Float(None)),
                multi_returns: None,
                body: spass_parser::ast::Block { stmts: vec![], span: spass_lexer::Span::dummy() },
                annotations: vec![],
                visibility: spass_parser::ast::Visibility::Public,
                source_file: String::new(),
                enclosing_func: None,
                span: spass_lexer::Span::dummy(),
            },
        };
        assert_eq!(mangle_function_name(&f), "_spass_height_2_f_f");
    }

    #[test]
    fn mangle_type_codes() {
        assert_eq!(mangle_type(&Type::Float(None)), "f");
        assert_eq!(mangle_type(&Type::Int(None)), "i");
        assert_eq!(mangle_type(&Type::Uint(None)), "u");
        assert_eq!(mangle_type(&Type::Bool), "b");
        assert_eq!(mangle_type(&Type::String), "s");
        assert_eq!(mangle_type(&Type::Vec2(None, None)), "2f");
        assert_eq!(mangle_type(&Type::Vec3(None, None, None)), "3f");
        assert_eq!(mangle_type(&Type::Vec4(None, None, None, None)), "4f");
        assert_eq!(mangle_type(&Type::Mat3), "m3");
        assert_eq!(mangle_type(&Type::Mat4), "m4");
        assert_eq!(mangle_type(&Type::List(Box::new(Type::Float(None)))), "af");
        assert_eq!(mangle_type(&Type::Struct("TerrainPoint".into(), spass_lexer::Span::dummy())), "sTerrainPoint");
    }

    #[test]
    fn end_to_end_simple_function() {
        let src = "func add(a: float, b: float): float { return a + b }";
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("_spass_add_2_f_f"), "missing mangled name:\n{}", c);
        assert!(c.contains("return"), "missing return:\n{}", c);
        assert!(c.contains("spass_"), "missing runtime reference:\n{}", c);
    }

    #[test]
    fn end_to_end_with_builtin() {
        // Use a real built-in (`sin`) so the semantic pass accepts the
        // call. The C output should contain a call to the runtime helper
        // `spass_sin`.
        let src = r#"
            func f(x: float): float { return sin(x) * 2.0 }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("spass_sin("), "missing call to spass_sin:\n{}", c);
        assert!(c.contains("spass_sin"), "missing runtime spass_sin:\n{}", c);
    }

    #[test]
    fn end_to_end_control_flow() {
        let src = r#"
            func classify(x: float): int {
                if x > 0.0 {
                    return 1
                } else {
                    return -1
                }
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("if ("), "missing if:\n{}", c);
        assert!(c.contains("} else"), "missing else:\n{}", c);
    }

    #[test]
    fn end_to_end_for_loop() {
        let src = r#"
            func sum_to(n: int): int {
                let total: int = 0
                for i in 0..n {
                    total = total + i
                }
                return total
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("for ("), "missing for loop:\n{}", c);
        assert!(c.contains("i++"), "missing increment:\n{}", c);
    }

    #[test]
    fn end_to_end_rust_emission() {
        let src = "func add(a: float, b: float): float { return a + b }";
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        assert!(rs.contains("pub extern \"C\" fn _spass_add_2_f_f"), "missing mangled symbol:\n{}", rs);
        assert!(rs.contains("pub fn spass_sin"), "missing runtime spass_sin:\n{}", rs);
        assert!(rs.contains("fn main()"), "missing main:\n{}", rs);
    }

    /// The deeppack flavour packages the module as a shared library:
    /// the public functions are exported under their exact symbol name
    /// and there is no `main` to dispatch on argv.
    #[test]
    fn cdylib_flavour_exports_symbols_without_main() {
        let src = r#"
            func add(a: float, b: float): float { return a + b }
            fileclude func half(x: float): float { return x * 0.5 }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");

        let cdylib = generate_rust_with(&typed, RustFlavor::Cdylib).expect("cdylib codegen");
        assert!(
            cdylib.contains("#[no_mangle]\npub extern \"C\" fn _spass_add_2_f_f"),
            "the public export must carry #[no_mangle]:\n{}", cdylib
        );
        assert!(
            !cdylib.contains("fn main()"),
            "a shared library must not have a main:\n{}", cdylib
        );
        // A file-private helper stays private: it is not part of the
        // surface the host can reach.
        assert!(
            !cdylib.contains("#[no_mangle]\nextern \"C\" fn _spass_half_1_f"),
            "a private helper must not be exported:\n{}", cdylib
        );

        // The program flavour is unchanged.
        let program = generate_rust(&typed).expect("rust codegen");
        assert!(program.contains("fn main()"), "missing main:\n{}", program);
        assert!(
            !program.contains("#[no_mangle]"),
            "the program flavour must not export symbols:\n{}", program
        );
    }

    /// A float[0.0, 1.0, 0.5] domain has 3 states -> ceil(log2(3)) = 2 bits,
    /// so the ABI should use `uint8_t`. The body should decode the uintN
    /// via `0.0 + 0.5 * __sp_in_x` and encode the return via `spass_clamp`.
    #[test]
    fn value_domain_3_states() {
        let src = r#"
            func passthrough(x: float[0.0, 1.0, 0.5]): float[0.0, 1.0, 0.5] {
                return x
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // ABI: uint8_t because 2 bits.
        assert!(c.contains("uint8_t __sp_in_x"), "param not encoded as uint8_t:\n{}", c);
        // ABI: uint8_t return.
        assert!(c.contains("uint8_t _spass_passthrough"), "return not encoded as uint8_t:\n{}", c);
        // Body decode.
        assert!(
            c.contains("0.0 + 0.5 * __sp_in_x") || c.contains("0.0+0.5*__sp_in_x"),
            "missing decode line:\n{}",
            c
        );
        // Body encode on return: the state index is
        // `round((x - min) * k)` with `k = 1/step = 2`, clamped into
        // `[0, state_count - 1]`.
        assert!(
            c.contains("spass_enc_state((double)(x), 0.0, 2.0, 3.0)"),
            "missing encode on return:\n{}",
            c
        );
    }

    /// A float[0.0, 380.0, 0.1] domain has 3801 states -> 12 bits,
    /// so the ABI should use `uint16_t`.
    #[test]
    fn value_domain_12_bits() {
        let src = r#"
            func h(x: float[0.0, 380.0, 0.1]): float[0.0, 380.0, 0.1] {
                return x
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("uint16_t __sp_in_x"), "param not encoded as uint16_t:\n{}", c);
        assert!(c.contains("uint16_t _spass_h"), "return not encoded as uint16_t:\n{}", c);
        assert!(c.contains("0.0 + 0.1 * __sp_in_x") || c.contains("0.0+0.1*__sp_in_x"),
                "missing decode line:\n{}", c);
    }

    /// A function with mixed value-domain and unconstrained parameters
    /// should only encode the constrained one.
    #[test]
    fn value_domain_mixed_params() {
        let src = r#"
            func add_quant(a: float[0.0, 1.0, 0.1], b: float): float {
                return a + b
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // `a` has a value-domain -> uint16_t (101 states -> 7 bits -> uint8_t).
        assert!(c.contains("uint8_t __sp_in_a") || c.contains("uint16_t __sp_in_a"),
                "param `a` not encoded:\n{}", c);
        // `b` is unconstrained -> `double b`.
        assert!(c.contains("double b"), "unconstrained param `b` not emitted as double:\n{}", c);
    }

    /// The Rust emitter (used by `spass run`) must mirror the C emitter's
    /// encoding. A 3-state domain encodes as u8; the body decodes to f64
    /// via `0.0 + 0.5 * __x as f64` and encodes the return via `clamp`.
    #[test]
    fn rust_value_domain_round_trip() {
        let src = r#"
            func passthrough(x: float[0.0, 1.0, 0.5]): float[0.0, 1.0, 0.5] {
                return x
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        // Param becomes __x: u8.
        assert!(rs.contains("__x: u8"), "param not encoded as u8:\n{}", rs);
        // Return type becomes u8.
        assert!(rs.contains("-> u8"), "return not u8:\n{}", rs);
        // Decode: `let x: f64 = 0.0 + 0.5 * (__x as f64);`
        assert!(
            rs.contains("let x: f64 = 0.0 + 0.5 * (__x as f64)"),
            "missing decode line:\n{}",
            rs
        );
        // Encode: `spass_enc_state((x) as f64, 0.0, 2.0, 3.0) as u8`
        // -- the state index is `round((x - min) * k)` with
        // `k = 1/step = 2`, clamped into `[0, state_count - 1]`.
        assert!(
            rs.contains("spass_enc_state((x) as f64, 0.0, 2.0, 3.0) as u8"),
            "missing encode line:\n{}",
            rs
        );
    }

    /// A call to a value-domain function must encode the argument into
    /// the domain's state index. Before this, the argument crossed the
    /// ABI raw: the Rust backend rejected it with a type error and the
    /// C backend truncated it silently.
    #[test]
    fn value_domain_call_site_encodes_argument() {
        let src = r#"
            func height(x: float[0.0, 380.0, 0.1]): float[0.0, 380.0, 0.1] {
                return x
            }
            func caller(y: float) {
                let h = height(y)
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        let c = generate_c(&typed).expect("codegen");
        // The argument's range is unknown (`y` is an unconstrained
        // float), so the encode clamps.
        assert!(
            rs.contains("_spass_height_1_f(spass_enc_state((y) as f64, 0.0, 10.0, 3801.0) as u16)"),
            "missing clamped encode in Rust:\n{}",
            rs
        );
        assert!(
            c.contains("_spass_height_1_f((uint16_t)spass_enc_state((double)(y), 0.0, 10.0, 3801.0))"),
            "missing clamped encode in C:\n{}",
            c
        );
    }

    /// When the argument's range is provably inside the callee's
    /// domain, the clamp cannot fire and is dropped -- the clamp-free
    /// encode is a plain `round((v - min) * k)`.
    #[test]
    fn value_domain_call_site_elides_clamp_in_domain() {
        let src = r#"
            func height(x: float[0.0, 380.0, 0.1]): float[0.0, 380.0, 0.1] {
                return x
            }
            func caller() {
                let h = height(12.5)
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        let c = generate_c(&typed).expect("codegen");
        assert!(
            rs.contains("_spass_height_1_f(spass_round((((12.5f64) as f64) - 0.0) * 10.0) as u16)"),
            "missing clamp-free encode in Rust:\n{}",
            rs
        );
        assert!(
            c.contains("_spass_height_1_f((uint16_t)spass_round(((double)((12.5)) - 0.0) * 10.0))"),
            "missing clamp-free encode in C:\n{}",
            c
        );
    }

    /// The callee returns the encoded state; the Spass level sees the
    /// decoded value, so the call site decodes the result.
    #[test]
    fn value_domain_call_site_decodes_result() {
        let src = r#"
            func height(x: float[0.0, 380.0, 0.1]): float[0.0, 380.0, 0.1] {
                return x
            }
            func caller(y: float) {
                let h = height(y)
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        let c = generate_c(&typed).expect("codegen");
        assert!(
            rs.contains("let mut h: f64 = 0.0 + 0.1 * (_spass_height_1_f("),
            "missing result decode in Rust:\n{}",
            rs
        );
        assert!(
            c.contains("double h = 0.0 + 0.1 * (double)(_spass_height_1_f("),
            "missing result decode in C:\n{}",
            c
        );
    }

    /// An argument whose range is provably disjoint from the callee's
    /// domain is a program error and is reported as one.
    #[test]
    fn value_domain_call_site_rejects_disjoint_argument() {
        let src = r#"
            func height(x: float[0.0, 380.0, 0.1]): float[0.0, 380.0, 0.1] {
                return x
            }
            func caller() {
                let h = height(1000.0)
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let err = generate_rust(&typed).expect_err("disjoint argument must be rejected");
        let msg = err.to_string();
        assert!(
            msg.contains("outside the value domain"),
            "unexpected diagnostic: {}",
            msg
        );
    }

    /// Multi-return - function returns a tuple via an
    /// anonymous struct. The C emitter must use a struct literal with
    /// `_f<i>` fields, and the destructuring `let (a, b) = f` at the
    /// call site must extract each field.
    #[test]
    fn multi_return_c_emission() {
        let src = r#"
            func split(x: float): (float, float) {
                return (x, x * 2.0)
            }
            func caller(): float {
                let (a, b) = split(3.0)
                return a + b
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // The function returns an anonymous struct { double _f0; double _f1; }.
        assert!(
            c.contains("struct { double _f0; double _f1; }"),
            "missing multi-return struct type:\n{}",
            c
        );
        // The return site uses a struct literal.
        assert!(
            c.contains("return ({._f0 =") || c.contains("return ({ ._f0 ="),
            "missing struct-literal return:\n{}",
            c
        );
        // The destructuring at the call site uses a temporary and field
        // accesses.
        assert!(
            c.contains("__sp_tup._f0") && c.contains("__sp_tup._f1"),
            "missing destructure fields:\n{}",
            c
        );
    }

    /// Multi-return on the Rust emitter must produce an FFI-safe
    /// `#[repr(C)]` struct (`SpassRet<N>`) as the return type, a
    /// `SpassRet<N> { _f0: a, _f1: b }` return literal, and a
    /// destructuring call site that uses a temporary + field access
    /// (rather than a native tuple pattern, which is not FFI-safe for
    /// `extern "C"`).
    #[test]
    fn multi_return_rust_emission() {
        let src = r#"
            func split(x: float): (float, float) {
                return (x, x * 2.0)
            }
            func caller(): float {
                let (a, b) = split(3.0)
                return a + b
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        // FFI-safe return type: `SpassRet2`. A native `(f64, f64)` is
        // not FFI-safe and would trigger a hard error at the extern
        // boundary, so we pin the struct form.
        assert!(
            rs.contains("-> SpassRet2"),
            "missing FFI-safe SpassRet2 return type:\n{}",
            rs
        );
        // Struct-literal return site.
        assert!(
            rs.contains("return SpassRet2 {"),
            "missing struct-literal return:\n{}",
            rs
        );
        // Destructuring via a temporary and field access, not a native
        // tuple pattern.
        assert!(
            rs.contains("let __sp_tup: SpassRet2 = _spass_split_1_f("),
            "missing destructuring temporary:\n{}",
            rs
        );
        assert!(
            rs.contains("__sp_tup._f0") && rs.contains("__sp_tup._f1"),
            "missing destructure field access:\n{}",
            rs
        );
    }

    /// Single-binding `let name = expr;` still works after the AST
    /// change to `names: Vec<String>`.
    #[test]
    fn let_single_binding_unchanged() {
        let src = "func f(x: float): float { let y: float = x * 2.0; return y }";
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // The single-binding form must still emit a `double y =...`
        // declaration. We don't pin the exact parenthesisation of the
        // RHS because the binop emitter is allowed to vary.
        assert!(c.contains("double y ="),
                "single-binding form broken:\n{}", c);
        assert!(c.contains("return y"),
                "missing `return y`:\n{}", c);
    }

    /// Mismatch between destructured arity and the callee's multi-return
    /// arity is caught at semantic-analysis time.
    #[test]
    fn destructuring_arity_mismatch() {
        let src = r#"
            func split(x: float): (float, float) {
                return (x, x * 2.0)
            }
            func caller(): float {
                let (a, b, c) = split(3.0)
                return a
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let err = analyze(&module).expect_err("should reject arity mismatch");
        let msg = format!("{}", err);
        assert!(msg.contains("destructuring"),
                "expected destructuring error, got: {}", msg);
    }

    /// Multi-return with 3 elements exercises the `SpassRet3` struct
    /// (the Rust emitter de-duplicates structs by arity) and a
    /// triple-destructure call site.
    #[test]
    fn multi_return_three_elements() {
        let src = r#"
            func split3(x: float): (float, float, float) {
                return (x, x * 2.0, x * 3.0)
            }
            func caller3(): float {
                let (a, b, c) = split3(2.0)
                return a + b + c
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        let c = generate_c(&typed).expect("c codegen");
        // Rust: `SpassRet3` struct with three f64 fields.
        assert!(rs.contains("pub struct SpassRet3"),
                "missing SpassRet3:\n{}", rs);
        assert!(rs.contains("-> SpassRet3"),
                "missing return type SpassRet3:\n{}", rs);
        // Rust: 3-field destructure via temporary.
        assert!(rs.contains("let __sp_tup: SpassRet3 = _spass_split3_1_f("),
                "missing 3-arity destructuring:\n{}", rs);
        // C: anonymous struct with three double fields.
        assert!(c.contains("struct { double _f0; double _f1; double _f2; }"),
                "missing C struct with 3 fields:\n{}", c);
    }

    /// Multi-return with mixed types exercises the per-field
    /// `rust_scalar_type` mapping (e.g. `(float, int)` -> `SpassRet2 { f64, i32 }`).
    #[test]
    fn multi_return_mixed_types() {
        let src = r#"
            func mixed(x: float): (float, int) {
                let n: int = 42
                return (x, n)
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        let c = generate_c(&typed).expect("c codegen");
        // Rust: one f64 field, one i32 field.
        assert!(rs.contains("pub _f0: f64"), "missing f64 field 0:\n{}", rs);
        assert!(rs.contains("pub _f1: i32"), "missing i32 field 1:\n{}", rs);
        // C: anonymous struct with one double and one int32_t.
        assert!(c.contains("struct { double _f0; int32_t _f1; }"),
                "missing mixed-type C struct:\n{}", c);
    }

    /// A multi-return function without an explicit `return` must still
    /// produce a valid Rust return: a zero-initialised `SpassRetN` value.
    /// This codepath was the source of an FFI bug earlier (returning
    /// `` silently dropped the struct).
    #[test]
    fn multi_return_implicit_return() {
        let src = r#"
            func silent(): (float, float) {
                let x: float = 1.0
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        // Implicit return emits a `SpassRet2` struct literal with both
        // fields zeroed.
        assert!(rs.contains("SpassRet2 { _f0: 0.0, _f1: 0.0 }"),
                "missing zero-initialised SpassRet2 return:\n{}", rs);
    }

    /// `out` parameter ABI. The C emitter takes a
    /// `T*` slot per `out` param, declares a `double` shadow at
    /// function entry, and writes through the pointer on assignment.
    #[test]
    fn out_param_c_emission() {
        let src = r#"
            func write(x: float, out r: float) {
                r = x
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // Param shape: `double* __sp_out_r`. The `__sp_out_` prefix
        // is the caller's slot.
        assert!(c.contains("double* __sp_out_r"),
                "missing out-pointer param:\n{}", c);
        // Entry shadow: `double r = *__sp_out_r;` reads the caller's
        // value at entry so the body can refer to `r` directly.
        assert!(c.contains("double r = *__sp_out_r;"),
                "missing entry shadow:\n{}", c);
        // Assignment writes back through the pointer.
        assert!(c.contains("*__sp_out_r = r;"),
                "missing write-through assignment:\n{}", c);
    }

    /// Value-domain `out` param ABI: the slot is `uintN_t*`, the body
    /// shadow is decoded from the slot, and the assignment re-encodes
    /// through `spass_enc_state` to the ABI type.
    #[test]
    fn out_param_value_domain_c_emission() {
        let src = r#"
            func writeq(x: float, out q: float[0.0, 380.0, 0.1]) {
                q = x
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // Slot ABI: `uint16_t* __sp_out_q` (3801 states -> 12 bits).
        assert!(c.contains("uint16_t* __sp_out_q"),
                "missing value-domain out slot:\n{}", c);
        // Body shadow: decode via `0.0 + 0.1 * (*__sp_out_q)`.
        assert!(c.contains("0.0 + 0.1 * (*__sp_out_q)"),
                "missing decode from slot:\n{}", c);
        // Re-encode on assignment via `spass_enc_state`, with the
        // domain's exact reciprocal `k = 1/0.1 = 10`.
        assert!(c.contains("__sp_out_q = (uint16_t)spass_enc_state((double)(q), 0.0, 10.0, 3801.0)"),
                "missing encode-on-assign:\n{}", c);
    }

    /// `out` parameter ABI in Rust: the slot is `&mut T` (FFI-safe),
    /// the body shadow is a `let mut f64`, and the write-through
    /// mirrors the local back through the reference.
    #[test]
    fn out_param_rust_emission() {
        let src = r#"
            func write(x: float, out r: float) {
                r = x
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        // Param shape: `&mut f64` (FFI-safe mirror of the C `double*`).
        assert!(rs.contains("__sp_out_r: &mut f64"),
                "missing &mut out slot:\n{}", rs);
        // Entry shadow: `let mut r: f64 = *__sp_out_r;`.
        assert!(rs.contains("let mut r: f64 = *__sp_out_r;"),
                "missing entry shadow:\n{}", rs);
        // Write-through assignment.
        assert!(rs.contains("*__sp_out_r = r;"),
                "missing write-through:\n{}", rs);
        // Mangling uses the `o<enc>` prefix.
        assert!(rs.contains("_spass_write_2_f_of"),
                "missing out-mangled symbol:\n{}", rs);
    }

    // ----------------------------------------------------------------
    // @dispatch codegen
    // ----------------------------------------------------------------

    /// The OR selector matches two functions, neither has @before/@after,
    /// so the expansion preserves source order and emits one call per
    /// match: `h = erode(pos, h, 0.5)` then `h = deposit(pos, h, 0.7)`.
    #[test]
    fn dispatch_or_emits_left_fold_calls() {
        let src = r#"
            @tag(erosion) func erode(pos: float, h: float, strength: float): float { return h - strength }
            @tag(erosion) func deposit(pos: float, h: float, rate: float): float { return h + rate }
            func main(pos: float, h: float): float {
                @dispatch(tags = {erosion}, bind = {strength: 0.5, rate: 0.7})
                h = apply(pos, h)
                return h
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // Both matched functions should be called from main, with the
        // bind literals inlined at the call site.
        assert!(c.contains("h = _spass_erode_3_f_f_f(pos, h,"),
                "missing erode call in main:\n{}", c);
        assert!(c.contains("h = _spass_deposit_3_f_f_f(pos, h,"),
                "missing deposit call in main:\n{}", c);
    }

    /// `@before(F, require)` reorders: a must run before b. The
    /// expansion should emit a's call before b's, even when source
    /// order is the opposite.
    #[test]
    fn dispatch_topo_sort_respects_before() {
        let src = r#"
            @tag(ord) func b(pos: float, h: float): float { return h }
            @tag(ord) func a(pos: float, h: float): float {
                @before(b, require)
                return h
            }
            func main(pos: float, h: float): float {
                @dispatch(tags = {ord})
                h = apply(pos, h)
                return h
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // Source order is b, a, but @before(a, b) reorders: a first.
        // Find the call sites (not the function definitions) by looking
        // for the LHS pattern `h = _spass_X_...`.
        let a_call = "h = _spass_a_2_f_f(pos, h);";
        let b_call = "h = _spass_b_2_f_f(pos, h);";
        let a_pos = c.find(a_call).expect("a call site");
        let b_pos = c.find(b_call).expect("b call site");
        assert!(a_pos < b_pos,
                "a should run before b (a at {}, b at {}):\n{}", a_pos, b_pos, c);
    }

    /// Bind with `@tag(key)` reference is resolved at codegen by reading
    /// the value off the matched function's @tag annotation.
    #[test]
    fn dispatch_bind_tag_value_is_inlined() {
        let src = r#"
            @tag(erosion, strength=0.42) func erode(pos: float, h: float, strength: float): float { return h - strength }
            func main(pos: float, h: float): float {
                @dispatch(tags = {erosion}, bind = {strength: @tag(strength)})
                h = apply(pos, h)
                return h
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // The bind value (0.42) should appear in the body of erode AND
        // in main's expanded call site.
        assert!(c.contains("0.42") || c.contains("42") || c.contains("0.420"),
                "missing bind value 0.42:\n{}", c);
    }

    /// Same on the Rust emitter: a left-fold of two function calls
    /// threaded through the carry `h`.
    #[test]
    fn dispatch_rust_emits_left_fold_calls() {
        let src = r#"
            @tag(erosion) func erode(pos: float, h: float, strength: float): float { return h - strength }
            @tag(erosion) func deposit(pos: float, h: float, rate: float): float { return h + rate }
            func main(pos: float, h: float): float {
                @dispatch(tags = {erosion}, bind = {strength: 0.5, rate: 0.7})
                h = apply(pos, h)
                return h
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        assert!(rs.contains("_spass_erode_3_f_f_f("),
                "missing erode call:\n{}", rs);
        assert!(rs.contains("_spass_deposit_3_f_f_f("),
                "missing deposit call:\n{}", rs);
    }

    /// Struct-typed params on the Rust emitter must be built from the
    /// next N CLI args, one per field. Pin the literal that the
    /// dispatcher emits so a future refactor of the parser/dispatcher
    /// keeps the positional contract for `spass run`.
    #[test]
    fn struct_param_dispatcher_reads_positional_fields() {
        let src = r#"
            struct Point { x: float, y: float, height: float }
            func height_of(p: Point): float { return p.height }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        // Dispatcher must build the struct field-by-field from
        // positional args, not zero-fill it. The emitter opens the
        // struct literal on its own line, so each field appears on a
        // line of its own.
        assert!(
            rs.contains("x: fargs.get(_i + 0).copied().unwrap_or(0.0),"),
            "missing x field from CLI:\n{}",
            rs
        );
        assert!(
            rs.contains("y: fargs.get(_i + 1).copied().unwrap_or(0.0),"),
            "missing y field from CLI:\n{}",
            rs
        );
        assert!(
            rs.contains("height: fargs.get(_i + 2).copied().unwrap_or(0.0),"),
            "missing height field from CLI:\n{}",
            rs
        );
        // And the index advances by 3 (one per field), not 1.
        assert!(
            rs.contains("_i += 3;"),
            "missing _i += 3 stride for struct param:\n{}",
            rs
        );
        // No `Default::default` for the struct param any more -
        // that was the bug that made struct input silently zero.
        assert!(
            !rs.contains("let p: Point = Default::default()"),
            "dispatcher still uses Default for struct param:\n{}",
            rs
        );
    }

    // --------------------------------------------------------------------
    // if_present - codegen
    // --------------------------------------------------------------------
    //
    // A function with `if_present` compiles to two C/Rust functions
    // with `_present` / `_absent` suffix. The present variant runs
    // the user's `if_present(x) {... }` body; the absent variant
    // runs the `@absent {... }` body, or falls through if the
    // user wrote no `@absent` block.

    /// Pin the variant mangling: the present/absent symbols are
    /// distinct and the base name is the regular mangle.
    #[test]
    fn if_present_mangle_variants() {
        let src = r#"
            func f(x: float, y: float): float {
                if_present(x) {
                    return y
                } @absent {
                    return -y
                }
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let f = &typed.functions[0];
        let base = mangle_function_name(f);
        assert_eq!(base, "_spass_f_2_f_f");
        assert_eq!(
            mangle_function_name_variant(f, if_present_codegen::Variant::Present),
            "_spass_f_2_f_f_present"
        );
        assert_eq!(
            mangle_function_name_variant(f, if_present_codegen::Variant::Absent),
            "_spass_f_2_f_f_absent"
        );
        // `mangle_for_call` picks the present variant (Spass calls
        // always pass every parameter).
        assert_eq!(
            mangle_for_call(f),
            "_spass_f_2_f_f_present"
        );
    }

    // ========================================================================
    // @checkpoint / @resume state-machine wrapper
    // ========================================================================

    /// C codegen: a function containing a `@checkpoint` emits a wrapper
    /// that drives the runner in a loop until the task marks itself
    /// complete. Without the loop the wrapper would return at the
    /// first suspension site and read a not-yet-written return slot.
    ///
    /// Regression test for the D1 fix.
    #[test]
    fn checkpoint_c_wrapper_loops_until_complete() {
        let src = r#"
            func run(x: float): float { @checkpoint a; return x }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let c = generate_c(&typed).expect("C codegen");
        assert!(
            c.contains("while (!t->completed) { spass_task_resume(t); }"),
            "wrapper must drive the state machine in a loop:\n{}",
            c
        );
    }

    // ========================================================================
    // D5 - Cross-function @resume via `Box<dyn SpassState>`
    // ========================================================================
    //
    // D5 replaced the per-function `thread_local! SPASS_TASK_REGISTRY`
    // (which had a concrete `StateT` value type) with a module-level
    // `static SPASS_TASK_REGISTRY: Mutex<HashMap<String, Box<dyn
    // SpassState>>>`. Each checkpointed function then implements
    // `SpassState` on its own state struct; the shared registry can
    // hold entries with different concrete types, so a `@resume` in
    // function A can re-enter function B's state machine even when
    // A and B have different param/local shapes.

    /// The `SpassState` trait and the shared `SPASS_TASK_REGISTRY`
    /// are emitted ONCE per program, not once per checkpointed
    /// function. The per-function `impl SpassState for StateT` then
    /// refers to the same trait/registry. (D5 fix: the previous MVP
    /// emitted a per-function `thread_local!` registry, which
    /// physically could not be shared across heterogeneous state
    /// types.)
    #[test]
    fn d5_trait_and_registry_emitted_once() {
        // Distinct checkpoint names (the language forbids duplicates
        // across functions), but the two functions still share the
        // same module-level `SPASS_TASK_REGISTRY`.
        let src = r#"
            func a(x: float): float { @checkpoint k1; return x }
            func b(y: float, z: float): float { @checkpoint k2; return y }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");
        // Exactly one `trait SpassState` definition. The trait
        // declares `Send` as a super-trait so the registry's
        // `Box<dyn SpassState + Send>` is `Sync` (required for
        // `static` storage).
        let trait_count = r.matches("trait SpassState").count();
        assert_eq!(trait_count, 1, "SpassState trait must be defined once:\n{}", r);
        // Exactly one `static SPASS_TASK_REGISTRY` (the shared one).
        let registry_count = r.matches("static SPASS_TASK_REGISTRY").count();
        assert_eq!(
            registry_count, 1,
            "SPASS_TASK_REGISTRY must be defined once:\n{}",
            r
        );
        // Both functions get a per-function `impl SpassState for...`.
        let impl_count = r.matches("impl SpassState for").count();
        assert_eq!(
            impl_count, 2,
            "each checkpointed function must implement SpassState:\n{}",
            r
        );
    }

    /// The `@checkpoint` site boxes the current state into the
    /// shared `SPASS_TASK_REGISTRY` as `Box<dyn SpassState>`. The
    /// box type is what makes the cross-function dispatch work.
    #[test]
    fn d5_checkpoint_uses_boxed_state() {
        let src = r#"
            func a(x: float): float { @checkpoint k; return x }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");
        // The @checkpoint site must box the state with the
        // type-eraser `Box<dyn SpassState>` and insert via the
        // shared registry's `Mutex` API.
        assert!(
            r.contains("Box<dyn SpassState>"),
            "checkpoint must use Box<dyn SpassState>:\n{}",
            r
        );
        assert!(
            r.contains("SPASS_TASK_REGISTRY.lock().unwrap().insert("),
            "checkpoint must insert via the shared Mutex registry:\n{}",
            r
        );
    }

    /// The `@resume` site pulls the boxed state out of the
    /// registry, calls `.resume` on it (trait dispatch, which
    /// lands in the per-function runner), and re-inserts the
    /// (potentially-updated) box. The `.resume` call is the
    /// type-erased entry point that makes heterogeneous state
    /// types work.
    #[test]
    fn d5_resume_dispatches_via_trait() {
        let src = r#"
            func a(x: float): float { @checkpoint k; return x }
            func driver(x: float): float {
                let v: float = a(x)
                @resume k
                return v
            }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");
        // The @resume site emits a `.resume` call on the boxed
        // state, which is the trait dispatch.
        assert!(
            r.contains("__sp_box.resume();"),
            "resume site must dispatch via Box::resume() trait call:\n{}",
            r
        );
        // It also uses the same `SPASS_TASK_REGISTRY` (single
        // static, not per-function), confirming the cross-function
        // dispatch target.
        assert!(
            r.contains("SPASS_TASK_REGISTRY.lock().unwrap().remove("),
            "resume must pull from the shared registry:\n{}",
            r
        );
    }

    /// Heterogeneous state: two functions with different param
    /// counts and different local counts both emit valid state
    /// structs. The trait dispatch wires them to the SAME
    /// `SPASS_TASK_REGISTRY`, so a cross-function `@resume` from
    /// one to the other will compile (different concrete types
    /// stored as `Box<dyn SpassState>`).
    #[test]
    fn d5_heterogeneous_state_shares_registry() {
        // Distinct checkpoint names.
        let src = r#"
            func short(x: float): float { @checkpoint k1; return x }
            func long(a: float, b: float, c: float): float {
                let s: float = a + b + c
                @checkpoint k2
                return s
            }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");
        // Two distinct state struct types (one per function).
        // The struct name is `{mangled}_state_t` (single underscore)
        // - see `state_struct_name` in `checkpoint_codegen.rs`.
        assert!(
            r.contains("struct _spass_short_1_f_state_t"),
            "missing short state struct:\n{}",
            r
        );
        assert!(
            r.contains("struct _spass_long_3_f_f_f_state_t"),
            "missing long state struct:\n{}",
            r
        );
        // Both impl SpassState, both refer to the same registry
        // name. This is the structural property that makes
        // heterogeneous cross-function @resume work.
        let spass_state_for_short = r.contains(
            "impl SpassState for _spass_short_1_f_state_t"
        );
        let spass_state_for_long = r.contains(
            "impl SpassState for _spass_long_3_f_f_f_state_t"
        );
        assert!(
            spass_state_for_short && spass_state_for_long,
            "both functions must implement SpassState:\n{}",
            r
        );
    }

    /// The C emitter is unchanged by D5: the `spass_task_t` C
    /// runtime already used `void*` for the state, so cross-
    /// function @resume was always heterogeneous-friendly. This
    /// test pins that the C path still emits the same
    /// `spass_task_resume` loop pattern (no regression).
    #[test]
    fn d5_c_backend_unchanged() {
        let src = r#"
            func a(x: float): float { @checkpoint k; return x }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let c = generate_c(&typed).expect("C codegen");
        assert!(
            c.contains("while (!t->completed) { spass_task_resume(t); }"),
            "C wrapper must still loop on the state machine:\n{}",
            c
        );
        assert!(
            c.contains("spass_task_register("),
            "C backend must still register the task for cross-function @resume:\n{}",
            c
        );
    }

    /// Rust codegen: the wrapper drives the state machine to
    /// completion by calling `__sp_state.resume` - the trait-method
    /// indirection added in D5. The single trait call dispatches to
    /// the per-function runner (via `impl SpassState`), and is the
    /// same call site the cross-function `@resume` uses to re-enter
    /// a different function's state machine.
    #[test]
    fn checkpoint_rust_runner_drives_to_completion() {
        let src = r#"
            func run(x: float): float { @checkpoint a; return x }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");
        // The wrapper calls the trait method, not the free-function
        // runner directly. The trait call is the single point that
        // the cross-function registry dispatches into.
        assert!(
            r.contains("__sp_state.resume();"),
            "rust wrapper must call state.resume() (D5 trait dispatch):\n{}",
            r
        );
    }

    /// D5 regression: the trait impl must call the per-function
    /// runner (whose name is `<mangled>_runner`, set by
    /// `CheckpointPlan::build`). A previous revision wrote
    /// `{plan.runner}_runner(self)` and produced `<...>_runner_runner`,
    /// which is a free function that doesn't exist - every call site
    /// failed to resolve and the program didn't compile. This test
    /// pins the runner symbol as exactly `_spass_<name>_<arity>_<types>_runner`
    /// (no double `_runner_runner`).
    #[test]
    fn d5_trait_impl_calls_runner_with_single_suffix() {
        let src = r#"
            func erode(h: float, n: float): float {
                @checkpoint k
                return h + n
            }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");
        // The trait impl must call the single-suffix runner.
        assert!(
            r.contains("_spass_erode_2_f_f_runner(self);"),
            "trait impl must call <mangled>_runner, not <mangled>_runner_runner:\n{}",
            r
        );
        // And the bug pattern must NOT appear.
        assert!(
            !r.contains("_spass_erode_2_f_f_runner_runner(self)"),
            "trait impl still calls <mangled>_runner_runner (D5 regression):\n{}",
            r
        );
    }

    /// D5: the shared registry is wrapped in `LazyLock` because
    /// `Mutex::new` is not `const fn` (it allocates), and a direct
    /// `static MUTEX = Mutex::new(...)` initializer fails to compile.
    /// The wrapper uses `LazyLock::new(||...)` and call sites
    /// deref through transparently, so the call pattern stays
    /// `SPASS_TASK_REGISTRY.lock.unwrap`.
    #[test]
    fn d5_registry_uses_lazy_lock() {
        let src = r#"
            func a(x: float): float { @checkpoint k; return x }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");
        // `LazyLock` is the static initialiser. The call sites
        // still go through `SPASS_TASK_REGISTRY.lock.unwrap`.
        assert!(
            r.contains("LazyLock::new("),
            "registry must be wrapped in LazyLock (Mutex::new is not const fn):\n{}",
            r
        );
        assert!(
            r.contains("use std::sync::LazyLock"),
            "LazyLock must be imported:\n{}",
            r
        );
    }

    /// D5: the `SpassState` trait declares `Send` as a super-trait
    /// so the boxed value can live in a `static` (the
    /// `Mutex<T>: Sync` bound requires `T: Send`). Every state
    /// struct is `Copy`, so the bound is satisfied for free.
    #[test]
    fn d5_spass_state_trait_requires_send() {
        let src = r#"
            func a(x: float): float { @checkpoint k; return x }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");
        // The trait must carry the `Send` bound.
        assert!(
            r.contains("trait SpassState: Send"),
            "SpassState must require Send (for static Mutex<HashMap<..., Box<dyn SpassState>>>):\n{}",
            r
        );
        // The registry type must mention the bound.
        assert!(
            r.contains("Box<dyn SpassState + Send>"),
            "registry must hold Box<dyn SpassState + Send>:\n{}",
            r
        );
    }

    // ========================================================================
    // @await codegen
    // ========================================================================

    /// C codegen: a function with `@await` + `spasio:input` is routed
    /// through the state-machine path (wrapper + runner + state struct).
    /// The runtime I/O call is emitted in the runner.
    #[test]
    fn await_c_emits_state_machine_and_runtime_call() {
        let src = r#"
            func read_height(): float {
                @await
                let h: float = spasio:input[file]("height")
                return h
            }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let c = generate_c(&typed).expect("C codegen");
        // State-machine wrapper + runner are emitted.
        assert!(c.contains("_spass_read_height_0_state_t"),
                "state struct missing:\n{}", c);
        assert!(c.contains("_spass_read_height_0_runner"),
                "runner missing:\n{}", c);
        // The spasio runtime call is invoked in the runner with the
        // file-mode constant and the channel name from the source.
        assert!(c.contains("spass_spasio_input(SPASS_SPASIO_FILE, \"height\")"),
                "spasio:input call missing:\n{}", c);
    }

    /// the Rust prelude implements socket mode end to
    /// end (frame encode/decode + listener/connect paths), replacing
    /// the old not-yet-implemented stub.
    #[test]
    fn rust_prelude_implements_socket_mode() {
        let mut prelude = String::new();
        emit_rust_runtime_spasio(&mut prelude);
        // spasio is a client RPC to the runner.
        assert!(prelude.contains("fn spass_spasio_rpc"), "rpc fn missing");
        assert!(prelude.contains("TcpStream::connect"), "runner connect missing");
        assert!(
            prelude.contains("SpasioMode::Socket | SpasioMode::Memory => 1"),
            "memory-to-socket mapping missing"
        );
        // The program process never touches the file system or binds a port.
        assert!(!prelude.contains("std::fs::read"), "file read still present");
        assert!(!prelude.contains("std::fs::write"), "file write still present");
        assert!(!prelude.contains("TcpListener::bind"), "bind listener still present");
        // Frame header is big-endian, body little-endian.
        assert!(prelude.contains("to_be_bytes()"), "header endianness");
        assert!(prelude.contains("to_le_bytes()"), "body endianness");
    }

    /// The spasio client keeps its runner connections in a pool instead
    /// of opening one per channel access, disables Nagle on every
    /// socket, and resolves the runner address and the project path
    /// once.
    #[test]
    fn rust_prelude_pools_runner_connections() {
        let mut prelude = String::new();
        emit_rust_runtime_spasio(&mut prelude);
        assert!(prelude.contains("fn spass_spasio_checkout"), "pool checkout missing");
        assert!(prelude.contains("fn spass_spasio_checkin"), "pool check-in missing");
        assert!(
            prelude.contains("fn spass_spasio_discard"),
            "failed connections must not be pooled"
        );
        assert!(
            prelude.contains("set_nodelay(true)"),
            "Nagle must be disabled on the runner socket"
        );
        // The address and the project path are process-level constants.
        assert!(
            prelude.contains("SPASS_SPASIO_ADDR") && prelude.contains("SPASS_SPASIO_PROJ"),
            "runner address / project path must be resolved once"
        );
        // A runner restart is survivable: one reconnect is attempted.
        assert!(
            prelude.contains("for attempt in 0..2"),
            "missing reconnect attempt"
        );
    }

    /// The sequence receive blocks on a per-queue condition variable
    /// instead of spinning on the queue.
    #[test]
    fn rust_prelude_sequences_use_a_condition_variable() {
        let mut prelude = String::new();
        emit_rust_runtime_sequences(&mut prelude);
        assert!(prelude.contains("fn spass_seq_recv"), "seq recv missing");
        assert!(
            prelude.contains("cv.wait(st)"),
            "sequence receive must wait on a condition variable"
        );
        // A spin loop burns a core while the sequence idles.
        assert!(
            !prelude.contains("yield_now"),
            "sequence receive still spins"
        );
    }

    /// The generated prelude only carries the runtime sections the
    /// program uses. A plain float program needs none of the vector,
    /// spasio, task or sequence runtimes, and none of the playground.
    #[test]
    fn rust_prelude_omits_unused_runtime_sections() {
        let src = "func add(a: float, b: float): float { return a + b }";
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        assert!(rs.contains("pub fn spass_sin"), "core runtime missing:\n{}", rs);
        assert!(!rs.contains("fn spass_spasio_rpc"), "spasio client emitted unused:\n{}", rs);
        assert!(!rs.contains("fn spass_spawn"), "task runtime emitted unused:\n{}", rs);
        assert!(!rs.contains("fn spass_seq_recv"), "sequence runtime emitted unused:\n{}", rs);
        assert!(!rs.contains("pub struct SpassVec2"), "vec runtime emitted unused:\n{}", rs);
        assert!(!rs.contains("fn spass_s2d_window"), "playground emitted unused:\n{}", rs);
    }

    /// A program that uses a vec keeps the vector runtime; a program
    /// that talks to a channel keeps the spasio client. A section that
    /// is dropped while it is still referenced does not compile, so
    /// this is a correctness test, not only a size test.
    #[test]
    fn rust_prelude_keeps_the_sections_a_program_uses() {
        let vec_src = r#"
            func vlen(x: float, y: float): float {
                let v: vec2 = mk_vec2(x, y)
                return length(v)
            }
        "#;
        let module = Parser::parse_source(vec_src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        assert!(rs.contains("pub struct SpassVec2"), "vec runtime missing:\n{}", rs);
        assert!(rs.contains("fn spass_length2"), "vec built-in missing:\n{}", rs);

        let spasio_src = r#"
            func poll(): float {
                let v = spasio:input[file]("scale")
                return v * 2.0
            }
        "#;
        let module = Parser::parse_source(spasio_src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        assert!(rs.contains("fn spass_spasio_rpc"), "spasio client missing:\n{}", rs);
        assert!(rs.contains("fn spass_spasio_input"), "spasio input missing:\n{}", rs);
    }

    /// The playground runtime is the largest section by far, so the C
    /// emitter drops it for every program that does not call into the
    /// `s2d:` / `s3d:` / `spio:` namespaces.
    #[test]
    fn c_emitter_gates_the_playground_runtime() {
        let plain = "func add(a: float, b: float): float { return a + b }";
        let module = Parser::parse_source(plain, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(!c.contains("spass_s2d_window"), "playground emitted unused:\n{}", c);

        let native = r#"
            func show(): float {
                let ok = s2d:window(320.0, 240.0, "t")
                return 0.0
            }
        "#;
        let module = Parser::parse_source(native, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("spass_s2d_window"), "playground missing:\n{}", c);
    }

    /// spawn/await emit a module-scope thunk per target
    /// function plus the runtime spawn/await calls. The task handle
    /// flows through the task variable as an opaque u64.
    #[test]
    fn spawn_await_rust_and_c_emission() {        let src = r#"
            func work(a: float, b: float): float {
                return a * 2.0 + b
            }
            func driver(x: float, y: float): float {
                let t = spawn work(x, y)
                return await(t)
            }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let c = generate_c(&typed).expect("C codegen");
        let r = generate_rust(&typed).expect("Rust codegen");

        // Thunks are emitted at module scope for the spawn target.
        assert!(c.contains("static void __sp_spawn_thunk__spass_work_2_f_f(const double* __sp_args, double* __sp_out)"),
                "C thunk missing:\n{}", c);
        assert!(r.contains("fn __sp_spawn_thunk__spass_work_2_f_f(args: &[f64], out: &mut f64)"),
                "Rust thunk missing:\n{}", r);
        // Call sites go through the runtime.
        assert!(c.contains("spass_spawn(__sp_spawn_thunk__spass_work_2_f_f, (const double[])"), "C spawn site:\n{}", c);
        assert!(r.contains("spass_spawn(__sp_spawn_thunk__spass_work_2_f_f, vec!["), "Rust spawn site:\n{}", r);
        assert!(c.contains("spass_task_await((uint64_t)(t))"), "C await site:\n{}", c);
        assert!(r.contains("spass_task_await(t as u64)"), "Rust await site:\n{}", r);
        // Task handle is a u64/uint64_t local.
        assert!(c.contains("uint64_t t ="), "C handle type:\n{}", c);
        assert!(r.contains("let mut t: u64 ="), "Rust handle type:\n{}", r);
    }

    /// sequences compile to zero-arg functions, the
    /// dispatcher starts one thread each and joins them via a drop
    /// guard, and send/receive marshal messages through the f64 slot
    /// pack/unpack helpers.
    #[test]
    fn sequence_send_receive_rust_emission() {
        let src = r#"
            struct Ping {
                value: float
            }
            sequence producer {
                send(consumer, Ping{value: 1.0})
            }
            sequence consumer {
                let m = receive Ping{value > 0.0}
            }
            func driver(): float {
                return 1.0
            }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");

        // Sequence ids and queue init.
        assert!(r.contains("const __SP_SEQ_ID_producer: usize = 0"), "ids:\n{}", r);
        assert!(r.contains("spass_seq_init(2)"), "queue init missing:\n{}", r);
        // One thread per sequence, joined by a drop guard.
        assert!(r.contains("spass_seq_spawn(_spass_producer_0);"), "spawn producer:\n{}", r);
        assert!(r.contains("spass_seq_spawn(_spass_consumer_0);"), "spawn consumer:\n{}", r);
        assert!(r.contains("impl Drop for __SpSeqJoin"), "join guard missing:\n{}", r);
        // Message marshalling.
        assert!(r.contains("fn __sp_pack_Ping"), "pack helper missing:\n{}", r);
        assert!(
            r.contains("spass_seq_send(__SP_SEQ_ID_consumer, __sp_pack_Ping(((Ping { value: (1f64) }).value) as f64))"),
            "send site:\n{}", r
        );
        assert!(
            r.contains("spass_seq_recv(__SP_SEQ_ID_consumer)"),
            "receive site:\n{}", r
        );
        assert!(r.contains("__sp_unpack_Ping(__sp_msg)"), "unpack call missing:\n{}", r);
    }

    /// Rust codegen: the same `read_height` function gets the same
    /// state-machine treatment AND the runner writes its local
    /// state back to `*t` so the wrapper sees the I/O result.
    /// This regression-tests a bug where the runner mutated a clone
    /// and the wrapper read the unchanged `t`.
    #[test]
    fn await_rust_runner_writes_state_back() {
        let src = r#"
            func read_height(): float {
                @await
                let h: float = spasio:input[file]("height")
                return h
            }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let r = generate_rust(&typed).expect("Rust codegen");
        // The runner function exists. The runner is the per-function
        // free function named `{mangled}_runner`; the trait impl
        // forwards `SpassState::resume` to it.
        assert!(r.contains("fn _spass_read_height_0_runner("),
                "rust runner missing:\n{}", r);
        // Every `return;` in the body is preceded by `*t = state;`
        // so the wrapper sees the I/O value before the runner exits.
        // Find at least one such pair.
        assert!(r.contains("*t = state;"),
                "rust runner must write state back to *t:\n{}", r);
        // The I/O call is in the runner.
        assert!(r.contains("spass_spasio_input(SpasioMode::File, \"height\")"),
                "spasio:input call missing in rust:\n{}", r);
    }

    /// C codegen: `@await` inside a plain (non-checkpoint) function
    /// reserves the Await slot in the state block. The slot is named
    /// after the bound local (`h` here), so the body emit's
    /// `state->h =...` is well-typed.
    #[test]
    fn await_state_block_includes_await_slot() {
        let src = r#"
            func f(): float {
                @await
                let h: float = spasio:input[file]("chan")
                return h
            }
        "#;
        let m = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&m).expect("analyse");
        let c = generate_c(&typed).expect("C codegen");
        // The state struct has a `h` member.
        assert!(c.contains("double h;"),
                "state struct missing `h` field:\n{}", c);
    }

    // ========================================================================
    // if_present codegen tests
    // ========================================================================

    /// C codegen: an `if_present` function emits BOTH the `_present`
    /// and `_absent` symbols, with the bodies swapped accordingly.
    #[test]
    fn if_present_c_emits_both_variants() {
        let src = r#"
            func f(x: float, y: float): float {
                if_present(x) {
                    return y
                } @absent {
                    return 0.0 - y
                }
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // Both symbols are emitted.
        assert!(
            c.contains("_spass_f_2_f_f_present"),
            "missing _present symbol:\n{}",
            c
        );
        assert!(
            c.contains("_spass_f_2_f_f_absent"),
            "missing _absent symbol:\n{}",
            c
        );
        // Neither variant still carries a `Stmt::IfPresent` - the
        // transform replaced them with the branch bodies. The
        // post-transform body has a plain `return y;` (or
        // `return 0.0 - y;` for the absent variant).
        // Locate the *definitions* (the last occurrence of each symbol
        // - the first is the forward declaration the codegen emits).
        let present_idx = c
            .rfind("_spass_f_2_f_f_present")
            .expect("present symbol");
        let absent_idx = c
            .rfind("_spass_f_2_f_f_absent")
            .expect("absent symbol");
        let present_body = &c[present_idx..absent_idx];
        let absent_body = &c[absent_idx..];
        assert!(
            present_body.contains("return y;"),
            "present variant missing `return y;`:\n{}",
            present_body
        );
        assert!(
            absent_body.contains("return 0.0 - y;")
                || absent_body.contains("return ((0) - y)")
                || absent_body.contains("return (0) - y"),
            "absent variant missing `return 0.0 - y;`:\n{}",
            absent_body
        );
        // No `if_present` should have leaked into the output.
        assert!(!c.contains("if_present"), "if_present leaked into output:\n{}", c);
    }

    /// When the user writes `if_present` with no `@absent` block, the
    /// absent variant must drop the `if_present` entirely (the
    /// statements following it run normally).
    #[test]
    fn if_present_without_absent_block_drops_in_absent() {
        let src = r#"
            func f(x: float, y: float): float {
                let pre: float = 1.0
                if_present(x) {
                    return y
                }
                let post: float = 2.0
                return pre + post
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // Locate the *definitions* (last occurrence - the first is the
        // forward declaration the codegen emits).
        let present_idx = c
            .rfind("_spass_f_2_f_f_present")
            .expect("present symbol");
        let absent_idx = c
            .rfind("_spass_f_2_f_f_absent")
            .expect("absent symbol");
        let present_body = &c[present_idx..absent_idx];
        let absent_body = &c[absent_idx..];
        // Present: only `return y;` after the pre-let.
        assert!(
            present_body.contains("return y;"),
            "present variant should `return y;`:\n{}",
            present_body
        );
        // Absent: no `if_present`; both `pre` and `post` lets survive,
        // and the final `return pre + post` runs.
        assert!(
            absent_body.contains("return (pre + post)")
                || absent_body.contains("return pre + post"),
            "absent variant should fall through and return pre+post:\n{}",
            absent_body
        );
        assert!(
            !absent_body.contains("if_present"),
            "absent variant should not mention if_present:\n{}",
            absent_body
        );
    }

    /// Rust codegen: both variants are exported; the present variant
    /// is the dispatcher default.
    #[test]
    fn if_present_rust_emits_both_variants_and_dispatcher() {
        let src = r#"
            func f(x: float, y: float): float {
                if_present(x) {
                    return y
                } @absent {
                    return 0.0 - y
                }
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("rust codegen");
        // Both functions exist.
        assert!(
            rs.contains("pub extern \"C\" fn _spass_f_2_f_f_present"),
            "missing _present Rust function:\n{}",
            rs
        );
        assert!(
            rs.contains("pub extern \"C\" fn _spass_f_2_f_f_absent"),
            "missing _absent Rust function:\n{}",
            rs
        );
        // Both are in the _exported list and the dispatch table.
        assert!(
            rs.contains("_spass_f_2_f_f_present")
                && rs.contains("_spass_f_2_f_f_absent"),
            "dispatcher should list both variants:\n{}",
            rs
        );
        // The present variant is the default `if fname ==...` arm.
        let present_match = rs
            .find("if fname == \"_spass_f_2_f_f_present\"")
            .expect("present match arm");
        let absent_match = rs
            .find("if fname == \"_spass_f_2_f_f_absent\"")
            .expect("absent match arm");
        assert!(
            present_match < absent_match,
            "present arm should be matched first (present at {}, absent at {}):\n{}",
            present_match,
            absent_match,
            rs
        );
    }

    /// An `if_present` function called from another function is
    /// resolved to the present variant (Spass calls always supply
    /// every argument). The internal call site uses the `_present`
    /// mangled symbol even though the user typed the plain name.
    #[test]
    fn if_present_internal_call_uses_present_variant() {
        let src = r#"
            func helper(x: float, y: float): float {
                if_present(x) {
                    return y
                } @absent {
                    return 0.0 - y
                }
            }
            func main(a: float, b: float): float {
                return helper(a, b)
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // `main` calls `_spass_helper_2_f_f_present` (the present
        // variant), not the unmangled symbol.
        assert!(
            c.contains("_spass_helper_2_f_f_present("),
            "internal call should target present variant:\n{}",
            c
        );
        assert!(
            !c.contains("_spass_helper_2_f_f("),
            "internal call should not target the un-suffixed symbol:\n{}",
            c
        );
    }

    // ========================================================================
    // vec/mat codegen tests
    // ========================================================================

    /// C codegen: a `vec3` parameter is emitted as `spass_vec3`,
    /// not as a raw array, so the C runtime can pass it by value.
    #[test]
    fn vec3_param_uses_spass_vec3_typedef() {
        let src = r#"
            func f(a: vec3): float { return a.x }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("spass_vec3 a"), "missing spass_vec3 typedef:\n{}", c);
    }

    /// C codegen: vec-vec add emits a struct literal that uses
    /// component-wise addition (no `<` comparison trick).
    #[test]
    fn vec3_add_emits_component_wise_addition() {
        let src = r#"
            func f(a: vec3, b: vec3): vec3 { return a + b }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // Each component appears on both sides of `+`.
        assert!(c.contains("a.x + b.x"), "missing a.x + b.x:\n{}", c);
        assert!(c.contains("a.y + b.y"), "missing a.y + b.y:\n{}", c);
        assert!(c.contains("a.z + b.z"), "missing a.z + b.z:\n{}", c);
    }

    /// C codegen: vec-scalar add broadcasts the scalar to all
    /// components, so `v + 1.0` is a vec3 with each component
    /// incremented by 1.0. The FloatLit codegen wraps the
    /// literal in parens (`(1)`) so we only check for the
    /// scalar operand without the `.x` accessor.
    #[test]
    fn vec3_add_scalar_broadcasts() {
        let src = r#"
            func f(a: vec3): vec3 { return a + 1.0 }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        // No `.x` (or `.y`/`.z`) on the scalar side.
        assert!(!c.contains("(1).x"), "scalar got .x accessor (no broadcast):\n{}", c);
        assert!(!c.contains("(1).y"), "scalar got .y accessor (no broadcast):\n{}", c);
        assert!(!c.contains("(1).z"), "scalar got .z accessor (no broadcast):\n{}", c);
    }

    /// C codegen: `dot(vec3, vec3)` resolves to `spass_dot3` so
    /// the runtime's specialised 3-vec implementation runs (the
    /// dispatcher is `dot`; the codegen lifts the dimension from
    /// the argument type).
    #[test]
    fn vec3_dot_dispatches_to_spass_dot3() {
        let src = r#"
            func f(a: vec3, b: vec3): float { return dot(a, b) }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("spass_dot3("), "missing spass_dot3:\n{}", c);
    }

    /// C codegen: `mk_vec3(x, y, z)` resolves to the runtime's
    /// `spass_mk_vec3` constructor so a struct literal isn't
    /// repeated at every call site.
    #[test]
    fn vec3_constructor_uses_runtime_helper() {
        let src = r#"
            func f(x: float, y: float, z: float): vec3 { return mk_vec3(x, y, z) }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("spass_mk_vec3("), "missing spass_mk_vec3:\n{}", c);
    }

    /// Rust codegen: the `+` operator on `SpassVec3` resolves
    /// through the `Add` trait implementation emitted in the
    /// runtime prelude (so the generated code is `a + b`, not a
    /// manual component-wise expression).
    #[test]
    fn rust_vec3_add_uses_operator() {
        let src = r#"
            func f(a: vec3, b: vec3): vec3 { return a + b }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        let rs = generate_rust(&typed).expect("codegen");
        assert!(rs.contains("a + b"), "missing a + b:\n{}", rs);
        assert!(rs.contains("impl core::ops::Add<SpassVec3> for SpassVec3"),
                "missing Add trait impl in runtime:\n{}", rs);
    }

    // ====================================================================
    // module system (ownclude hoisting / private linkage)
    // ====================================================================

    /// Shared fixture: the examples/module scenario. `half` is a
    /// `fileclude` helper, `scale` is an `ownclude` closure capturing
    /// `base` by value.
    fn module_fixture() -> spass_semantic::TypedModule {
        let src = r#"
            func add(a: float, b: float): float { return a + b }
            fileclude func half(x: float): float { return x * 0.5 }
            func compute_a(x: float): float {
                let h = half(x)
                return add(h, h)
            }
            func compute_b(x: float): float {
                let base = x + 5.0
                ownclude func scale(t: float): float {
                    return t * base + 1.0
                }
                let a = scale(2.0)
                let b = scale(3.0)
                return add(a, b)
            }
        "#;
        let module = Parser::parse_source(src, "<test>").expect("parse");
        analyze(&module).expect("analyse")
    }

    /// The hoisted ownclude helper is a `static` C function whose
    /// signature prepends the captured variables, and its call sites
    /// forward those captures by name.
    #[test]
    fn ownclude_helper_has_capture_params_in_c() {
        let typed = module_fixture();
        let c = generate_c(&typed).expect("codegen");
        // Minimal capture: only `base` is read by the closure body,
        // so the mangle carries exactly one capture type (`c_1_f`).
        assert!(
            c.contains("static double _spass_compute_b_scale_c_1_f_1_f(double base, double t)"),
            "hoisted helper missing capture params:\n{}", c
        );
        // Call sites forward the capture.
        assert!(
            c.contains("_spass_compute_b_scale_c_1_f_1_f(base, (2))"),
            "call site does not forward captures:\n{}", c
        );
    }

    /// A closure that captures variables is not spawn-compatible: the
    /// hoisted helper takes the captures as extra leading parameters and
    /// a module-scope thunk has no way to supply them. Emitting a thunk
    /// for it would call a two-parameter helper with one argument.
    #[test]
    fn capture_bearing_closure_gets_no_spawn_thunk() {
        let typed = module_fixture();
        let c = generate_c(&typed).expect("C codegen");
        let r = generate_rust(&typed).expect("Rust codegen");
        assert!(
            !c.contains("__sp_spawn_thunk__spass_compute_b_scale_c_1_f_1_f"),
            "C must not emit a thunk for a closure with captures:\n{}", c
        );
        assert!(
            !r.contains("__sp_spawn_thunk__spass_compute_b_scale_c_1_f_1_f"),
            "Rust must not emit a thunk for a closure with captures:\n{}", r
        );
        // A plain function in the same module keeps its thunk.
        assert!(
            r.contains("__sp_spawn_thunk__spass_compute_a_1_f"),
            "plain function must keep its thunk:\n{}", r
        );
    }

    /// `fileclude` and `ownclude` functions get internal (`static`)
    /// linkage in C - they must not enter the global namespace.
    #[test]
    fn private_functions_are_static_in_c() {
        let typed = module_fixture();
        let c = generate_c(&typed).expect("codegen");
        assert!(
            c.contains("static double _spass_half_1_f(double x) {"),
            "fileclude must be static:\n{}", c
        );
        // Public functions stay external.
        assert!(
            c.contains("\ndouble _spass_compute_a_1_f(double x) {"),
            "public function must keep external linkage:\n{}", c
        );
    }

    /// Every function gets a C prototype (from the same signature
    /// helper as the definitions), so the hoisted ownclude helper -
    /// emitted after its enclosing function - is declared before use.
    #[test]
    fn forward_declarations_cover_all_functions() {
        let typed = module_fixture();
        let c = generate_c(&typed).expect("codegen");
        assert!(c.contains("/* Forward declarations */"), "missing decl block:\n{}", c);
        assert!(
            c.contains("static double _spass_half_1_f(double x);"),
            "missing fileclude prototype:\n{}", c
        );
        assert!(
            c.contains("static double _spass_compute_b_scale_c_1_f_1_f(double base, double t);"),
            "missing ownclude prototype:\n{}", c
        );
    }

    /// In Rust, private functions stay module-private (no `pub`) and
    /// the dispatch main only covers Public functions.
    #[test]
    fn rust_dispatch_and_pub_are_public_only() {
        let typed = module_fixture();
        let rs = generate_rust(&typed).expect("codegen");
        // Private helpers are emitted without `pub`.
        assert!(
            !rs.contains("pub extern \"C\" fn _spass_half_1_f"),
            "fileclude must not be pub:\n{}", rs
        );
        assert!(
            rs.contains("extern \"C\" fn _spass_half_1_f("),
            "fileclude definition must still be emitted:\n{}", rs
        );
        assert!(
            !rs.contains("pub extern \"C\" fn _spass_compute_b_scale"),
            "ownclude helper must not be pub:\n{}", rs
        );
        // The dispatcher's help list and arms only list public symbols.
        assert!(
            !rs.contains("if fname == \"_spass_half_1_f\""),
            "fileclude must not be dispatchable:\n{}", rs
        );
        assert!(
            !rs.contains("_spass_compute_b_scale_c_1_f_1_f\""),
            "ownclude helper must not be dispatchable:\n{}", rs
        );
        assert!(
            rs.contains("if fname == \"_spass_compute_a_1_f\""),
            "public function must stay dispatchable:\n{}", rs
        );
    }

    /// Compile one source through both emitters.
    fn compile_both(src: &str) -> (String, String) {
        let module = Parser::parse_source(src, "<test>").expect("parse");
        let typed = analyze(&module).expect("analyse");
        (
            generate_c(&typed).expect("C codegen"),
            generate_rust(&typed).expect("Rust codegen"),
        )
    }

    /// a list literal and a list walk are real code in both
    /// backends, not a comment.
    #[test]
    fn list_literal_and_walk_emit_in_both_backends() {
        let (c, rs) = compile_both(
            "func f(): float { \
                 let xs: list<float> = [1.0, 2.0] \
                 let total: float = 0.0 \
                 for x in xs { total = total + x } \
                 return total }",
        );
        assert!(c.contains("typedef struct { unsigned char* data; int32_t len; int32_t stride; } SpassList;"));
        assert!(c.contains("SpassList xs = "), "C list binding missing:\n{}", c);
        assert!(c.contains("for (int32_t __sp_i = 0; __sp_i < (xs).len; ++__sp_i)"), "C list walk missing:\n{}", c);
        assert!(rs.contains("let mut xs: Vec<f64> = vec!["), "Rust list binding missing:\n{}", rs);
        assert!(rs.contains("for x in (xs).iter().cloned()"), "Rust list walk missing:\n{}", rs);
    }

    /// both random forms reach their runtime helpers.
    #[test]
    fn random_modes_emit_in_both_backends() {
        let (c, rs) = compile_both(
            "func one(x: float): float { return x + 1.0 } \
             func two(x: float): float { return x + 2.0 } \
             func pick_value(): float { return random(1.0, 2.0) } \
             func pick_function(x: float): float { return random(one, two)(x) }",
        );
        assert!(c.contains("spass_random_pick((const double[]){"), "C value pick missing:\n{}", c);
        assert!(c.contains("(*[])(double)"), "C function pick missing:\n{}", c);
        assert!(rs.contains("spass_random_pick(&["), "Rust value pick missing:\n{}", rs);
        assert!(rs.contains("spass_random_index(2)"), "Rust function pick missing:\n{}", rs);
    }

    /// `parallel` builds a batch and `await` tidies it
    /// into a list.
    #[test]
    fn parallel_batch_emits_in_both_backends() {
        let (c, rs) = compile_both(
            "func pair(a: float, b: float): float { return a + b } \
             func f(): float { \
                 let xs: list<float> = [1.0, 2.0] \
                 let t = parallel pair(xs, xs) \
                 let rs: list<float> = await(t) \
                 return rs[0] }",
        );
        assert!(c.contains("spass_parallel_spawn_args("), "C batch spawn missing:\n{}", c);
        assert!(c.contains("spass_parallel_await("), "C batch await missing:\n{}", c);
        assert!(rs.contains("spass_parallel_spawn("), "Rust batch spawn missing:\n{}", rs);
        assert!(rs.contains("spass_parallel_await("), "Rust batch await missing:\n{}", rs);
    }
}
